diffs.replacement:
{
  "name": "ŞantiyeHakediş - Taşeron Yönetim Sistemi",
  "description": "İnşaat taşeronlarının hakedişlerini, iş kalemlerini ve ödemelerini takip eden, Gemini yapay zeka destekli profesyonel mobil uyumlu hakediş uygulaması."
}

export enum UnitType {
  M2 = 'm²',
  M3 = 'm³',
  MT = 'mt',
  ADET = 'Adet',
  TON = 'Ton',
  KG = 'Kg',
  LS = 'Lump-sum'
}

export interface WorkItem {
  id: string;
  description: string;
  unit: UnitType;
  unitPrice: number;
  contractQuantity: number;
  completedQuantity: number;
}

export interface Subcontractor {
  id: string;
  name: string;
  trade: string;
  contractDate: string;
  totalContractValue: number;
  workItems: WorkItem[];
  progressPayments: ProgressPayment[];
}

export interface ProgressPayment {
  id: string;
  number: number; // Hakediş No
  date: string;
  subcontractorId: string;
  items: {
    workItemId: string;
    thisPeriodQuantity: number;
    cumulativeQuantity: number;
  }[];
  summary: {
    previousTotal: number;
    currentTotal: number;
    cumulativeTotal: number;
    retentionAmount: number; // Kesinti
    vatAmount: number; // KDV
    netPayable: number;
  };
}

export interface AppState {
  subcontractors: Subcontractor[];
}

import { GoogleGenAI, Type } from "@google/genai";
import { Subcontractor, ProgressPayment } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeProgress = async (subcontractor: Subcontractor) => {
  const prompt = `
    Aşağıdaki taşeronun hakediş verilerini analiz et ve Türkçe olarak profesyonel bir inşaat mühendisi gibi yorumla.
    Taşeron: ${subcontractor.name} (${subcontractor.trade})
    Sözleşme Bedeli: ${subcontractor.totalContractValue} TL
    İş Kalemleri: ${JSON.stringify(subcontractor.workItems)}
    Yapılan Hakedişler: ${JSON.stringify(subcontractor.progressPayments)}

    Lütfen şunları belirt:
    1. İşin genel ilerleme yüzdesi.
    2. Bütçe aşımı veya verimlilik uyarısı var mı?
    3. Gelecek hakediş için projeksiyon ve tavsiyeler.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini analysis error:", error);
    return "Analiz sırasında bir hata oluştu.";
  }
};

export const parseWorkItemsFromText = async (text: string) => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Metinden iş kalemlerini çıkar ve JSON formatında döndür. Metin: ${text}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            description: { type: Type.STRING },
            unit: { type: Type.STRING, enum: ["m²", "m³", "mt", "Adet", "Ton", "Kg", "Lump-sum"] },
            unitPrice: { type: Type.NUMBER },
            contractQuantity: { type: Type.NUMBER },
          },
          required: ["description", "unit", "unitPrice", "contractQuantity"]
        }
      }
    }
  });
  return JSON.parse(response.text);
};

import React from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  Cell, PieChart, Pie 
} from 'recharts';
import { Subcontractor } from '../types';
import { TrendingUp, Users, ClipboardCheck, Wallet } from 'lucide-react';

interface DashboardProps {
  subcontractors: Subcontractor[];
}

const Dashboard: React.FC<DashboardProps> = ({ subcontractors }) => {
  const totalContract = subcontractors.reduce((sum, s) => sum + s.totalContractValue, 0);
  const totalPaid = subcontractors.reduce((sum, s) => {
    const lastPayment = s.progressPayments[s.progressPayments.length - 1];
    return sum + (lastPayment?.summary.cumulativeTotal || 0);
  }, 0);

  const chartData = subcontractors.map(s => {
    const paid = s.progressPayments.reduce((sum, p) => sum + p.summary.currentTotal, 0);
    return {
      name: s.name.split(' ')[0],
      Sözleşme: s.totalContractValue,
      Ödenen: paid
    };
  });

  const progressPercent = totalContract > 0 ? (totalPaid / totalContract) * 100 : 0;

  return (
    <div className="space-y-6 pb-20">
      <h1 className="text-2xl font-bold text-slate-800 px-2">Genel Bakış</h1>

      {/* Metrics Grid */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 flex flex-col items-center text-center">
          <div className="bg-blue-50 p-2 rounded-full mb-2">
            <Users className="text-blue-600 w-5 h-5" />
          </div>
          <span className="text-xs text-slate-500 font-medium">Taşeron</span>
          <span className="text-lg font-bold text-slate-800">{subcontractors.length}</span>
        </div>
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 flex flex-col items-center text-center">
          <div className="bg-green-50 p-2 rounded-full mb-2">
            <TrendingUp className="text-green-600 w-5 h-5" />
          </div>
          <span className="text-xs text-slate-500 font-medium">İlerleme</span>
          <span className="text-lg font-bold text-slate-800">%{progressPercent.toFixed(1)}</span>
        </div>
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 flex flex-col items-center text-center col-span-2">
          <div className="bg-indigo-50 p-2 rounded-full mb-2">
            <Wallet className="text-indigo-600 w-5 h-5" />
          </div>
          <span className="text-xs text-slate-500 font-medium">Toplam Sözleşme Bedeli</span>
          <span className="text-xl font-bold text-slate-800">{totalContract.toLocaleString('tr-TR')} TL</span>
        </div>
      </div>

      {/* Charts Section */}
      <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 h-64">
        <h3 className="text-sm font-semibold text-slate-700 mb-4">Taşeron Bazlı Bütçe Dağılımı</h3>
        <ResponsiveContainer width="100%" height="80%">
          <BarChart data={chartData}>
            <CartesianGrid strokeDasharray="3 3" vertical={false} />
            <XAxis dataKey="name" fontSize={10} />
            <YAxis fontSize={10} hide />
            <Tooltip />
            <Bar dataKey="Sözleşme" fill="#94a3b8" radius={[4, 4, 0, 0]} />
            <Bar dataKey="Ödenen" fill="#3b82f6" radius={[4, 4, 0, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </div>

      <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
        <h3 className="text-sm font-semibold text-slate-700 mb-2">Son Aktiviteler</h3>
        <div className="space-y-3">
          {subcontractors.flatMap(s => s.progressPayments).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0,3).map(p => {
             const sub = subcontractors.find(s => s.id === p.subcontractorId);
             return (
               <div key={p.id} className="flex justify-between items-center py-2 border-b border-slate-50 last:border-0">
                  <div className="flex flex-col">
                    <span className="text-sm font-medium text-slate-700">{sub?.name}</span>
                    <span className="text-xs text-slate-400">Hakediş #{p.number} • {new Date(p.date).toLocaleDateString('tr-TR')}</span>
                  </div>
                  <span className="text-sm font-bold text-green-600">+{p.summary.netPayable.toLocaleString('tr-TR')} TL</span>
               </div>
             )
          })}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Subcontractor } from '../types';
import { Search, Plus, UserCircle, ChevronRight } from 'lucide-react';

interface SubcontractorListProps {
  subcontractors: Subcontractor[];
  onSelect: (id: string) => void;
  onAdd: () => void;
}

const SubcontractorList: React.FC<SubcontractorListProps> = ({ subcontractors, onSelect, onAdd }) => {
  const [searchTerm, setSearchTerm] = useState('');

  const filtered = subcontractors.filter(s => 
    s.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    s.trade.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-slate-800">Taşeronlar</h1>
        <button 
          onClick={onAdd}
          className="bg-blue-600 text-white p-2 rounded-xl shadow-lg active:scale-95 transition-all"
        >
          <Plus className="w-6 h-6" />
        </button>
      </div>

      <div className="relative mb-6">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
        <input 
          type="text" 
          placeholder="İsim veya branş ara..." 
          className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500 shadow-sm transition-all"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="space-y-3">
        {filtered.map(sub => {
          const lastPayment = sub.progressPayments[sub.progressPayments.length - 1];
          const progress = sub.totalContractValue > 0 
            ? ((lastPayment?.summary.cumulativeTotal || 0) / sub.totalContractValue) * 100 
            : 0;

          return (
            <button
              key={sub.id}
              onClick={() => onSelect(sub.id)}
              className="w-full text-left bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-4 active:bg-slate-50 transition-colors"
            >
              <div className="w-12 h-12 bg-blue-100 rounded-full flex items-center justify-center text-blue-600">
                <UserCircle className="w-8 h-8" />
              </div>
              <div className="flex-1 min-w-0">
                <h3 className="font-bold text-slate-800 truncate">{sub.name}</h3>
                <p className="text-xs text-slate-500 mb-2">{sub.trade}</p>
                <div className="w-full bg-slate-100 h-1.5 rounded-full overflow-hidden">
                  <div 
                    className="bg-blue-600 h-full rounded-full transition-all duration-1000" 
                    style={{ width: `${Math.min(100, progress)}%` }}
                  />
                </div>
              </div>
              <ChevronRight className="text-slate-300 w-5 h-5" />
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default SubcontractorList;

import React, { useState } from 'react';
import { Subcontractor, ProgressPayment } from '../types';
import { ArrowLeft, Plus, History, Sparkles, FileText, Info } from 'lucide-react';
import { analyzeProgress } from '../services/geminiService';

interface SubcontractorDetailProps {
  subcontractor: Subcontractor;
  onBack: () => void;
  onNewPayment: () => void;
}

const SubcontractorDetail: React.FC<SubcontractorDetailProps> = ({ subcontractor, onBack, onNewPayment }) => {
  const [activeTab, setActiveTab] = useState<'items' | 'payments'>('items');
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    const report = await analyzeProgress(subcontractor);
    setAiReport(report || "Analiz yapılamadı.");
    setIsAnalyzing(false);
  };

  const lastPayment = subcontractor.progressPayments[subcontractor.progressPayments.length - 1];
  const totalPaid = lastPayment?.summary.cumulativeTotal || 0;
  const progressPercent = (totalPaid / subcontractor.totalContractValue) * 100;

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-500">
      <div className="flex items-center gap-3">
        <button onClick={onBack} className="p-2 bg-white rounded-xl shadow-sm"><ArrowLeft className="w-5 h-5" /></button>
        <div>
          <h2 className="text-xl font-bold text-slate-800">{subcontractor.name}</h2>
          <span className="text-xs text-slate-500 uppercase tracking-wider font-semibold">{subcontractor.trade}</span>
        </div>
      </div>

      {/* Summary Card */}
      <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-6 rounded-3xl text-white shadow-xl">
        <div className="flex justify-between items-start mb-4">
          <div>
            <p className="text-blue-100 text-xs font-medium">Sözleşme Toplamı</p>
            <p className="text-2xl font-bold">{subcontractor.totalContractValue.toLocaleString('tr-TR')} TL</p>
          </div>
          <div className="bg-white/20 p-2 rounded-xl backdrop-blur-sm">
            <Info className="w-5 h-5" />
          </div>
        </div>
        <div className="space-y-2">
          <div className="flex justify-between text-xs">
            <span>İlerleme Durumu</span>
            <span>%{progressPercent.toFixed(1)}</span>
          </div>
          <div className="w-full bg-white/20 h-2 rounded-full overflow-hidden">
            <div className="bg-white h-full transition-all duration-1000" style={{ width: `${progressPercent}%` }} />
          </div>
        </div>
      </div>

      {/* AI Assistant Button */}
      <button 
        onClick={handleAnalyze}
        disabled={isAnalyzing}
        className="w-full bg-white border border-indigo-100 p-4 rounded-2xl shadow-sm flex items-center justify-between group active:scale-95 transition-all"
      >
        <div className="flex items-center gap-3">
          <div className="p-2 bg-indigo-50 rounded-lg text-indigo-600">
            <Sparkles className={`w-5 h-5 ${isAnalyzing ? 'animate-pulse' : ''}`} />
          </div>
          <div className="text-left">
            <p className="text-sm font-bold text-slate-800">Yapay Zeka Danışmanı</p>
            <p className="text-xs text-slate-500">Hakediş durumunu analiz et</p>
          </div>
        </div>
        <div className="text-indigo-600 text-xs font-bold bg-indigo-50 px-3 py-1 rounded-full">
          {isAnalyzing ? 'Analiz Ediliyor...' : 'Analiz Et'}
        </div>
      </button>

      {aiReport && (
        <div className="bg-indigo-50 p-4 rounded-2xl border border-indigo-100 text-sm text-indigo-900 leading-relaxed whitespace-pre-wrap animate-in slide-in-from-top duration-300">
          <div className="flex items-center gap-2 mb-2 font-bold text-indigo-600">
            <Sparkles className="w-4 h-4" />
            Gemini Analiz Raporu
          </div>
          {aiReport}
        </div>
