                       </div>
                       <div>
                          <p className="text-sm font-bold text-slate-800">Hakediş #{p.number}</p>
                          <p className="text-xs text-slate-400">{new Date(p.date).toLocaleDateString('tr-TR')}</p>
                       </div>
                    </div>
                    <span className="text-sm font-bold text-green-600">{p.summary.netPayable.toLocaleString('tr-TR')} TL</span>
                  </div>
                  <div className="grid grid-cols-3 gap-2 border-t border-slate-50 pt-3 mt-1">
                    <div className="text-center">
                      <p className="text-[10px] text-slate-400 uppercase">Önceki Toplam</p>
