export default SubcontractorDetail;

import React, { useState } from 'react';
import { Subcontractor, ProgressPayment, WorkItem } from '../types';
import { ArrowLeft, Check, Save } from 'lucide-react';

interface ProgressPaymentFormProps {
  subcontractor: Subcontractor;
  onCancel: () => void;
  onSave: (payment: ProgressPayment) => void;
}

const ProgressPaymentForm: React.FC<ProgressPaymentFormProps> = ({ subcontractor, onCancel, onSave }) => {
  const [quantities, setQuantities] = useState<Record<string, number>>(
    subcontractor.workItems.reduce((acc, item) => ({ ...acc, [item.id]: 0 }), {})
  );

  const [vatRate, setVatRate] = useState(20);
  const [retentionRate, setRetentionRate] = useState(5);

  const calculateSummary = () => {
    let currentTotal = 0;
    const items = subcontractor.workItems.map(item => {
      const thisPeriod = quantities[item.id] || 0;
      const prevPayments = subcontractor.progressPayments.flatMap(p => p.items).filter(i => i.workItemId === item.id);
      const prevTotal = prevPayments.reduce((sum, i) => sum + i.thisPeriodQuantity, 0);

      currentTotal += thisPeriod * item.unitPrice;

      return {
        workItemId: item.id,
        thisPeriodQuantity: thisPeriod,
        cumulativeQuantity: prevTotal + thisPeriod
      };
    });

    const lastPayment = subcontractor.progressPayments[subcontractor.progressPayments.length - 1];
    const previousTotal = lastPayment?.summary.cumulativeTotal || 0;
    const cumulativeTotal = previousTotal + currentTotal;
    const retentionAmount = (currentTotal * retentionRate) / 100;
    const vatAmount = (currentTotal * vatRate) / 100;
    const netPayable = currentTotal - retentionAmount + vatAmount;

    return {
      previousTotal,
      currentTotal,
      cumulativeTotal,
      retentionAmount,
      vatAmount,
      netPayable,
      items
    };
  };

  const summary = calculateSummary();

  const handleSave = () => {
    const newPayment: ProgressPayment = {
      id: Math.random().toString(36).substr(2, 9),
      number: subcontractor.progressPayments.length + 1,
      date: new Date().toISOString(),
      subcontractorId: subcontractor.id,
      items: summary.items,
      summary: {
        previousTotal: summary.previousTotal,
        currentTotal: summary.currentTotal,
        cumulativeTotal: summary.cumulativeTotal,
        retentionAmount: summary.retentionAmount,
        vatAmount: summary.vatAmount,
        netPayable: summary.netPayable
      }
    };
    onSave(newPayment);
  };

  return (
    <div className="space-y-6 pb-20 animate-in slide-in-from-bottom duration-500">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <button onClick={onCancel} className="p-2 bg-white rounded-xl shadow-sm"><ArrowLeft className="w-5 h-5" /></button>
          <h2 className="text-xl font-bold text-slate-800">Hakediş Düzenle</h2>
        </div>
        <button 
          onClick={handleSave}
          className="bg-blue-600 text-white px-4 py-2 rounded-xl flex items-center gap-2 font-bold shadow-lg shadow-blue-200 active:scale-95 transition-all"
        >
          <Save className="w-4 h-4" /> Kaydet
        </button>
      </div>

      <div className="bg-blue-50 p-4 rounded-2xl border border-blue-100 flex items-center gap-4">
        <div className="bg-white w-10 h-10 rounded-full flex items-center justify-center text-blue-600 font-bold shadow-sm">
          #{subcontractor.progressPayments.length + 1}
        </div>
        <div>
          <p className="text-xs text-blue-600 font-bold uppercase tracking-wide">Sıradaki Hakediş No</p>
          <p className="text-sm text-slate-600">{new Date().toLocaleDateString('tr-TR')}</p>
        </div>
      </div>

      <div className="space-y-4">
        <h3 className="text-sm font-bold text-slate-700 uppercase tracking-wider ml-1">Yapılan İş Miktarları</h3>
        {subcontractor.workItems.map(item => {
           const prevPayments = subcontractor.progressPayments.flatMap(p => p.items).filter(i => i.workItemId === item.id);
           const prevTotal = prevPayments.reduce((sum, i) => sum + i.thisPeriodQuantity, 0);
           const remaining = item.contractQuantity - prevTotal;

           return (
            <div key={item.id} className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm space-y-3">
              <div className="flex justify-between items-start">
                <p className="text-sm font-bold text-slate-800">{item.description}</p>
                <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded-md font-bold uppercase">{item.unit}</span>
              </div>
              <div className="flex gap-4 items-center">
                <div className="flex-1">
                  <p className="text-[10px] text-slate-400 uppercase mb-1">Miktar Girişi</p>
                  <input 
                    type="number" 
                    value={quantities[item.id]} 
                    onChange={(e) => setQuantities({ ...quantities, [item.id]: Number(e.target.value) })}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-700"
                  />
                </div>
                <div className="text-right flex flex-col justify-end h-full pt-4">
                   <p className="text-[10px] text-slate-400 uppercase">Sözleşme Kalanı</p>
                   <p className="text-sm font-bold text-slate-600">{remaining} {item.unit}</p>
