import { GoogleGenAI, Type } from "@google/genai";
import { Subcontractor, ProgressPayment } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeProgress = async (subcontractor: Subcontractor) => {
  const prompt = `
    Aşağıdaki taşeronun hakediş verilerini analiz et ve Türkçe olarak profesyonel bir inşaat mühendisi gibi yorumla.
    Taşeron: ${subcontractor.name} (${subcontractor.trade})
    Sözleşme Bedeli: ${subcontractor.totalContractValue} TL
    İş Kalemleri: ${JSON.stringify(subcontractor.workItems)}
    Yapılan Hakedişler: ${JSON.stringify(subcontractor.progressPayments)}

    Lütfen şunları belirt:
    1. İşin genel ilerleme yüzdesi.
    2. Bütçe aşımı veya verimlilik uyarısı var mı?
    3. Gelecek hakediş için projeksiyon ve tavsiyeler.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini analysis error:", error);
    return "Analiz sırasında bir hata oluştu.";
  }
};

export const analyzeProjectHealth = async (subcontractors: Subcontractor[]) => {
  const summaryData = subcontractors.map(s => ({
    name: s.name,
    trade: s.trade,
    contractValue: s.totalContractValue,
    paidTotal: s.progressPayments.reduce((sum, p) => sum + p.summary.currentTotal, 0),
    lastPaymentDate: s.progressPayments[s.progressPayments.length - 1]?.date
  }));

  const prompt = `
    Tüm şantiyenin taşeron hakediş verilerini analiz et. 
    Veriler: ${JSON.stringify(summaryData)}

    Bir proje müdürü perspektifiyle Türkçe olarak:
    1. Projenin genel mali sağlığını değerlendir.
    2. En çok ödeme yapılan kalemleri ve riskli gördüğün taşeronları belirt.
    3. Nakit akışı yönetimi için stratejik tavsiyeler ver.
    Kısa, öz ve profesyonel bir dil kullan.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Project health analysis error:", error);
    return "Proje analizi yapılamadı.";
  }
};

export const parseWorkItemsFromText = async (text: string) => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Metinden iş kalemlerini çıkar ve JSON formatında döndür. Metin: ${text}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            description: { type: Type.STRING },
            unit: { type: Type.STRING, enum: ["m²", "m³", "mt", "Adet", "Ton", "Kg", "Lump-sum"] },
            unitPrice: { type: Type.NUMBER },
            contractQuantity: { type: Type.NUMBER },
          },
          required: ["description", "unit", "unitPrice", "contractQuantity"]
        }
      }
    }
  });
  return JSON.parse(response.text);
};

import React, { useState, useMemo } from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Legend, Cell 
} from 'recharts';
import { Subcontractor } from '../types';
import { Calendar, TrendingUp, PieChart as PieChartIcon, Sparkles, Filter, ChevronDown } from 'lucide-react';
import { analyzeProjectHealth } from '../services/geminiService';

interface ReportsProps {
  subcontractors: Subcontractor[];
}

type Range = '30d' | '90d' | 'all';

const Reports: React.FC<ReportsProps> = ({ subcontractors }) => {
  const [range, setRange] = useState<Range>('all');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiInsight, setAiInsight] = useState<string | null>(null);

  const filteredData = useMemo(() => {
    const now = new Date();
    const rangeLimit = range === '30d' ? 30 : range === '90d' ? 90 : Infinity;

    const allPayments = subcontractors.flatMap(s => 
      s.progressPayments.map(p => ({
        ...p,
        subName: s.name,
        dateObj: new Date(p.date)
      }))
    ).filter(p => {
      if (range === 'all') return true;
      const diffDays = (now.getTime() - p.dateObj.getTime()) / (1000 * 3600 * 24);
      return diffDays <= rangeLimit;
    });

    return allPayments.sort((a, b) => a.dateObj.getTime() - b.dateObj.getTime());
  }, [subcontractors, range]);

  const stats = useMemo(() => {
    const totalPaid = filteredData.reduce((sum, p) => sum + p.summary.currentTotal, 0);
    const totalRetention = filteredData.reduce((sum, p) => sum + p.summary.retentionAmount, 0);
    const paymentCount = filteredData.length;
    return { totalPaid, totalRetention, paymentCount };
  }, [filteredData]);

  const trendData = useMemo(() => {
    // Group by month
    const groups: Record<string, number> = {};
    filteredData.forEach(p => {
      const month = p.dateObj.toLocaleDateString('tr-TR', { month: 'short', year: '2-digit' });
      groups[month] = (groups[month] || 0) + p.summary.currentTotal;
    });
    return Object.entries(groups).map(([name, total]) => ({ name, total }));
  }, [filteredData]);

  const subProgressData = useMemo(() => {
    return subcontractors.map(s => {
      const paid = s.progressPayments.reduce((sum, p) => sum + p.summary.currentTotal, 0);
      return {
        name: s.name.split(' ')[0],
        Tamamlanan: Math.round((paid / s.totalContractValue) * 100) || 0,
        Kalan: Math.max(0, 100 - Math.round((paid / s.totalContractValue) * 100))
      };
    }).sort((a, b) => b.Tamamlanan - a.Tamamlanan);
  }, [subcontractors]);

  const handleProjectAnalysis = async () => {
    setIsAnalyzing(true);
    const result = await analyzeProjectHealth(subcontractors);
    setAiInsight(result);
    setIsAnalyzing(false);
  };

  return (
    <div className="space-y-6 pb-24 animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold text-slate-800">Gelişmiş Raporlar</h1>
        <div className="flex bg-white border border-slate-200 p-1 rounded-xl shadow-sm">
          {(['30d', '90d', 'all'] as Range[]).map((r) => (
            <button
              key={r}
              onClick={() => setRange(r)}
              className={`px-3 py-1.5 text-[10px] font-bold rounded-lg transition-all ${range === r ? 'bg-blue-600 text-white' : 'text-slate-400'}`}
            >
              {r === '30d' ? '30 GÜN' : r === '90d' ? '90 GÜN' : 'TÜMÜ'}
            </button>
          ))}
        </div>
      </div>

      {/* Quick Stats Grid */}
      <div className="grid grid-cols-2 gap-3">
        <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm">
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">Dönemlik Ödeme</p>
          <p className="text-lg font-black text-blue-600">{stats.totalPaid.toLocaleString('tr-TR')} TL</p>
          <div className="flex items-center gap-1 mt-1 text-[10px] text-green-500 font-bold">
            <TrendingUp className="w-3 h-3" /> {stats.paymentCount} Hakediş
          </div>
        </div>
        <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm">
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">Dönemlik Teminat</p>
          <p className="text-lg font-black text-slate-700">{stats.totalRetention.toLocaleString('tr-TR')} TL</p>
          <p className="text-[10px] text-slate-400 mt-1 italic">Vadesi beklenen tutar</p>
        </div>
      </div>

      {/* AI Project Insight */}
      <div className="bg-gradient-to-r from-indigo-600 to-purple-600 p-5 rounded-3xl text-white shadow-xl shadow-indigo-100 overflow-hidden relative group">
        <div className="absolute -right-4 -top-4 opacity-10 group-hover:scale-110 transition-transform">
          <Sparkles className="w-24 h-24" />
        </div>
        <div className="relative z-10 space-y-3">
          <div className="flex items-center gap-2">
            <Sparkles className="w-5 h-5 text-indigo-200" />
            <h3 className="font-bold">Gemini Pro Proje Analizi</h3>
          </div>
          <p className="text-xs text-indigo-100 leading-relaxed">
            Tüm taşeron verilerini yapay zeka ile analiz ederek genel gidişat hakkında stratejik öngörü alın.
          </p>
          {!aiInsight ? (
            <button 
              onClick={handleProjectAnalysis}
              disabled={isAnalyzing}
              className="bg-white/20 hover:bg-white/30 backdrop-blur-md px-4 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-2"
            >
              {isAnalyzing ? 'Veriler İşleniyor...' : 'Analizi Başlat'}
            </button>
          ) : (
            <div className="bg-white/10 backdrop-blur-md p-4 rounded-2xl text-xs leading-relaxed border border-white/10 animate-in slide-in-from-top duration-500 max-h-48 overflow-y-auto no-scrollbar">
              {aiInsight}
