          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">Dönemlik Teminat</p>
          <p className="text-lg font-black text-slate-700">{stats.totalRetention.toLocaleString('tr-TR')} TL</p>
          <p className="text-[10px] text-slate-400 mt-1 italic">Vadesi beklenen tutar</p>
        </div>
      </div>

      {/* AI Project Insight */}
      <div className="bg-gradient-to-r from-indigo-600 to-purple-600 p-5 rounded-3xl text-white shadow-xl shadow-indigo-100 overflow-hidden relative group">
        <div className="absolute -right-4 -top-4 opacity-10 group-hover:scale-110 transition-transform">
