import React, { useState } from 'react';
import { Subcontractor, ProgressPayment } from '../types';
import { ArrowLeft, Plus, Sparkles, FileText, Info, TrendingUp, Calendar } from 'lucide-react';
import { analyzeProgress } from '../services/geminiService';

interface SubcontractorDetailProps {
  subcontractor: Subcontractor;
  onBack: () => void;
  onNewPayment: () => void;
}

const SubcontractorDetail: React.FC<SubcontractorDetailProps> = ({ subcontractor, onBack, onNewPayment }) => {
  const [activeTab, setActiveTab] = useState<'items' | 'payments'>('items');
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    const report = await analyzeProgress(subcontractor);
    setAiReport(report || "Analiz yapılamadı.");
    setIsAnalyzing(false);
  };

  const lastPayment = subcontractor.progressPayments[subcontractor.progressPayments.length - 1];
  const totalPaid = lastPayment?.summary.cumulativeTotal || 0;
  const progressPercent = (totalPaid / subcontractor.totalContractValue) * 100;

  return (
    <div className="space-y-6 pb-24 animate-in fade-in duration-500 max-w-2xl mx-auto">
      {/* Top Bar */}
      <div className="flex items-center gap-3">
        <button onClick={onBack} className="p-2 bg-white rounded-xl shadow-sm border border-slate-100 hover:bg-slate-50 transition-colors">
          <ArrowLeft className="w-5 h-5 text-slate-600" />
        </button>
        <div>
          <h2 className="text-xl font-bold text-slate-800">{subcontractor.name}</h2>
          <div className="flex items-center gap-2">
            <span className="text-[10px] bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full font-bold uppercase tracking-wider">{subcontractor.trade}</span>
            <span className="text-[10px] text-slate-400 font-medium">Sözleşme: {new Date(subcontractor.contractDate).toLocaleDateString('tr-TR')}</span>
          </div>
        </div>
      </div>

      {/* Summary Card */}
      <div className="bg-gradient-to-br from-slate-800 to-slate-900 p-6 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden group">
        <div className="absolute top-0 right-0 p-8 opacity-10 rotate-12 group-hover:rotate-45 transition-transform duration-700">
           <TrendingUp className="w-32 h-32" />
        </div>
        <div className="relative z-10">
          <div className="flex justify-between items-start mb-6">
            <div>
              <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest mb-1">Toplam Sözleşme Bedeli</p>
              <p className="text-2xl font-black">{subcontractor.totalContractValue.toLocaleString('tr-TR')} <span className="text-sm font-bold text-slate-500">TL</span></p>
            </div>
            <div className="bg-white/10 p-2.5 rounded-2xl backdrop-blur-md border border-white/10">
              <Info className="w-5 h-5 text-blue-400" />
            </div>
          </div>
          <div className="space-y-3">
            <div className="flex justify-between items-end">
              <div>
                <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest mb-1">Tamamlanan İmalat</p>
                <p className="text-lg font-bold text-blue-400">{totalPaid.toLocaleString('tr-TR')} TL</p>
              </div>
              <span className="text-2xl font-black text-white">%{progressPercent.toFixed(1)}</span>
            </div>
            <div className="w-full bg-white/10 h-3 rounded-full overflow-hidden border border-white/5">
              <div 
                className="bg-blue-500 h-full transition-all duration-1000 ease-out shadow-[0_0_15px_rgba(59,130,246,0.5)]" 
                style={{ width: `${Math.min(100, progressPercent)}%` }} 
              />
            </div>
          </div>
        </div>
      </div>

      {/* AI Assistant Button */}
      <button 
        onClick={handleAnalyze}
        disabled={isAnalyzing}
        className="w-full bg-white border border-indigo-100 p-5 rounded-3xl shadow-sm flex items-center justify-between group active:scale-[0.98] transition-all hover:shadow-md hover:border-indigo-200"
      >
        <div className="flex items-center gap-4">
          <div className="p-3 bg-indigo-50 rounded-2xl text-indigo-600 group-hover:rotate-12 transition-transform">
            <Sparkles className={`w-6 h-6 ${isAnalyzing ? 'animate-pulse' : ''}`} />
          </div>
          <div className="text-left">
            <p className="text-sm font-bold text-slate-800">Gemini Teknik Analiz</p>
            <p className="text-[10px] text-slate-500 font-medium">İlerleme ve verimlilik raporu al</p>
          </div>
        </div>
        <div className="text-indigo-600 text-[10px] font-black bg-indigo-50 px-4 py-1.5 rounded-full uppercase tracking-tighter">
          {isAnalyzing ? 'Analiz Ediliyor...' : 'Rapor Oluştur'}
        </div>
      </button>

      {aiReport && (
        <div className="bg-indigo-50/50 p-5 rounded-[2rem] border border-indigo-100 text-sm text-indigo-900 leading-relaxed whitespace-pre-wrap animate-in slide-in-from-top duration-300 relative">
          <div className="flex items-center gap-2 mb-3 font-black text-indigo-600 uppercase text-[10px] tracking-widest">
            <Sparkles className="w-4 h-4" />
            Gemini Analiz Sonucu
          </div>
          {aiReport}
        </div>
      )}

      {/* Tabs */}
      <div className="flex bg-white p-1.5 rounded-[1.5rem] border border-slate-200 shadow-sm">
        <button 
          onClick={() => setActiveTab('items')}
          className={`flex-1 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'items' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}
        >
          İş Kalemleri
        </button>
        <button 
          onClick={() => setActiveTab('payments')}
          className={`flex-1 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'payments' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}
        >
          Hakedişler
        </button>
      </div>

      {/* Content Area */}
      <div className="space-y-4 min-h-[300px]">
        {activeTab === 'items' ? (
          <div className="grid grid-cols-1 gap-3">
            {subcontractor.workItems.map(item => {
               const paidQty = subcontractor.progressPayments.reduce((sum, p) => {
                 const pItem = p.items.find(i => i.workItemId === item.id);
                 return sum + (pItem?.thisPeriodQuantity || 0);
               }, 0);
               const itemProgress = (paidQty / item.contractQuantity) * 100;

               return (
                <div key={item.id} className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm hover:border-blue-200 transition-colors">
                  <div className="flex justify-between items-start mb-4">
                    <div className="flex-1">
                      <p className="text-sm font-bold text-slate-800 leading-tight">{item.description}</p>
                      <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{item.unitPrice.toLocaleString('tr-TR')} TL / {item.unit}</span>
                    </div>
                    <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-1 rounded-md font-black uppercase">{item.unit}</span>
                  </div>

                  <div className="space-y-2">
                    <div className="flex justify-between items-center text-[10px] font-bold">
                      <span className="text-slate-400">İLERLEME</span>
                      <span className="text-slate-700">{paidQty} / {item.contractQuantity}</span>
                    </div>
                    <div className="w-full bg-slate-50 h-1.5 rounded-full overflow-hidden border border-slate-100">
                      <div 
                        className={`h-full transition-all duration-700 ${itemProgress > 100 ? 'bg-red-500' : 'bg-blue-500'}`} 
                        style={{ width: `${Math.min(100, itemProgress)}%` }} 
                      />
                    </div>
                  </div>
                </div>
               );
            })}
          </div>
        ) : (
          <div className="space-y-4">
             <button 
                onClick={onNewPayment}
                className="w-full py-6 border-2 border-dashed border-blue-200 bg-blue-50/20 rounded-[2rem] text-blue-600 font-black text-sm uppercase tracking-widest flex items-center justify-center gap-3 hover:bg-blue-50 active:scale-95 transition-all group"
              >
                <div className="p-2 bg-blue-600 rounded-xl text-white group-hover:scale-110 transition-transform">
                  <Plus className="w-5 h-5" />
                </div>
                YENİ HAKEDİŞ OLUŞTUR
              </button>

              {subcontractor.progressPayments.length === 0 ? (
                <div className="text-center py-12 px-6">
                   <div className="bg-slate-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                      <FileText className="text-slate-300 w-8 h-8" />
                   </div>
                   <p className="text-slate-400 text-sm font-medium">Henüz bir hakediş kaydı bulunmuyor.</p>
                </div>
              ) : (
                subcontractor.progressPayments.sort((a,b) => b.number - a.number).map(p => (
                  <div key={p.id} className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm relative overflow-hidden group hover:border-green-100 transition-colors">
                    <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:scale-110 transition-transform">
                       <FileText className="w-16 h-16" />
                    </div>
                    <div className="flex justify-between items-center mb-5 relative z-10">
                      <div className="flex items-center gap-4">
                        <div className="bg-green-50 p-3 rounded-2xl border border-green-100">
                           <FileText className="text-green-600 w-6 h-6" />
                        </div>
                        <div>
                           <p className="text-sm font-black text-slate-800">Hakediş #{p.number}</p>
                           <div className="flex items-center gap-2 text-[10px] text-slate-400 font-bold uppercase mt-0.5">
                             <Calendar className="w-3 h-3" />
                             {new Date(p.date).toLocaleDateString('tr-TR')}
                           </div>
                        </div>
                      </div>
                      <div className="text-right">
                        <p className="text-lg font-black text-green-600">{p.summary.netPayable.toLocaleString('tr-TR')} TL</p>
                        <p className="text-[9px] font-bold text-slate-400 uppercase">NET ÖDENEN</p>
                      </div>
                    </div>

                    <div className="grid grid-cols-3 gap-3 bg-slate-50/80 p-3 rounded-2xl relative z-10 border border-slate-100/50">
                      <div className="text-center">
                        <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter">Önceki Toplam</p>
                        <p className="text-[11px] font-bold text-slate-600">{p.summary.previousTotal.toLocaleString('tr-TR')} TL</p>
                      </div>
                      <div className="text-center border-x border-slate-200">
                        <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter">Bu Dönem</p>
                        <p className="text-[11px] font-black text-blue-600">{p.summary.currentTotal.toLocaleString('tr-TR')} TL</p>
                      </div>
                      <div className="text-center">
                        <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter">Kümülatif</p>
                        <p className="text-[11px] font-black text-slate-800">{p.summary.cumulativeTotal.toLocaleString('tr-TR')} TL</p>
                      </div>
                    </div>
                  </div>
                ))
              )}
          </div>
        )}
      </div>
    </div>
  );
};

