import React, { useState, useEffect } from 'react';
import { Subcontractor, ProgressPayment } from './types';
import Dashboard from './components/Dashboard';
import SubcontractorList from './components/SubcontractorList';
import SubcontractorDetail from './components/SubcontractorDetail';
import ProgressPaymentForm from './components/ProgressPaymentForm';
import AddSubcontractorForm from './components/AddSubcontractorForm';
import Reports from './components/Reports';
import { LayoutDashboard, Users, BarChart3, Settings } from 'lucide-react';

const STORAGE_KEY = 'hakedis_app_data';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<'dashboard' | 'subcontractors' | 'reports' | 'detail' | 'payment-form' | 'add-sub'>('dashboard');
  const [subcontractors, setSubcontractors] = useState<Subcontractor[]>([]);
  const [selectedSubId, setSelectedSubId] = useState<string | null>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      setSubcontractors(JSON.parse(saved));
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(subcontractors));
  }, [subcontractors]);

  const selectedSub = subcontractors.find(s => s.id === selectedSubId);

  const handleAddSubcontractor = (newSub: Subcontractor) => {
    setSubcontractors([...subcontractors, newSub]);
    setActiveView('subcontractors');
  };

  const handleUpdateSubcontractor = (updatedSub: Subcontractor) => {
    setSubcontractors(prev => prev.map(s => s.id === updatedSub.id ? updatedSub : s));
  };

  const handleAddPayment = (payment: ProgressPayment) => {
    setSubcontractors(prev => prev.map(s => {
      if (s.id === payment.subcontractorId) {
        return {
          ...s,
          progressPayments: [...s.progressPayments, payment]
        };
      }
      return s;
    }));
    setActiveView('detail');
  };

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return <Dashboard subcontractors={subcontractors} />;
      case 'subcontractors':
        return (
          <SubcontractorList 
            subcontractors={subcontractors} 
            onSelect={(id) => { setSelectedSubId(id); setActiveView('detail'); }} 
            onAdd={() => setActiveView('add-sub')}
          />
        );
      case 'reports':
        return <Reports subcontractors={subcontractors} />;
      case 'detail':
        return selectedSub ? (
          <SubcontractorDetail 
            subcontractor={selectedSub} 
            onBack={() => setActiveView('subcontractors')} 
            onNewPayment={() => setActiveView('payment-form')}
            onUpdate={handleUpdateSubcontractor}
          />
        ) : null;
      case 'payment-form':
        return selectedSub ? (
          <ProgressPaymentForm 
            subcontractor={selectedSub} 
            onCancel={() => setActiveView('detail')} 
            onSave={handleAddPayment}
          />
        ) : null;
      case 'add-sub':
        return (
          <AddSubcontractorForm 
            onCancel={() => setActiveView('subcontractors')} 
            onSave={handleAddSubcontractor}
          />
        );
      default:
        return <Dashboard subcontractors={subcontractors} />;
    }
  };

  return (
    <div className="max-w-md mx-auto min-h-screen relative bg-slate-50 flex flex-col">
      <main className="flex-1 p-5 overflow-y-auto no-scrollbar">
        {renderView()}
      </main>

      {/* Persistent Bottom Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/80 backdrop-blur-lg border-t border-slate-200 px-6 py-3 flex justify-between items-center z-50">
        <button 
          onClick={() => setActiveView('dashboard')}
          className={`flex flex-col items-center gap-1 transition-all ${activeView === 'dashboard' ? 'text-blue-600' : 'text-slate-400'}`}
        >
          <LayoutDashboard className="w-6 h-6" />
          <span className="text-[10px] font-bold uppercase tracking-tight">Panel</span>
        </button>
        <button 
          onClick={() => setActiveView('subcontractors')}
          className={`flex flex-col items-center gap-1 transition-all ${['subcontractors', 'detail', 'payment-form', 'add-sub'].includes(activeView) ? 'text-blue-600' : 'text-slate-400'}`}
        >
          <Users className="w-6 h-6" />
          <span className="text-[10px] font-bold uppercase tracking-tight">Taşeron</span>
        </button>
        <button 
          onClick={() => setActiveView('reports')}
          className={`flex flex-col items-center gap-1 transition-all ${activeView === 'reports' ? 'text-blue-600' : 'text-slate-400'}`}
        >
          <BarChart3 className="w-6 h-6" />
          <span className="text-[10px] font-bold uppercase tracking-tight">Raporlar</span>
        </button>
        <button 
          className="flex flex-col items-center gap-1 text-slate-400 opacity-50 cursor-not-allowed"
          title="Gelecek Özellik"
        >
          <Settings className="w-6 h-6" />
          <span className="text-[10px] font-bold uppercase tracking-tight">Ayarlar</span>
        </button>
      </nav>
    </div>
  );
};

export default App;

