  M2 = 'm²',
  M3 = 'm³',
  MT = 'mt',
  ADET = 'Adet',
  TON = 'Ton',
  KG = 'Kg',
  LS = 'Lump-sum'
}

export interface WorkItem {
  id: string;
  description: string;
  unit: UnitType;
  unitPrice: number;
  contractQuantity: number;
  completedQuantity: number;
}

export interface Subcontractor {
  id: string;
  name: string;
  trade: string;
  contractDate: string;
  totalContractValue: number;
  workItems: WorkItem[];
  progressPayments: ProgressPayment[];
  contractDocument?: string; // Base64 string of the document/image
  contractDocumentName?: string;
}

export interface ProgressPayment {
  id: string;
  number: number; // Hakediş No
  date: string;
  subcontractorId: string;
  items: {
    workItemId: string;
    thisPeriodQuantity: number;
    cumulativeQuantity: number;
  }[];
  summary: {
    previousTotal: number;
    currentTotal: number;
    cumulativeTotal: number;
    retentionAmount: number; // Kesinti
    vatAmount: number; // KDV
    netPayable: number;
  };
}

