                      <Eye className="w-5 h-5" />
                    </button>
                    <button 
                      onClick={handleRemoveDoc}
                      className="p-2 bg-red-50 text-red-600 rounded-xl hover:bg-red-100 transition-colors"
                    >
                      <Trash2 className="w-5 h-5" />
