import React, { useState, useRef } from 'react';
import { Subcontractor, ProgressPayment, ContractDocument } from '../types';
import { ArrowLeft, Plus, Sparkles, FileText, Info, TrendingUp, Calendar, Edit2, Check, X, FileUp, Eye, Trash2, Image as ImageIcon, ZoomIn } from 'lucide-react';
import { analyzeProgress } from '../services/geminiService';

interface SubcontractorDetailProps {
  subcontractor: Subcontractor;
  onBack: () => void;
  onNewPayment: () => void;
  onUpdate: (updatedSub: Subcontractor) => void;
}

const SubcontractorDetail: React.FC<SubcontractorDetailProps> = ({ subcontractor, onBack, onNewPayment, onUpdate }) => {
  const [activeTab, setActiveTab] = useState<'items' | 'payments' | 'docs'>('items');
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isEditingDate, setIsEditingDate] = useState(false);
  const [tempDate, setTempDate] = useState(subcontractor.contractDate.split('T')[0]);
  const [previewDoc, setPreviewDoc] = useState<ContractDocument | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    const report = await analyzeProgress(subcontractor);
    setAiReport(report || "Analiz yapılamadı.");
    setIsAnalyzing(false);
  };

  const handleSaveDate = () => {
    onUpdate({
      ...subcontractor,
      contractDate: new Date(tempDate).toISOString()
    });
    setIsEditingDate(false);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const newDoc: ContractDocument = {
          id: Math.random().toString(36).substr(2, 9),
          url: reader.result as string,
          name: file.name,
          uploadDate: new Date().toISOString()
        };
        onUpdate({
          ...subcontractor,
          contractDocuments: [...(subcontractor.contractDocuments || []), newDoc]
        });
      };
      reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleRemoveDoc = (docId: string) => {
    if (confirm("Bu belgeyi silmek istediğinize emin misiniz?")) {
      onUpdate({
        ...subcontractor,
        contractDocuments: subcontractor.contractDocuments.filter(d => d.id !== docId)
      });
    }
  };

  const lastPayment = subcontractor.progressPayments[subcontractor.progressPayments.length - 1];
  const totalPaid = lastPayment?.summary.cumulativeTotal || 0;
  const progressPercent = (totalPaid / subcontractor.totalContractValue) * 100;

  return (
    <div className="space-y-6 pb-24 animate-in fade-in duration-500 max-w-2xl mx-auto relative">
      {/* Fullscreen Image Preview Modal */}
      {previewDoc && (
        <div className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-black/95 animate-in fade-in duration-300 p-4">
          <button 
            onClick={() => setPreviewDoc(null)}
            className="absolute top-6 right-6 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white transition-colors"
          >
            <X className="w-6 h-6" />
          </button>
          <div className="w-full max-w-4xl h-[80vh] flex items-center justify-center">
            <img 
              src={previewDoc.url} 
              alt={previewDoc.name} 
              className="max-w-full max-h-full object-contain rounded-lg shadow-2xl"
            />
          </div>
          <div className="mt-6 text-center">
            <p className="text-white font-bold text-lg">{previewDoc.name}</p>
            <p className="text-white/50 text-xs mt-1">Yükleme: {new Date(previewDoc.uploadDate).toLocaleDateString('tr-TR')}</p>
          </div>
        </div>
      )}

      {/* Top Bar */}
      <div className="flex items-center gap-3">
        <button onClick={onBack} className="p-2 bg-white rounded-xl shadow-sm border border-slate-100 hover:bg-slate-50 transition-colors">
          <ArrowLeft className="w-5 h-5 text-slate-600" />
        </button>
        <div className="flex-1">
          <h2 className="text-xl font-bold text-slate-800">{subcontractor.name}</h2>
          <div className="flex items-center flex-wrap gap-2 mt-1">
            <span className="text-[10px] bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full font-bold uppercase tracking-wider">{subcontractor.trade}</span>
            <div className="flex items-center gap-1.5">
              {isEditingDate ? (
                <div className="flex items-center gap-1 bg-white border border-slate-200 rounded-lg p-1 animate-in zoom-in-95 duration-200">
                  <input 
                    type="date" 
                    value={tempDate}
                    onChange={(e) => setTempDate(e.target.value)}
                    className="text-[10px] font-bold text-slate-700 outline-none bg-transparent px-1"
                  />
                  <button onClick={handleSaveDate} className="text-green-600 p-0.5 hover:bg-green-50 rounded">
                    <Check className="w-3 h-3" />
                  </button>
                  <button onClick={() => setIsEditingDate(false)} className="text-red-600 p-0.5 hover:bg-red-50 rounded">
                    <X className="w-3 h-3" />
                  </button>
                </div>
              ) : (
                <button 
                  onClick={() => setIsEditingDate(true)}
                  className="flex items-center gap-1 group text-[10px] text-slate-400 font-medium hover:text-blue-600 transition-colors"
                >
                  <Calendar className="w-3 h-3" />
                  <span>Sözleşme: {new Date(subcontractor.contractDate).toLocaleDateString('tr-TR')}</span>
                  <Edit2 className="w-2.5 h-2.5 opacity-0 group-hover:opacity-100 transition-opacity" />
                </button>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Summary Card */}
      <div className="bg-gradient-to-br from-slate-800 to-slate-900 p-6 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden group">
        <div className="absolute top-0 right-0 p-8 opacity-10 rotate-12 group-hover:rotate-45 transition-transform duration-700">
           <TrendingUp className="w-32 h-32" />
