export enum UnitType {
  M2 = 'm²',
  M3 = 'm³',
  MT = 'mt',
  ADET = 'Adet',
  TON = 'Ton',
  KG = 'Kg',
  LS = 'Lump-sum'
}

export interface WorkItem {
  id: string;
  description: string;
  unit: UnitType;
  unitPrice: number;
  contractQuantity: number;
  completedQuantity: number;
}

export interface ContractDocument {
  id: string;
  url: string;
  name: string;
  uploadDate: string;
}

export interface Project {
  id: string;
  name: string;
  location: string;
  startDate: string;
  status: 'Devam Ediyor' | 'Tamamlandı' | 'Planlama';
  description?: string;
}

export interface Contract {
  id: string;
  projectId: string;
  subcontractorId: string;
  title: string;
  contractDate: string;
  totalValue: number;
  workItems: WorkItem[];
  progressPayments: ProgressPayment[];
  documents: ContractDocument[];
  status: 'Aktif' | 'Fesih' | 'Bitti';
}

export interface Subcontractor {
  id: string;
  name: string;
  trade: string;
  contactInfo?: string;
}

export interface ProgressPayment {
  id: string;
  number: number;
  date: string;
  contractId: string;
  items: {
    workItemId: string;
    thisPeriodQuantity: number;
    cumulativeQuantity: number;
  }[];
  summary: {
    previousTotal: number;
    currentTotal: number;
    cumulativeTotal: number;
    retentionAmount: number;
    vatAmount: number;
    netPayable: number;
  };
}

export interface AppState {
  projects: Project[];
  subcontractors: Subcontractor[];
  contracts: Contract[];
}

