import React, { useState } from 'react';
import { Project, Subcontractor, Contract, UnitType, WorkItem } from '../types';
import { ArrowLeft, Save, Plus, Trash2, FileText, User } from 'lucide-react';

interface ContractFormProps {
  projects: Project[];
  subcontractors: Subcontractor[];
  onCancel: () => void;
  onSave: (contract: Contract) => void;
}

const ContractForm: React.FC<ContractFormProps> = ({ projects, subcontractors, onCancel, onSave }) => {
  const [projectId, setProjectId] = useState(projects[0]?.id || '');
  const [subId, setSubId] = useState(subcontractors[0]?.id || '');
  const [title, setTitle] = useState('');
  const [workItems, setWorkItems] = useState<WorkItem[]>([]);

  const handleAddWorkItem = () => {
    setWorkItems([...workItems, { 
      id: Math.random().toString(36).substr(2, 9), 
      description: '', 
      unit: UnitType.M2, 
      unitPrice: 0, 
      contractQuantity: 0, 
      completedQuantity: 0 
    }]);
  };

  const handleSave = () => {
    if (!projectId || !subId || !title || workItems.length === 0) return;
    const totalValue = workItems.reduce((sum, item) => sum + (item.unitPrice * item.contractQuantity), 0);

    onSave({
      id: Math.random().toString(36).substr(2, 9),
      projectId,
      subcontractorId: subId,
      title,
      contractDate: new Date().toISOString(),
      totalValue,
      workItems,
      progressPayments: [],
      documents: [],
      status: 'Aktif'
    });
  };

  return (
    <div className="space-y-6 pb-24 animate-in slide-in-from-right duration-500 max-w-2xl mx-auto">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <button onClick={onCancel} className="p-2 bg-white rounded-xl shadow-sm border border-slate-100">
            <ArrowLeft className="w-5 h-5 text-slate-600" />
          </button>
          <h2 className="text-xl font-bold text-slate-800">Yeni Sözleşme Tanımla</h2>
        </div>
        <button 
          onClick={handleSave}
          className="bg-blue-600 text-white px-5 py-2.5 rounded-xl flex items-center gap-2 font-bold shadow-lg shadow-blue-200 active:scale-95 transition-all"
        >
          <Save className="w-4 h-4" /> Kaydet
        </button>
      </div>

      <div className="space-y-4">
        <div className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-5">
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-1">Sözleşme Başlığı</label>
            <input 
              type="text" 
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Örn: Blok A Seramik İşleri Sözleşmesi"
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm font-bold"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-1">İlgili Proje</label>
              <select 
                value={projectId}
                onChange={(e) => setProjectId(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-4 text-xs font-bold focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                {projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-1">Taşeron</label>
              <select 
                value={subId}
                onChange={(e) => setSubId(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-4 text-xs font-bold focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                {subcontractors.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
              </select>
            </div>
          </div>
        </div>

        <div className="space-y-3">
          <div className="flex justify-between items-center px-1">
            <h3 className="text-xs font-black text-slate-700 uppercase tracking-widest">Sözleşme İş Kalemleri</h3>
            <button 
              onClick={handleAddWorkItem}
              className="bg-blue-50 text-blue-600 px-4 py-2 rounded-xl text-[10px] font-black uppercase flex items-center gap-1 shadow-sm"
            >
              <Plus className="w-3 h-3" /> Kalem Ekle
            </button>
          </div>

          {workItems.map((item, idx) => (
            <div key={item.id} className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm space-y-4 relative group animate-in zoom-in-95">
              <button 
                onClick={() => setWorkItems(workItems.filter(i => i.id !== item.id))}
                className="absolute top-4 right-4 text-slate-200 hover:text-red-500 transition-colors"
              >
                <Trash2 className="w-4 h-4" />
              </button>

              <div className="space-y-1">
                <label className="text-[9px] font-bold text-slate-400 uppercase ml-1">İş Tanımı</label>
                <input 
                  type="text"
                  value={item.description}
                  onChange={(e) => {
                    const next = [...workItems];
                    next[idx].description = e.target.value;
                    setWorkItems(next);
                  }}
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm font-bold"
                />
              </div>

              <div className="grid grid-cols-3 gap-3">
                <div className="space-y-1">
                  <label className="text-[9px] font-bold text-slate-400 uppercase ml-1">Birim</label>
                  <select 
                    value={item.unit}
                    onChange={(e) => {
                      const next = [...workItems];
                      next[idx].unit = e.target.value as UnitType;
                      setWorkItems(next);
                    }}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-2 py-2 text-[10px] font-black uppercase"
                  >
                    {Object.values(UnitType).map(u => <option key={u} value={u}>{u}</option>)}
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-bold text-slate-400 uppercase ml-1">Fiyat</label>
                  <input 
                    type="number"
                    value={item.unitPrice}
                    onChange={(e) => {
                      const next = [...workItems];
                      next[idx].unitPrice = Number(e.target.value);
                      setWorkItems(next);
                    }}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-black"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-bold text-slate-400 uppercase ml-1">Miktar</label>
                  <input 
                    type="number"
                    value={item.contractQuantity}
                    onChange={(e) => {
                      const next = [...workItems];
                      next[idx].contractQuantity = Number(e.target.value);
                      setWorkItems(next);
                    }}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-black"
                  />
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default ContractForm;

import React, { useState, useEffect } from 'react';
import { Subcontractor, ProgressPayment, Project, Contract } from './types';
import Dashboard from './components/Dashboard';
import SubcontractorList from './components/SubcontractorList';
import SubcontractorDetail from './components/SubcontractorDetail';
import ProgressPaymentForm from './components/ProgressPaymentForm';
import AddSubcontractorForm from './components/AddSubcontractorForm';
import Reports from './components/Reports';
import AllPaymentsList from './components/AllPaymentsList';
import ProjectList from './components/ProjectList';
import ProjectForm from './components/ProjectForm';
import ContractForm from './components/ContractForm';
import { LayoutDashboard, Users, BarChart3, FileText, Building2, BookOpen } from 'lucide-react';

const STORAGE_KEY = 'hakedis_app_data_v2';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<'dashboard' | 'subcontractors' | 'all-payments' | 'reports' | 'detail' | 'payment-form' | 'add-sub' | 'projects' | 'add-project' | 'contracts' | 'add-contract'>('dashboard');

  const [projects, setProjects] = useState<Project[]>([]);
  const [subcontractors, setSubcontractors] = useState<Subcontractor[]>([]);
  const [contracts, setContracts] = useState<Contract[]>([]);

  const [selectedSubId, setSelectedSubId] = useState<string | null>(null);
  const [selectedContractId, setSelectedContractId] = useState<string | null>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const data = JSON.parse(saved);
      setProjects(data.projects || []);
      setSubcontractors(data.subcontractors || []);
      setContracts(data.contracts || []);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ projects, subcontractors, contracts }));
  }, [projects, subcontractors, contracts]);

  const handleAddProject = (p: Project) => {
    setProjects([...projects, p]);
    setActiveView('projects');
  };

  const handleAddSubcontractor = (s: Subcontractor) => {
    setSubcontractors([...subcontractors, s]);
    setActiveView('subcontractors');
  };

  const handleAddContract = (c: Contract) => {
    setContracts([...contracts, c]);
    setActiveView('contracts');
  };

  const handleUpdateContract = (updated: Contract) => {
    setContracts(prev => prev.map(c => c.id === updated.id ? updated : c));
  };

  const handleAddPayment = (payment: ProgressPayment) => {
    setContracts(prev => prev.map(c => {
      if (c.id === payment.contractId) {
        return {
          ...c,
          progressPayments: [...c.progressPayments, payment]
        };
      }
      return c;
    }));
    setActiveView('detail');
  };

  const selectedContract = contracts.find(c => c.id === selectedContractId);

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return <Dashboard subcontractors={subcontractors} projects={projects} contracts={contracts} />;
      case 'projects':
        return <ProjectList projects={projects} onAdd={() => setActiveView('add-project')} onSelect={() => {}} />;
      case 'add-project':
        return <ProjectForm onCancel={() => setActiveView('projects')} onSave={handleAddProject} />;
      case 'contracts':
        return (
          <div className="space-y-6 pb-24">
            <div className="flex justify-between items-center">
              <h1 className="text-2xl font-bold text-slate-800">Sözleşmeler</h1>
              <button 
                onClick={() => setActiveView('add-contract')}
                className="bg-blue-600 text-white p-3 rounded-2xl shadow-lg shadow-blue-200 active:scale-95 transition-all flex items-center gap-2"
              >
                <BookOpen className="w-5 h-5" />
                <span className="text-xs font-bold uppercase">Sözleşme Tanımla</span>
              </button>
            </div>
            <div className="space-y-4">
              {contracts.map(c => {
                const project = projects.find(p => p.id === c.projectId);
                const sub = subcontractors.find(s => s.id === c.subcontractorId);
                return (
                  <button 
                    key={c.id} 
                    onClick={() => { setSelectedContractId(c.id); setActiveView('detail'); }}
                    className="w-full text-left bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm hover:border-blue-100 transition-all flex flex-col gap-3"
                  >
                    <div className="flex justify-between items-start">
                      <div>
                        <h3 className="font-black text-slate-800 text-sm uppercase">{c.title}</h3>
                        <p className="text-[10px] font-bold text-slate-400 mt-0.5">{project?.name} / {sub?.name}</p>
                      </div>
                      <span className="bg-blue-50 text-blue-600 text-[10px] font-black px-3 py-1 rounded-full uppercase">
                        {c.totalValue.toLocaleString('tr-TR')} TL
                      </span>
                    </div>
                    <div className="w-full bg-slate-100 h-1.5 rounded-full overflow-hidden">
                      <div 
                        className="bg-blue-600 h-full rounded-full transition-all duration-1000" 
                        style={{ width: `${Math.min(100, (c.progressPayments[c.progressPayments.length-1]?.summary.cumulativeTotal || 0) / c.totalValue * 100)}%` }}
                      />
                    </div>
                  </button>
                );
              })}
            </div>
          </div>
        );
      case 'add-contract':
        return <ContractForm projects={projects} subcontractors={subcontractors} onCancel={() => setActiveView('contracts')} onSave={handleAddContract} />;
      case 'subcontractors':
        return <SubcontractorList subcontractors={subcontractors} onSelect={() => {}} onAdd={() => setActiveView('add-sub')} />;
      case 'add-sub':
        return (
          <div className="space-y-6 pb-24">
            <h2 className="text-xl font-bold">Taşeron Ekle</h2>
            <div className="bg-white p-6 rounded-3xl border shadow-sm space-y-4">
               <input 
                type="text" 
                placeholder="İsim" 
                className="w-full p-4 bg-slate-50 border rounded-2xl" 
                onBlur={(e) => {
                  if (e.target.value) handleAddSubcontractor({ id: Math.random().toString(36).substr(2, 9), name: e.target.value, trade: 'Genel' });
                }}
               />
               <button onClick={() => setActiveView('subcontractors')} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-bold">Geri Dön</button>
            </div>
          </div>
        );
      case 'detail':
        return selectedContract ? (
          <SubcontractorDetail 
            subcontractor={{ ...subcontractors.find(s => s.id === selectedContract.subcontractorId)!, contractDate: selectedContract.contractDate, totalContractValue: selectedContract.totalValue, workItems: selectedContract.workItems, progressPayments: selectedContract.progressPayments, contractDocuments: selectedContract.documents }}
            onBack={() => setActiveView('contracts')} 
            onNewPayment={() => setActiveView('payment-form')}
            onUpdate={(updatedSub) => {
               handleUpdateContract({
                 ...selectedContract,
                 workItems: updatedSub.workItems,
                 progressPayments: updatedSub.progressPayments,
                 documents: updatedSub.contractDocuments || []
               });
            }}
          />
        ) : null;
      case 'payment-form':
        return selectedContract ? (
          <ProgressPaymentForm 
            subcontractor={{ ...subcontractors.find(s => s.id === selectedContract.subcontractorId)!, contractDate: selectedContract.contractDate, totalContractValue: selectedContract.totalValue, workItems: selectedContract.workItems, progressPayments: selectedContract.progressPayments, contractDocuments: selectedContract.documents }} 
            onCancel={() => setActiveView('detail')} 
            onSave={(p) => handleAddPayment({ ...p, contractId: selectedContract.id })}
          />
        ) : null;
      default:
        return <Dashboard subcontractors={subcontractors} projects={projects} contracts={contracts} />;
    }
  };

  return (
    <div className="max-w-md mx-auto min-h-screen relative bg-slate-50 flex flex-col">
      <main className="flex-1 p-5 overflow-y-auto no-scrollbar">
        {renderView()}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/80 backdrop-blur-lg border-t border-slate-200 px-4 py-3 flex justify-between items-center z-50 shadow-2xl">
        <button 
          onClick={() => setActiveView('dashboard')}
          className={`flex flex-col items-center gap-1 transition-all flex-1 ${activeView === 'dashboard' ? 'text-indigo-600' : 'text-slate-400'}`}
        >
          <LayoutDashboard className="w-5 h-5" />
          <span className="text-[8px] font-black uppercase tracking-tighter">Panel</span>
        </button>
        <button 
          onClick={() => setActiveView('projects')}
          className={`flex flex-col items-center gap-1 transition-all flex-1 ${['projects', 'add-project'].includes(activeView) ? 'text-indigo-600' : 'text-slate-400'}`}
        >
          <Building2 className="w-5 h-5" />
          <span className="text-[8px] font-black uppercase tracking-tighter">Proje</span>
        </button>
        <button 
          onClick={() => setActiveView('contracts')}
          className={`flex flex-col items-center gap-1 transition-all flex-1 ${['contracts', 'add-contract', 'detail', 'payment-form'].includes(activeView) ? 'text-indigo-600' : 'text-slate-400'}`}
        >
          <BookOpen className="w-5 h-5" />
          <span className="text-[8px] font-black uppercase tracking-tighter">Sözleşme</span>
        </button>
        <button 
          onClick={() => setActiveView('subcontractors')}
          className={`flex flex-col items-center gap-1 transition-all flex-1 ${['subcontractors', 'add-sub'].includes(activeView) ? 'text-indigo-600' : 'text-slate-400'}`}
        >
          <Users className="w-5 h-5" />
          <span className="text-[8px] font-black uppercase tracking-tighter">Taşeron</span>
        </button>
      </nav>
    </div>
  );
};

export default App;

import React from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer 
} from 'recharts';
import { Subcontractor, Project, Contract } from '../types';
import { TrendingUp, Users, Building2, BookOpen, Wallet } from 'lucide-react';

interface DashboardProps {
  subcontractors: Subcontractor[];
  projects: Project[];
  contracts: Contract[];
}

const Dashboard: React.FC<DashboardProps> = ({ subcontractors, projects, contracts }) => {
  const totalContract = contracts.reduce((sum, c) => sum + c.totalValue, 0);
  const totalPaid = contracts.reduce((sum, c) => {
    const lastPayment = c.progressPayments[c.progressPayments.length - 1];
    return sum + (lastPayment?.summary.cumulativeTotal || 0);
  }, 0);

  const chartData = contracts.map(c => {
    const paid = c.progressPayments.reduce((sum, p) => sum + p.summary.currentTotal, 0);
    return {
      name: c.title.length > 8 ? c.title.substring(0, 8) + '...' : c.title,
      Sözleşme: c.totalValue,
      Ödenen: paid
    };
  });

  const progressPercent = totalContract > 0 ? (totalPaid / totalContract) * 100 : 0;

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-700">
      <h1 className="text-2xl font-black text-slate-800 px-2 uppercase tracking-tight">Genel Bakış</h1>

      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-100 flex flex-col items-center text-center">
          <div className="bg-indigo-50 p-3 rounded-2xl mb-2 text-indigo-600">
            <Building2 className="w-6 h-6" />
          </div>
          <span className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Proje</span>
          <span className="text-xl font-black text-slate-800">{projects.length}</span>
        </div>
        <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-100 flex flex-col items-center text-center">
          <div className="bg-blue-50 p-3 rounded-2xl mb-2 text-blue-600">
            <BookOpen className="w-6 h-6" />
          </div>
          <span className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Sözleşme</span>
          <span className="text-xl font-black text-slate-800">{contracts.length}</span>
        </div>
        <div className="bg-slate-900 p-6 rounded-[2.5rem] shadow-xl shadow-slate-200 flex flex-col col-span-2 text-white relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:rotate-12 transition-transform">
             <TrendingUp className="w-24 h-24" />
          </div>
          <div className="relative z-10 flex justify-between items-end">
            <div>
              <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mb-1">Toplam Sözleşme Hacmi</p>
              <p className="text-2xl font-black text-white">{totalContract.toLocaleString('tr-TR')} TL</p>
            </div>
            <div className="text-right">
               <p className="text-[10px] text-slate-400 font-black uppercase mb-1">İlerleme</p>
               <p className="text-2xl font-black text-blue-400">%{progressPercent.toFixed(1)}</p>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100 h-72">
        <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-6">Sözleşme Dağılımı</h3>
        <ResponsiveContainer width="100%" height="80%">
          <BarChart data={chartData}>
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
            <XAxis dataKey="name" fontSize={10} axisLine={false} tickLine={false} />
            <Tooltip cursor={{fill: '#f8fafc'}} />
            <Bar dataKey="Sözleşme" fill="#e2e8f0" radius={[6, 6, 0, 0]} />
            <Bar dataKey="Ödenen" fill="#4f46e5" radius={[6, 6, 0, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default Dashboard;

export enum UnitType {
  M2 = 'm²',
