const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeProgress = async (subcontractor: Subcontractor) => {
  // Use defaults for optional fields to ensure the prompt is valid
  const prompt = `
    Aşağıdaki taşeronun hakediş verilerini analiz et ve Türkçe olarak profesyonel bir inşaat mühendisi gibi yorumla.
    Taşeron: ${subcontractor.name} (${subcontractor.trade})
    Sözleşme Bedeli: ${subcontractor.totalContractValue || 0} TL
    İş Kalemleri: ${JSON.stringify(subcontractor.workItems || [])}
    Yapılan Hakedişler: ${JSON.stringify(subcontractor.progressPayments || [])}

    Lütfen şunları belirt:
    1. İşin genel ilerleme yüzdesi.
    2. Bütçe aşımı veya verimlilik uyarısı var mı?
    3. Gelecek hakediş için projeksiyon ve tavsiyeler.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini analysis error:", error);
    return "Analiz sırasında bir hata oluştu.";
  }
};

export const analyzeProjectHealth = async (subcontractors: Subcontractor[]) => {
  // Use safe property access for optional subcontractor fields
  const summaryData = subcontractors.map(s => ({
    name: s.name,
    trade: s.trade,
    contractValue: s.totalContractValue || 0,
    paidTotal: (s.progressPayments || []).reduce((sum, p) => sum + p.summary.currentTotal, 0),
    lastPaymentDate: s.progressPayments?.[s.progressPayments.length - 1]?.date
  }));

  const prompt = `
    Tüm şantiyenin taşeron hakediş verilerini analiz et. 
    Veriler: ${JSON.stringify(summaryData)}

    Bir proje müdürü perspektifiyle Türkçe olarak:
    1. Projenin genel mali sağlığını değerlendir.
    2. En çok ödeme yapılan kalemleri ve riskli gördüğün taşeronları belirt.
    3. Nakit akışı yönetimi için stratejik tavsiyeler ver.
    Kısa, öz ve profesyonel bir dil kullan.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Project health analysis error:", error);
    return "Proje analizi yapılamadı.";
  }
};

export const parseWorkItemsFromText = async (text: string) => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Metinden iş kalemlerini çıkar ve JSON formatında döndür. Metin: ${text}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            description: { type: Type.STRING },
            unit: { type: Type.STRING, enum: ["m²", "m³", "mt", "Adet", "Ton", "Kg", "Lump-sum"] },
            unitPrice: { type: Type.NUMBER },
            contractQuantity: { type: Type.NUMBER },
          },
          required: ["description", "unit", "unitPrice", "contractQuantity"]
        }
      }
    }
  });
  // Trim the response text before parsing to ensure valid JSON
  return JSON.parse(response.text.trim());
};

import React, { useState, useMemo } from 'react';
import { Subcontractor, ProgressPayment, UnitType } from '../types';
import { ArrowLeft, Save, AlertCircle, Calculator, Percent } from 'lucide-react';

interface ProgressPaymentFormProps {
  subcontractor: Subcontractor;
  onCancel: () => void;
  onSave: (payment: ProgressPayment) => void;
}

const ProgressPaymentForm: React.FC<ProgressPaymentFormProps> = ({ subcontractor, onCancel, onSave }) => {
  // Defensive initialization for optional workItems
  const [quantities, setQuantities] = useState<Record<string, number>>(
    (subcontractor.workItems || []).reduce((acc, item) => ({ ...acc, [item.id]: 0 }), {})
  );

  const [vatRate, setVatRate] = useState(20);
  const [retentionRate, setRetentionRate] = useState(5);

  // Derived data for each work item with defensive checks
  const itemProgress = useMemo(() => {
    return (subcontractor.workItems || []).map(item => {
      const prevTotal = (subcontractor.progressPayments || []).reduce((sum, p) => {
        const pItem = p.items.find(i => i.workItemId === item.id);
        return sum + (pItem?.thisPeriodQuantity || 0);
      }, 0);

      const thisPeriod = quantities[item.id] || 0;
      const cumulative = prevTotal + thisPeriod;
      const amount = thisPeriod * item.unitPrice;
      const isExceeding = cumulative > item.contractQuantity;

      return {
        ...item,
        prevTotal,
        thisPeriod,
        cumulative,
        amount,
        isExceeding
      };
    });
  }, [subcontractor, quantities]);

  // Overall summary calculation using optional chaining
  const summary = useMemo(() => {
    const currentTotal = itemProgress.reduce((sum, i) => sum + i.amount, 0);
    const lastPayment = subcontractor.progressPayments?.[subcontractor.progressPayments.length - 1];
    const previousTotal = lastPayment?.summary.cumulativeTotal || 0;
    const cumulativeTotal = previousTotal + currentTotal;

    const retentionAmount = (currentTotal * retentionRate) / 100;
    const vatAmount = (currentTotal * vatRate) / 100;
    const netPayable = currentTotal - retentionAmount + vatAmount;

    return {
      previousTotal,
      currentTotal,
      cumulativeTotal,
      retentionAmount,
      vatAmount,
      netPayable
    };
  }, [itemProgress, retentionRate, vatRate, subcontractor.progressPayments]);

  const handleSave = () => {
    // Fixed: Changed subcontractorId to contractId to match ProgressPayment interface
    const newPayment: ProgressPayment = {
      id: Math.random().toString(36).substr(2, 9),
      number: (subcontractor.progressPayments?.length || 0) + 1,
      date: new Date().toISOString(),
      contractId: '', // Placeholder, gets overridden in the App.tsx onSave handler
      items: itemProgress.map(i => ({
        workItemId: i.id,
        thisPeriodQuantity: i.thisPeriod,
        cumulativeQuantity: i.cumulative
      })),
      summary: {
        previousTotal: summary.previousTotal,
        currentTotal: summary.currentTotal,
        cumulativeTotal: summary.cumulativeTotal,
        retentionAmount: summary.retentionAmount,
        vatAmount: summary.vatAmount,
        netPayable: summary.netPayable
      }
    };
    onSave(newPayment);
  };

  return (
    <div className="space-y-6 pb-24 animate-in slide-in-from-bottom duration-500 max-w-2xl mx-auto">
      {/* Header */}
      <div className="flex items-center justify-between sticky top-0 bg-slate-50/80 backdrop-blur-md z-20 py-2">
        <div className="flex items-center gap-3">
          <button onClick={onCancel} className="p-2 bg-white rounded-xl shadow-sm border border-slate-200">
            <ArrowLeft className="w-5 h-5 text-slate-600" />
          </button>
          <div>
            <h2 className="text-xl font-bold text-slate-800">Yeni Hakediş No: {(subcontractor.progressPayments?.length || 0) + 1}</h2>
            <p className="text-xs text-slate-500 font-medium uppercase">{subcontractor.name}</p>
          </div>
        </div>
        <button 
          onClick={handleSave}
          className="bg-blue-600 text-white px-5 py-2.5 rounded-xl flex items-center gap-2 font-bold shadow-lg shadow-blue-200 active:scale-95 transition-all"
        >
          <Save className="w-4 h-4" /> Kaydet
        </button>
      </div>

      {/* Settings Summary */}
      <div className="grid grid-cols-2 gap-3">
        <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-3">
          <div className="p-2 bg-indigo-50 rounded-lg">
            <Percent className="w-4 h-4 text-indigo-600" />
          </div>
          <div className="flex-1">
            <p className="text-[10px] text-slate-400 font-bold uppercase">KDV Oranı</p>
            <select 
              value={vatRate} 
              onChange={(e) => setVatRate(Number(e.target.value))}
              className="text-sm font-bold text-slate-700 bg-transparent w-full focus:outline-none"
            >
              <option value={0}>%0</option>
              <option value={10}>%10</option>
              <option value={20}>%20</option>
            </select>
          </div>
        </div>
        <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-3">
          <div className="p-2 bg-orange-50 rounded-lg">
            <Calculator className="w-4 h-4 text-orange-600" />
          </div>
          <div className="flex-1">
            <p className="text-[10px] text-slate-400 font-bold uppercase">Kesinti Oranı</p>
            <select 
              value={retentionRate} 
              onChange={(e) => setRetentionRate(Number(e.target.value))}
              className="text-sm font-bold text-slate-700 bg-transparent w-full focus:outline-none"
            >
              <option value={0}>%0</option>
              <option value={3}>%3</option>
              <option value={5}>%5</option>
              <option value={10}>%10</option>
            </select>
          </div>
        </div>
      </div>

      {/* Item List */}
      <div className="space-y-4">
        <div className="flex items-center justify-between px-1">
          <h3 className="text-sm font-bold text-slate-700 uppercase tracking-widest">İş Kalemleri</h3>
          <span className="text-[10px] text-slate-400 font-medium">Toplam {subcontractor.workItems?.length || 0} Kalem</span>
        </div>

        {itemProgress.map(item => (
          <div key={item.id} className={`bg-white rounded-2xl border transition-all duration-300 ${item.isExceeding ? 'border-red-200 bg-red-50/30' : 'border-slate-100 shadow-sm'}`}>
            <div className="p-4 space-y-4">
              <div className="flex justify-between items-start">
                <div className="flex-1">
                  <p className="text-sm font-bold text-slate-800 leading-tight">{item.description}</p>
                  <p className="text-[10px] text-slate-400 mt-1">Birim Fiyat: {item.unitPrice.toLocaleString('tr-TR')} TL</p>
                </div>
                <span className="bg-slate-100 text-slate-500 text-[10px] font-black px-2 py-1 rounded-md uppercase ml-2">{item.unit}</span>
              </div>

              {/* Progress Tracker */}
              <div className="grid grid-cols-3 gap-2 bg-slate-50/50 p-2 rounded-xl border border-slate-100/50">
                <div className="text-center">
                  <p className="text-[9px] text-slate-400 font-bold uppercase">Sözleşme</p>
                  <p className="text-xs font-bold text-slate-600">{item.contractQuantity}</p>
                </div>
                <div className="text-center border-x border-slate-200">
                  <p className="text-[9px] text-slate-400 font-bold uppercase">Önceki</p>
                  <p className="text-xs font-bold text-slate-600">{item.prevTotal}</p>
                </div>
                <div className="text-center">
                  <p className="text-[9px] text-slate-400 font-bold uppercase">Kalan</p>
                  <p className={`text-xs font-bold ${item.contractQuantity - item.prevTotal < 0 ? 'text-red-500' : 'text-green-600'}`}>
                    {Math.max(0, item.contractQuantity - item.prevTotal)}
                  </p>
                </div>
              </div>

              {/* Input Section */}
              <div className="flex items-end gap-4 pt-1">
                <div className="flex-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block ml-1">Bu Dönem Miktarı</label>
                  <div className="relative">
                    <input 
                      type="number" 
                      value={item.thisPeriod || ''} 
                      placeholder="0"
                      onChange={(e) => setQuantities({ ...quantities, [item.id]: parseFloat(e.target.value) || 0 })}
                      className={`w-full bg-slate-50 border rounded-xl px-4 py-3 focus:outline-none focus:ring-2 font-black text-slate-700 transition-all ${item.isExceeding ? 'border-red-300 focus:ring-red-200' : 'border-slate-200 focus:ring-blue-100'}`}
                    />
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-300 pointer-events-none">
                      <Calculator className="w-4 h-4" />
                    </div>
                  </div>
                </div>
                <div className="text-right min-w-[100px]">
                  <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">Dönem Tutarı</p>
                  <p className="text-sm font-black text-blue-600 py-3">{item.amount.toLocaleString('tr-TR')} TL</p>
                </div>
              </div>

              {item.isExceeding && (
                <div className="flex items-center gap-2 text-red-600 text-[10px] font-bold bg-red-50 p-2 rounded-lg border border-red-100 animate-pulse">
                  <AlertCircle className="w-3 h-3" />
                  SÖZLEŞME MİKTARI AŞILDI (Kümülatif: {item.cumulative})
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Grand Summary Card */}
      <div className="bg-slate-900 text-white rounded-[32px] p-8 shadow-2xl space-y-6 relative overflow-hidden group">
        <div className="absolute -right-20 -top-20 bg-blue-500/10 w-64 h-64 rounded-full blur-3xl group-hover:bg-blue-500/20 transition-colors" />

        <h3 className="text-sm font-bold text-slate-400 uppercase tracking-[0.2em] relative z-10">Hakediş İcmal</h3>

        <div className="space-y-4 relative z-10">
          <div className="flex justify-between items-center text-sm">
            <span className="text-slate-400">Bu Dönem İmalat Toplamı</span>
            <span className="font-bold">{summary.currentTotal.toLocaleString('tr-TR')} TL</span>
          </div>
          <div className="flex justify-between items-center text-sm">
            <span className="text-slate-400">Teminat Kesintisi (%{retentionRate})</span>
            <span className="font-bold text-orange-400">-{summary.retentionAmount.toLocaleString('tr-TR')} TL</span>
          </div>
          <div className="flex justify-between items-center text-sm pb-4 border-b border-slate-800">
            <span className="text-slate-400">KDV Tutarı (%{vatRate})</span>
            <span className="font-bold text-blue-400">+{summary.vatAmount.toLocaleString('tr-TR')} TL</span>
          </div>

          <div className="pt-2 flex justify-between items-end">
            <div>
              <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1">NET ÖDENECEK TUTAR</p>
              <p className="text-3xl font-black text-white">{summary.netPayable.toLocaleString('tr-TR')} <span className="text-lg font-bold text-slate-500">TL</span></p>
            </div>
            <div className="text-right">
              <p className="text-[9px] font-bold text-slate-500 uppercase mb-1">KÜMÜLATİF TOPLAM</p>
              <p className="text-sm font-bold text-slate-300">{summary.cumulativeTotal.toLocaleString('tr-TR')} TL</p>
            </div>
          </div>
        </div>

        <button 
          onClick={handleSave}
          className="w-full bg-blue-600 hover:bg-blue-500 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all active:scale-95 shadow-xl shadow-blue-900/20 relative z-10"
        >
          HAKEDİŞİ ONAYLA VE KAYDET
        </button>
      </div>
    </div>
  );
};

