import React, { useState, useMemo } from 'react';
import { Subcontractor, ProgressPayment, UnitType } from '../types';
import { ArrowLeft, Save, AlertCircle, Calculator, Percent, Gavel, ShieldCheck } from 'lucide-react';

interface ProgressPaymentFormProps {
  subcontractor: Subcontractor;
  onCancel: () => void;
  onSave: (payment: ProgressPayment) => void;
}

const ProgressPaymentForm: React.FC<ProgressPaymentFormProps> = ({ subcontractor, onCancel, onSave }) => {
  const [quantities, setQuantities] = useState<Record<string, number>>(
    (subcontractor.workItems || []).reduce((acc, item) => ({ ...acc, [item.id]: 0 }), {})
  );

  const [vatRate, setVatRate] = useState(20);
  const [retentionRate, setRetentionRate] = useState(5); // Teminat kesintisi %5
  const STAMP_DUTY_RATE = 0.00948; // Binde 9.48

  const itemProgress = useMemo(() => {
    return (subcontractor.workItems || []).map(item => {
      const prevTotal = (subcontractor.progressPayments || []).reduce((sum, p) => {
        const pItem = p.items.find(i => i.workItemId === item.id);
        return sum + (pItem?.thisPeriodQuantity || 0);
      }, 0);

      const thisPeriod = quantities[item.id] || 0;
      const cumulative = prevTotal + thisPeriod;
      const amount = thisPeriod * item.unitPrice;
      const isExceeding = cumulative > item.contractQuantity;

      return {
        ...item,
        prevTotal,
        thisPeriod,
        cumulative,
        amount,
        isExceeding
      };
    });
  }, [subcontractor, quantities]);

  const summary = useMemo(() => {
    const currentTotal = itemProgress.reduce((sum, i) => sum + i.amount, 0);
    const lastPayment = subcontractor.progressPayments?.[subcontractor.progressPayments.length - 1];
    const previousTotal = lastPayment?.summary.cumulativeTotal || 0;
    const cumulativeTotal = previousTotal + currentTotal;

    const retentionAmount = (currentTotal * retentionRate) / 100;
    const stampDutyAmount = currentTotal * STAMP_DUTY_RATE;
    const vatAmount = (currentTotal * vatRate) / 100;
    const netPayable = currentTotal - retentionAmount - stampDutyAmount + vatAmount;

    return {
      previousTotal,
      currentTotal,
      cumulativeTotal,
      retentionAmount,
      stampDutyAmount,
      vatAmount,
      netPayable
    };
  }, [itemProgress, retentionRate, vatRate, subcontractor.progressPayments]);

  const handleSave = () => {
    const newPayment: ProgressPayment = {
      id: Math.random().toString(36).substr(2, 9),
      number: (subcontractor.progressPayments?.length || 0) + 1,
      date: new Date().toISOString(),
      contractId: '', 
      items: itemProgress.map(i => ({
        workItemId: i.id,
        thisPeriodQuantity: i.thisPeriod,
        cumulativeQuantity: i.cumulative
      })),
      summary: {
        previousTotal: summary.previousTotal,
        currentTotal: summary.currentTotal,
        cumulativeTotal: summary.cumulativeTotal,
        retentionAmount: summary.retentionAmount,
        stampDutyAmount: summary.stampDutyAmount,
        vatAmount: summary.vatAmount,
        netPayable: summary.netPayable
      }
    };
    onSave(newPayment);
  };

  return (
    <div className="space-y-6 pb-24 animate-in slide-in-from-bottom duration-500 max-w-2xl mx-auto">
      <div className="flex items-center justify-between sticky top-0 bg-slate-50/80 backdrop-blur-md z-20 py-4">
        <div className="flex items-center gap-3">
          <button onClick={onCancel} className="p-2 bg-white rounded-xl shadow-sm border border-slate-200">
            <ArrowLeft className="w-5 h-5 text-slate-600" />
          </button>
          <div>
            <h2 className="text-xl font-bold text-slate-800">Hakediş Raporu No: {(subcontractor.progressPayments?.length || 0) + 1}</h2>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{subcontractor.name}</p>
          </div>
        </div>
        <button 
          onClick={handleSave}
          className="bg-blue-600 text-white px-5 py-2.5 rounded-xl flex items-center gap-2 font-bold shadow-lg shadow-blue-200 active:scale-95 transition-all"
        >
          <Save className="w-4 h-4" /> Onayla
        </button>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-3">
          <div className="p-2 bg-indigo-50 rounded-lg"><Percent className="w-4 h-4 text-indigo-600" /></div>
          <div>
            <p className="text-[9px] text-slate-400 font-bold uppercase">KDV (%)</p>
            <select value={vatRate} onChange={(e) => setVatRate(Number(e.target.value))} className="text-xs font-bold text-slate-700 bg-transparent focus:outline-none">
              <option value={0}>%0</option><option value={10}>%10</option><option value={20}>%20</option>
            </select>
          </div>
        </div>
        <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-3">
          <div className="p-2 bg-orange-50 rounded-lg"><ShieldCheck className="w-4 h-4 text-orange-600" /></div>
          <div>
            <p className="text-[9px] text-slate-400 font-bold uppercase">Teminat (%)</p>
            <select value={retentionRate} onChange={(e) => setRetentionRate(Number(e.target.value))} className="text-xs font-bold text-slate-700 bg-transparent focus:outline-none">
              <option value={0}>%0</option><option value={3}>%3</option><option value={5}>%5</option>
            </select>
          </div>
        </div>
      </div>

      <div className="space-y-4">
        {itemProgress.map(item => (
          <div key={item.id} className={`bg-white rounded-3xl border transition-all ${item.isExceeding ? 'border-red-200' : 'border-slate-100 shadow-sm'}`}>
            <div className="p-5 space-y-4">
              <div className="flex justify-between items-start">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-[9px] font-black bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded uppercase tracking-tighter">Poz: {item.pozNo || 'Özel'}</span>
                    <h4 className="text-sm font-bold text-slate-800">{item.description}</h4>
                  </div>
                  <p className="text-[10px] text-slate-400 font-medium">Birim Fiyat: {item.unitPrice.toLocaleString('tr-TR')} TL / {item.unit}</p>
                </div>
              </div>

              <div className="grid grid-cols-3 gap-3">
                <div className="space-y-1">
                  <label className="text-[9px] font-bold text-slate-400 uppercase ml-1">Önceki Toplam</label>
                  <div className="bg-slate-50 p-2 rounded-xl text-xs font-bold text-slate-600 text-center">{item.prevTotal}</div>
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-bold text-slate-400 uppercase ml-1">Bu Dönem</label>
                  <input 
                    type="number" 
                    value={item.thisPeriod || ''} 
                    onChange={(e) => setQuantities({ ...quantities, [item.id]: parseFloat(e.target.value) || 0 })}
                    className="w-full bg-blue-50/50 border border-blue-100 rounded-xl p-2 text-xs font-black text-blue-700 text-center focus:ring-2 focus:ring-blue-500 outline-none"
                    placeholder="0"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-bold text-slate-400 uppercase ml-1">Kümülatif</label>
                  <div className="bg-slate-50 p-2 rounded-xl text-xs font-black text-slate-800 text-center">{item.cumulative}</div>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="bg-slate-900 text-white rounded-[2.5rem] p-8 space-y-5 shadow-2xl relative overflow-hidden">
        <div className="flex justify-between items-center text-xs text-slate-400 font-bold uppercase tracking-widest border-b border-slate-800 pb-3">
          <span>Hakediş İcmal Özeti</span>
          <Gavel className="w-4 h-4 opacity-50" />
        </div>

        <div className="space-y-3">
          <div className="flex justify-between text-sm">
            <span className="text-slate-400">Brüt İmalat Tutarı</span>
            <span className="font-bold">{summary.currentTotal.toLocaleString('tr-TR')} TL</span>
          </div>
          <div className="flex justify-between text-sm">
            <span className="text-slate-400">Teminat Kesintisi (%{retentionRate})</span>
            <span className="font-bold text-orange-400">-{summary.retentionAmount.toLocaleString('tr-TR')} TL</span>
          </div>
          <div className="flex justify-between text-sm">
            <span className="text-slate-400">Damga Vergisi (%0,948)</span>
            <span className="font-bold text-red-400">-{summary.stampDutyAmount.toLocaleString('tr-TR')} TL</span>
          </div>
          <div className="flex justify-between text-sm">
            <span className="text-slate-400">KDV (%{vatRate})</span>
            <span className="font-bold text-blue-400">+{summary.vatAmount.toLocaleString('tr-TR')} TL</span>
          </div>
          <div className="pt-4 mt-2 border-t border-slate-800">
            <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.3em] mb-1">Net Ödenecek (Elinize Geçecek)</p>
            <p className="text-3xl font-black text-white">{summary.netPayable.toLocaleString('tr-TR')} <span className="text-lg text-slate-500">TL</span></p>
          </div>
        </div>
      </div>
    </div>
  );
};

