import React, { useState } from 'react';
import { Transaction, Project } from '../types';
import { Plus, Search, TrendingUp, TrendingDown, Wallet, Calendar, Tag } from 'lucide-react';

interface TransactionListProps {
  transactions: Transaction[];
  projects: Project[];
  onAdd: () => void;
}

const TransactionList: React.FC<TransactionListProps> = ({ transactions, projects, onAdd }) => {
  const [filter, setFilter] = useState('');

  const sorted = [...transactions].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  const filtered = sorted.filter(t => 
    t.description.toLowerCase().includes(filter.toLowerCase()) ||
    t.category.toLowerCase().includes(filter.toLowerCase())
  );

  const totalIncome = transactions.filter(t => t.type === 'income').reduce((sum, t) => sum + t.amount, 0);
  const totalExpense = transactions.filter(t => t.type === 'expense').reduce((sum, t) => sum + t.amount, 0);

  return (
    <div className="space-y-6 pb-24 animate-in fade-in duration-500">
      <div className="flex justify-between items-center px-1">
        <div>
          <h1 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Proje Kasası</h1>
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Gelir ve Gider Takibi</p>
        </div>
        <button 
          onClick={onAdd}
          className="bg-slate-900 text-white p-3 rounded-2xl shadow-lg active:scale-95 transition-all flex items-center gap-2"
        >
          <Plus className="w-5 h-5" />
          <span className="text-xs font-bold uppercase tracking-widest">Kayıt Ekle</span>
        </button>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div className="bg-emerald-50 p-4 rounded-3xl border border-emerald-100">
          <p className="text-[9px] font-black text-emerald-600 uppercase tracking-widest mb-1">Toplam Gelir</p>
          <p className="text-lg font-black text-emerald-700">{totalIncome.toLocaleString('tr-TR')} TL</p>
        </div>
        <div className="bg-rose-50 p-4 rounded-3xl border border-rose-100">
          <p className="text-[9px] font-black text-rose-600 uppercase tracking-widest mb-1">Toplam Gider</p>
          <p className="text-lg font-black text-rose-700">{totalExpense.toLocaleString('tr-TR')} TL</p>
        </div>
      </div>

      <div className="relative">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
