          type="text" 
          placeholder="İşlem veya kategori ara..." 
          className="w-full pl-12 pr-4 py-4 bg-white border border-slate-200 rounded-[2rem] focus:outline-none focus:ring-2 focus:ring-slate-500 shadow-sm text-sm"
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
        />
      </div>

      <div className="space-y-3">
        {filtered.length === 0 ? (
          <div className="text-center py-16 bg-white rounded-[2.5rem] border border-dashed border-slate-200">
            <Wallet className="w-12 h-12 text-slate-200 mx-auto mb-3" />
            <p className="text-slate-400 text-sm font-bold uppercase">Kayıt bulunamadı</p>
          </div>
        ) : (
          filtered.map(t => {
            const project = projects.find(p => p.id === t.projectId);
            return (
              <div key={t.id} className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm flex items-center gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${t.type === 'income' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                  {t.type === 'income' ? <TrendingUp className="w-6 h-6" /> : <TrendingDown className="w-6 h-6" />}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex justify-between items-start">
                    <h4 className="text-sm font-bold text-slate-800 truncate">{t.description}</h4>
                    <span className={`text-sm font-black whitespace-nowrap ml-2 ${t.type === 'income' ? 'text-emerald-600' : 'text-rose-600'}`}>
                      {t.type === 'income' ? '+' : '-'}{t.amount.toLocaleString('tr-TR')} TL
                    </span>
                  </div>
                  <div className="flex items-center gap-3 mt-1 text-[9px] font-bold uppercase tracking-tighter text-slate-400">
                    <span className="flex items-center gap-1"><Tag className="w-3 h-3" /> {t.category}</span>
                    <span className="flex items-center gap-1"><Calendar className="w-3 h-3" /> {new Date(t.date).toLocaleDateString('tr-TR')}</span>
                  </div>
                  <p className="text-[8px] text-slate-300 font-bold uppercase mt-0.5 truncate">{project?.name}</p>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

