import React, { useState, useEffect } from 'react';
import { Subcontractor, ProgressPayment, Project, Contract, Transaction } from './types';
import Dashboard from './components/Dashboard';
import SubcontractorList from './components/SubcontractorList';
import SubcontractorDetail from './components/SubcontractorDetail';
import ProgressPaymentForm from './components/ProgressPaymentForm';
import Reports from './components/Reports';
import AllPaymentsList from './components/AllPaymentsList';
import ProjectList from './components/ProjectList';
import ProjectForm from './components/ProjectForm';
import ContractForm from './components/ContractForm';
import TransactionList from './components/TransactionList';
import TransactionForm from './components/TransactionForm';
import { LayoutDashboard, Users, BarChart3, Building2, BookOpen, ReceiptText, Wallet } from 'lucide-react';

const STORAGE_KEY = 'hakedis_app_data_v2';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<'dashboard' | 'subcontractors' | 'all-payments' | 'reports' | 'detail' | 'payment-form' | 'add-sub' | 'projects' | 'add-project' | 'contracts' | 'add-contract' | 'transactions' | 'add-transaction'>('dashboard');

  const [projects, setProjects] = useState<Project[]>([]);
  const [subcontractors, setSubcontractors] = useState<Subcontractor[]>([]);
  const [contracts, setContracts] = useState<Contract[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  const [selectedContractId, setSelectedContractId] = useState<string | null>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const data = JSON.parse(saved);
      setProjects(data.projects || []);
      setSubcontractors(data.subcontractors || []);
      setContracts(data.contracts || []);
      setTransactions(data.transactions || []);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ projects, subcontractors, contracts, transactions }));
  }, [projects, subcontractors, contracts, transactions]);

  const handleAddProject = (p: Project) => {
    setProjects([...projects, p]);
    setActiveView('projects');
  };

  const handleAddSubcontractor = (s: Subcontractor) => {
    setSubcontractors([...subcontractors, s]);
    setActiveView('subcontractors');
  };

  const handleAddContract = (c: Contract) => {
    setContracts([...contracts, c]);
    setActiveView('contracts');
  };

  const handleAddTransaction = (t: Transaction) => {
    setTransactions([...transactions, t]);
    setActiveView('transactions');
  };

  const handleUpdateContract = (updated: Contract) => {
    setContracts(prev => prev.map(c => c.id === updated.id ? updated : c));
  };

  const handleAddPayment = (payment: ProgressPayment) => {
    setContracts(prev => prev.map(c => {
      if (c.id === payment.contractId) {
        return {
          ...c,
          progressPayments: [...c.progressPayments, payment]
        };
      }
      return c;
    }));
    setActiveView('detail');
  };

  const selectedContract = contracts.find(c => c.id === selectedContractId);

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return <Dashboard subcontractors={subcontractors} projects={projects} contracts={contracts} transactions={transactions} />;
      case 'projects':
        return <ProjectList projects={projects} onAdd={() => setActiveView('add-project')} onSelect={() => {}} />;
      case 'add-project':
        return <ProjectForm onCancel={() => setActiveView('projects')} onSave={handleAddProject} />;
      case 'transactions':
        return <TransactionList transactions={transactions} projects={projects} onAdd={() => setActiveView('add-transaction')} />;
      case 'add-transaction':
        return <TransactionForm projects={projects} onCancel={() => setActiveView('transactions')} onSave={handleAddTransaction} />;
      case 'all-payments':
        return (
          <AllPaymentsList 
            contracts={contracts} 
            subcontractors={subcontractors} 
            onSelectContract={(id) => {
              setSelectedContractId(id);
              setActiveView('detail');
            }} 
          />
        );
      case 'contracts':
        return (
          <div className="space-y-6 pb-24">
            <div className="flex justify-between items-center px-1">
              <h1 className="text-2xl font-bold text-slate-800">Sözleşmeler</h1>
              <button 
                onClick={() => setActiveView('add-contract')}
                className="bg-blue-600 text-white p-3 rounded-2xl shadow-lg shadow-blue-200 active:scale-95 transition-all flex items-center gap-2"
              >
                <BookOpen className="w-5 h-5" />
                <span className="text-xs font-bold uppercase">Sözleşme Tanımla</span>
              </button>
            </div>
            <div className="space-y-4">
              {contracts.length === 0 ? (
                <div className="text-center py-20 bg-white rounded-[2.5rem] border border-dashed border-slate-200">
                  <BookOpen className="w-12 h-12 text-slate-200 mx-auto mb-3" />
                  <p className="text-slate-400 text-sm">Henüz bir sözleşme tanımlanmamış.</p>
                </div>
              ) : (
                contracts.map(c => {
                  const project = projects.find(p => p.id === c.projectId);
                  const sub = subcontractors.find(s => s.id === c.subcontractorId);
                  return (
                    <button 
                      key={c.id} 
                      onClick={() => { setSelectedContractId(c.id); setActiveView('detail'); }}
                      className="w-full text-left bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm hover:border-blue-100 transition-all flex flex-col gap-3"
                    >
                      <div className="flex justify-between items-start">
                        <div>
                          <h3 className="font-black text-slate-800 text-sm uppercase">{c.title}</h3>
                          <p className="text-[10px] font-bold text-slate-400 mt-0.5">{project?.name} / {sub?.name}</p>
                        </div>
                        <span className="bg-blue-50 text-blue-600 text-[10px] font-black px-3 py-1 rounded-full uppercase">
                          {c.totalValue.toLocaleString('tr-TR')} TL
                        </span>
                      </div>
                      <div className="w-full bg-slate-100 h-1.5 rounded-full overflow-hidden">
                        <div 
                          className="bg-blue-600 h-full rounded-full transition-all duration-1000" 
                          style={{ width: `${Math.min(100, (c.progressPayments[c.progressPayments.length-1]?.summary.cumulativeTotal || 0) / c.totalValue * 100)}%` }}
                        />
                      </div>
                    </button>
                  );
                })
              )}
            </div>
          </div>
        );
      case 'add-contract':
        return <ContractForm projects={projects} subcontractors={subcontractors} onCancel={() => setActiveView('contracts')} onSave={handleAddContract} />;
      case 'subcontractors':
        return <SubcontractorList subcontractors={subcontractors} onSelect={() => {}} onAdd={() => setActiveView('add-sub')} />;
      case 'add-sub':
        return (
          <div className="space-y-6 pb-24">
            <h2 className="text-xl font-bold">Taşeron Ekle</h2>
            <div className="bg-white p-6 rounded-3xl border shadow-sm space-y-4">
               <input 
                type="text" 
                placeholder="İsim" 
                className="w-full p-4 bg-slate-50 border rounded-2xl" 
                onBlur={(e) => {
                  if (e.target.value) handleAddSubcontractor({ id: Math.random().toString(36).substr(2, 9), name: e.target.value, trade: 'Genel' });
                }}
               />
               <button onClick={() => setActiveView('subcontractors')} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-bold">Geri Dön</button>
            </div>
          </div>
        );
      case 'detail':
        return selectedContract ? (
          <SubcontractorDetail 
            subcontractor={{ ...subcontractors.find(s => s.id === selectedContract.subcontractorId)!, contractDate: selectedContract.contractDate, totalContractValue: selectedContract.totalValue, workItems: selectedContract.workItems, progressPayments: selectedContract.progressPayments, contractDocuments: selectedContract.documents }}
            onBack={() => setActiveView('contracts')} 
            onNewPayment={() => setActiveView('payment-form')}
            onUpdate={(updatedSub) => {
               handleUpdateContract({
                 ...selectedContract,
                 workItems: updatedSub.workItems,
                 progressPayments: updatedSub.progressPayments,
                 documents: updatedSub.contractDocuments || []
               });
            }}
          />
        ) : null;
      case 'payment-form':
        return selectedContract ? (
          <ProgressPaymentForm 
            subcontractor={{ ...subcontractors.find(s => s.id === selectedContract.subcontractorId)!, contractDate: selectedContract.contractDate, totalContractValue: selectedContract.totalValue, workItems: selectedContract.workItems, progressPayments: selectedContract.progressPayments, contractDocuments: selectedContract.documents }} 
            onCancel={() => setActiveView('detail')} 
            onSave={(p) => handleAddPayment({ ...p, contractId: selectedContract.id })}
          />
        ) : null;
      case 'reports':
        return <Reports subcontractors={subcontractors} />;
      default:
        return <Dashboard subcontractors={subcontractors} projects={projects} contracts={contracts} transactions={transactions} />;
    }
  };

  return (
    <div className="max-w-md mx-auto min-h-screen relative bg-slate-50 flex flex-col">
      <main className="flex-1 p-5 overflow-y-auto no-scrollbar">
        {renderView()}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/80 backdrop-blur-lg border-t border-slate-200 px-2 py-3 flex justify-between items-center z-50 shadow-2xl">
        <button 
          onClick={() => setActiveView('dashboard')}
          className={`flex flex-col items-center gap-1 transition-all flex-1 ${activeView === 'dashboard' ? 'text-indigo-600' : 'text-slate-400'}`}
        >
          <LayoutDashboard className="w-5 h-5" />
          <span className="text-[8px] font-black uppercase tracking-tighter">Panel</span>
        </button>
        <button 
          onClick={() => setActiveView('projects')}
          className={`flex flex-col items-center gap-1 transition-all flex-1 ${['projects', 'add-project'].includes(activeView) ? 'text-indigo-600' : 'text-slate-400'}`}
        >
          <Building2 className="w-5 h-5" />
          <span className="text-[8px] font-black uppercase tracking-tighter">Proje</span>
        </button>
        <button 
          onClick={() => setActiveView('contracts')}
          className={`flex flex-col items-center gap-1 transition-all flex-1 ${['contracts', 'add-contract', 'detail', 'payment-form'].includes(activeView) ? 'text-indigo-600' : 'text-slate-400'}`}
        >
          <BookOpen className="w-5 h-5" />
          <span className="text-[8px] font-black uppercase tracking-tighter">Sözleşme</span>
        </button>
        <button 
          onClick={() => setActiveView('transactions')}
          className={`flex flex-col items-center gap-1 transition-all flex-1 ${['transactions', 'add-transaction'].includes(activeView) ? 'text-indigo-600' : 'text-slate-400'}`}
        >
          <Wallet className="w-5 h-5" />
          <span className="text-[8px] font-black uppercase tracking-tighter">Kasa</span>
        </button>
        <button 
          onClick={() => setActiveView('all-payments')}
          className={`flex flex-col items-center gap-1 transition-all flex-1 ${activeView === 'all-payments' ? 'text-indigo-600' : 'text-slate-400'}`}
        >
          <ReceiptText className="w-5 h-5" />
          <span className="text-[8px] font-black uppercase tracking-tighter">Hakediş</span>
        </button>
      </nav>
    </div>
  );
};

export default App;

import React from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer 
} from 'recharts';
import { Subcontractor, Project, Contract, Transaction } from '../types';
import { TrendingUp, Activity, Wallet, Landmark, DollarSign } from 'lucide-react';

interface DashboardProps {
  subcontractors: Subcontractor[];
  projects: Project[];
  contracts: Contract[];
  transactions: Transaction[];
}

const Dashboard: React.FC<DashboardProps> = ({ subcontractors, projects, contracts, transactions }) => {
  // Consolidated Income: From Client (Income transactions)
  const totalIncome = transactions.filter(t => t.type === 'income').reduce((sum, t) => sum + t.amount, 0);

  // Consolidated Costs: Subcontractor Payments + Misc Expenses
  const subCosts = contracts.reduce((sum, c) => {
    const lastPayment = c.progressPayments[c.progressPayments.length - 1];
    return sum + (lastPayment?.summary.cumulativeTotal || 0);
  }, 0);

  const miscExpenses = transactions.filter(t => t.type === 'expense').reduce((sum, t) => sum + t.amount, 0);
  const totalCost = subCosts + miscExpenses;
  const balance = totalIncome - totalCost;

  const chartData = projects.map(p => {
    const projIncome = transactions.filter(t => t.projectId === p.id && t.type === 'income').reduce((sum, t) => sum + t.amount, 0);
    const projContracts = contracts.filter(c => c.projectId === p.id);
    const projSubCosts = projContracts.reduce((sum, c) => {
      const last = c.progressPayments[c.progressPayments.length-1];
      return sum + (last?.summary.cumulativeTotal || 0);
    }, 0);
    const projMiscCosts = transactions.filter(t => t.projectId === p.id && t.type === 'expense').reduce((sum, t) => sum + t.amount, 0);

    return {
      name: p.name.length > 8 ? p.name.substring(0, 8) + '...' : p.name,
      Gelir: projIncome,
      Maliyet: projSubCosts + projMiscCosts,
    };
  });

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-700">
      <div className="flex items-center gap-3 px-2">
        <div className="bg-indigo-600 p-2 rounded-xl text-white shadow-lg shadow-indigo-200">
          <Landmark className="w-5 h-5" />
        </div>
        <h1 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Finansal Durum</h1>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-100 relative overflow-hidden group">
          <Activity className="absolute -right-2 -bottom-2 w-12 h-12 text-slate-50 group-hover:scale-110 transition-transform" />
          <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest mb-1">Toplam Tahsilat</p>
          <p className="text-2xl font-black text-slate-800">{totalIncome.toLocaleString('tr-TR')} TL</p>
        </div>
        <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-100 relative overflow-hidden group">
          <Wallet className="absolute -right-2 -bottom-2 w-12 h-12 text-slate-50 group-hover:scale-110 transition-transform" />
          <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest mb-1">Toplam Maliyet</p>
          <p className="text-2xl font-black text-rose-600">{totalCost.toLocaleString('tr-TR')} TL</p>
        </div>

        <div className={`p-6 rounded-[2.5rem] shadow-xl flex flex-col col-span-2 text-white relative overflow-hidden transition-colors ${balance >= 0 ? 'bg-slate-900' : 'bg-rose-900'}`}>
          <div className="absolute top-0 right-0 p-8 opacity-10"><TrendingUp className="w-24 h-24" /></div>
          <div className="relative z-10 space-y-2">
            <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Kasa Net Bakiyesi (Kar/Zarar)</p>
            <div className="flex items-end gap-2">
              <p className="text-4xl font-black text-white">{balance.toLocaleString('tr-TR')}</p>
              <p className="text-lg font-bold text-slate-500 mb-1">TL</p>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100">
        <div className="flex items-center justify-between mb-6">
          <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Nakıt Akış Analizi (Gelir vs Maliyet)</h3>
          <DollarSign className="w-4 h-4 text-slate-200" />
        </div>
        <div className="h-64 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" fontSize={10} axisLine={false} tickLine={false} />
              <Tooltip cursor={{fill: '#f8fafc'}} />
              <Bar dataKey="Gelir" fill="#10b981" radius={[6, 6, 0, 0]} />
              <Bar dataKey="Maliyet" fill="#ef4444" radius={[6, 6, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

