import React, { useState, useEffect } from 'react';
import { Subcontractor, ProgressPayment, Project, Contract, Transaction } from './types';
import Dashboard from './components/Dashboard';
import SubcontractorList from './components/SubcontractorList';
import SubcontractorDetail from './components/SubcontractorDetail';
import ProgressPaymentForm from './components/ProgressPaymentForm';
import Reports from './components/Reports';
import AllPaymentsList from './components/AllPaymentsList';
import ProjectList from './components/ProjectList';
import ProjectForm from './components/ProjectForm';
import ContractForm from './components/ContractForm';
import TransactionList from './components/TransactionList';
import TransactionForm from './components/TransactionForm';
import { 
  LayoutGrid, 
  Building, 
  FileSignature, 
  Coins, 
  Receipt, 
  BarChart2 
} from 'lucide-react';

const STORAGE_KEY = 'hakedis_app_data_v2';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<'dashboard' | 'subcontractors' | 'all-payments' | 'reports' | 'detail' | 'payment-form' | 'add-sub' | 'projects' | 'add-project' | 'contracts' | 'add-contract' | 'transactions' | 'add-transaction'>('dashboard');

  const [projects, setProjects] = useState<Project[]>([]);
  const [subcontractors, setSubcontractors] = useState<Subcontractor[]>([]);
  const [contracts, setContracts] = useState<Contract[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  const [selectedContractId, setSelectedContractId] = useState<string | null>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const data = JSON.parse(saved);
      setProjects(data.projects || []);
      setSubcontractors(data.subcontractors || []);
      setContracts(data.contracts || []);
      setTransactions(data.transactions || []);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ projects, subcontractors, contracts, transactions }));
  }, [projects, subcontractors, contracts, transactions]);

  const handleAddProject = (p: Project) => {
    setProjects([...projects, p]);
    setActiveView('projects');
  };

  const handleAddSubcontractor = (s: Subcontractor) => {
    setSubcontractors([...subcontractors, s]);
    setActiveView('subcontractors');
  };

  const handleAddContract = (c: Contract) => {
    setContracts([...contracts, c]);
    setActiveView('contracts');
  };

  const handleAddTransaction = (t: Transaction) => {
    setTransactions([...transactions, t]);
    setActiveView('transactions');
  };

  const handleUpdateContract = (updated: Contract) => {
    setContracts(prev => prev.map(c => c.id === updated.id ? updated : c));
  };

  const handleAddPayment = (payment: ProgressPayment) => {
    setContracts(prev => prev.map(c => {
      if (c.id === payment.contractId) {
        return {
          ...c,
          progressPayments: [...c.progressPayments, payment]
        };
      }
      return c;
    }));
    setActiveView('detail');
  };

  const selectedContract = contracts.find(c => c.id === selectedContractId);

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return <Dashboard subcontractors={subcontractors} projects={projects} contracts={contracts} transactions={transactions} />;
      case 'projects':
        return <ProjectList projects={projects} onAdd={() => setActiveView('add-project')} onSelect={() => {}} />;
      case 'add-project':
        return <ProjectForm onCancel={() => setActiveView('projects')} onSave={handleAddProject} />;
      case 'transactions':
        return <TransactionList transactions={transactions} projects={projects} onAdd={() => setActiveView('add-transaction')} />;
      case 'add-transaction':
        return <TransactionForm projects={projects} onCancel={() => setActiveView('transactions')} onSave={handleAddTransaction} />;
      case 'all-payments':
        return (
          <AllPaymentsList 
            contracts={contracts} 
            subcontractors={subcontractors} 
            onSelectContract={(id) => {
              setSelectedContractId(id);
              setActiveView('detail');
            }} 
          />
        );
      case 'contracts':
        return (
          <div className="space-y-6 pb-24">
            <div className="flex justify-between items-center px-1">
              <h1 className="text-2xl font-bold text-slate-800">Sözleşmeler</h1>
              <button 
                onClick={() => setActiveView('add-contract')}
                className="bg-blue-600 text-white p-3 rounded-2xl shadow-lg shadow-blue-200 active:scale-95 transition-all flex items-center gap-2"
              >
                <FileSignature className="w-5 h-5" />
                <span className="text-xs font-bold uppercase">Sözleşme Tanımla</span>
              </button>
            </div>
            <div className="space-y-4">
              {contracts.length === 0 ? (
                <div className="text-center py-20 bg-white rounded-[2.5rem] border border-dashed border-slate-200">
                  <FileSignature className="w-12 h-12 text-slate-200 mx-auto mb-3" />
                  <p className="text-slate-400 text-sm">Henüz bir sözleşme tanımlanmamış.</p>
                </div>
              ) : (
                contracts.map(c => {
                  const project = projects.find(p => p.id === c.projectId);
                  const sub = subcontractors.find(s => s.id === c.subcontractorId);
                  return (
                    <button 
                      key={c.id} 
                      onClick={() => { setSelectedContractId(c.id); setActiveView('detail'); }}
                      className="w-full text-left bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm hover:border-blue-100 transition-all flex flex-col gap-3"
                    >
                      <div className="flex justify-between items-start">
                        <div>
                          <h3 className="font-black text-slate-800 text-sm uppercase">{c.title}</h3>
                          <p className="text-[10px] font-bold text-slate-400 mt-0.5">{project?.name} / {sub?.name}</p>
                        </div>
                        <span className="bg-blue-50 text-blue-600 text-[10px] font-black px-3 py-1 rounded-full uppercase">
                          {c.totalValue.toLocaleString('tr-TR')} TL
                        </span>
                      </div>
                      <div className="w-full bg-slate-100 h-1.5 rounded-full overflow-hidden">
                        <div 
                          className="bg-blue-600 h-full rounded-full transition-all duration-1000" 
                          style={{ width: `${Math.min(100, (c.progressPayments[c.progressPayments.length-1]?.summary.cumulativeTotal || 0) / c.totalValue * 100)}%` }}
                        />
                      </div>
                    </button>
                  );
                })
              )}
            </div>
          </div>
        );
      case 'add-contract':
        return <ContractForm projects={projects} subcontractors={subcontractors} onCancel={() => setActiveView('contracts')} onSave={handleAddContract} />;
      case 'subcontractors':
        return <SubcontractorList subcontractors={subcontractors} onSelect={() => {}} onAdd={() => setActiveView('add-sub')} />;
      case 'add-sub':
        return (
          <div className="space-y-6 pb-24">
            <h2 className="text-xl font-bold">Taşeron Ekle</h2>
            <div className="bg-white p-6 rounded-3xl border shadow-sm space-y-4">
               <input 
                type="text" 
                placeholder="İsim" 
                className="w-full p-4 bg-slate-50 border rounded-2xl" 
                onBlur={(e) => {
                  if (e.target.value) handleAddSubcontractor({ id: Math.random().toString(36).substr(2, 9), name: e.target.value, trade: 'Genel' });
                }}
               />
               <button onClick={() => setActiveView('subcontractors')} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-bold">Geri Dön</button>
            </div>
          </div>
        );
      case 'detail':
        return selectedContract ? (
          <SubcontractorDetail 
            subcontractor={{ ...subcontractors.find(s => s.id === selectedContract.subcontractorId)!, contractDate: selectedContract.contractDate, totalContractValue: selectedContract.totalValue, workItems: selectedContract.workItems, progressPayments: selectedContract.progressPayments, contractDocuments: selectedContract.documents }}
            onBack={() => setActiveView('contracts')} 
            onNewPayment={() => setActiveView('payment-form')}
            onUpdate={(updatedSub) => {
               handleUpdateContract({
                 ...selectedContract,
                 workItems: updatedSub.workItems,
                 progressPayments: updatedSub.progressPayments,
                 documents: updatedSub.contractDocuments || []
               });
            }}
          />
        ) : null;
      case 'payment-form':
        return selectedContract ? (
          <ProgressPaymentForm 
            subcontractor={{ ...subcontractors.find(s => s.id === selectedContract.subcontractorId)!, contractDate: selectedContract.contractDate, totalContractValue: selectedContract.totalValue, workItems: selectedContract.workItems, progressPayments: selectedContract.progressPayments, contractDocuments: selectedContract.documents }} 
            onCancel={() => setActiveView('detail')} 
            onSave={(p) => handleAddPayment({ ...p, contractId: selectedContract.id })}
          />
        ) : null;
      case 'reports':
        return <Reports subcontractors={subcontractors} transactions={transactions} />;
      default:
        return <Dashboard subcontractors={subcontractors} projects={projects} contracts={contracts} transactions={transactions} />;
    }
  };

  const NavItem = ({ view, icon: Icon, label, activeViews = [] }: { view: any, icon: any, label: string, activeViews?: string[] }) => {
    const isActive = activeView === view || activeViews.includes(activeView);
    return (
      <button 
        onClick={() => setActiveView(view)}
        className={`flex flex-col items-center justify-center gap-1 transition-all duration-300 relative px-2 py-1.5 rounded-2xl flex-1 ${
          isActive 
            ? 'text-indigo-600 bg-indigo-50/60' 
            : 'text-slate-400 hover:text-slate-600'
        }`}
      >
        <Icon className={`w-5 h-5 transition-transform duration-300 ${isActive ? 'scale-110 stroke-[2.5px]' : 'stroke-2'}`} />
        <span className={`text-[10px] uppercase tracking-tight leading-none ${isActive ? 'font-bold' : 'font-medium'}`}>
          {label}
        </span>
        {isActive && (
          <span className="absolute -bottom-1 w-1 h-1 bg-indigo-600 rounded-full shadow-[0_0_8px_rgba(79,70,229,0.8)]" />
        )}
      </button>
    );
  };

  return (
    <div className="max-w-md mx-auto min-h-screen relative bg-slate-50 flex flex-col selection:bg-indigo-100">
      <main className="flex-1 p-5 overflow-y-auto no-scrollbar">
        {renderView()}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/90 backdrop-blur-xl border-t border-slate-100 px-3 py-3 flex justify-between items-center z-50 shadow-[0_-10px_30px_-5px_rgba(0,0,0,0.05)]">
        <NavItem view="dashboard" icon={LayoutGrid} label="Panel" />
        <NavItem view="projects" icon={Building} label="Proje" activeViews={['add-project']} />
        <NavItem view="contracts" icon={FileSignature} label="Sözleşme" activeViews={['add-contract', 'detail', 'payment-form']} />
        <NavItem view="transactions" icon={Coins} label="Kasa" activeViews={['add-transaction']} />
        <NavItem view="all-payments" icon={Receipt} label="Hakediş" />
        <NavItem view="reports" icon={BarChart2} label="Rapor" />
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Legend, Cell 
} from 'recharts';
import { Subcontractor, Transaction } from '../types';
import { Calendar, TrendingUp, PieChart as PieChartIcon, Sparkles, Info, CheckCircle2, BarChart3, Wallet } from 'lucide-react';
import { analyzeProjectHealth } from '../services/geminiService';

interface ReportsProps {
  subcontractors: Subcontractor[];
  transactions: Transaction[];
}

type Range = '30d' | '90d' | 'all';

// Custom Tooltip for the Cash Flow (Trend) Chart
const CustomTrendTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    const data = payload[0].payload;
    return (
      <div className="bg-white/95 backdrop-blur-md p-4 border border-slate-100 shadow-2xl rounded-2xl animate-in zoom-in-95 duration-200">
        <p className="text-xs font-bold text-slate-400 uppercase mb-2 tracking-wider">{label}</p>
        <p className="text-lg font-black text-blue-600 mb-2">
          {payload[0].value.toLocaleString('tr-TR')} TL
        </p>
        <div className="space-y-1 border-t border-slate-50 pt-2">
          <p className="text-[10px] font-bold text-slate-500 mb-1">DÖNEM ÖDEMELERİ:</p>
          {data.details.map((d: any, i: number) => (
            <div key={i} className="flex justify-between gap-4 text-[10px]">
              <span className="text-slate-600 font-medium">{d.name}</span>
              <span className="text-slate-900 font-bold">{d.amount.toLocaleString('tr-TR')} TL</span>
            </div>
          ))}
        </div>
      </div>
    );
  }
  return null;
};

// Custom Tooltip for the Progress Comparison Chart
const CustomProgressTooltip = ({ active, payload }: any) => {
  if (active && payload && payload.length) {
    const data = payload[0].payload;
    return (
      <div className="bg-white/95 backdrop-blur-md p-4 border border-slate-100 shadow-2xl rounded-2xl animate-in zoom-in-95 duration-200">
        <p className="text-sm font-bold text-slate-800 mb-1">{data.fullName}</p>
        <div className="space-y-2 mt-2">
          <div className="flex justify-between items-center gap-6">
            <span className="text-[10px] font-bold text-slate-400 uppercase">Tamamlanma Oranı</span>
            <span className="text-xs font-bold text-indigo-600">%{data.percent}</span>
          </div>
          <div className="flex justify-between items-center gap-6 border-t border-slate-50 pt-2">
            <span className="text-[10px] font-bold text-slate-400 uppercase">Ödenen Tutar</span>
            <span className="text-xs font-bold text-slate-700">{data.paidAmount.toLocaleString('tr-TR')} TL</span>
          </div>
          <div className="flex justify-between items-center gap-6">
            <span className="text-[10px] font-bold text-slate-400 uppercase">Toplam Sözleşme</span>
            <span className="text-xs font-bold text-slate-500">{data.totalValue.toLocaleString('tr-TR')} TL</span>
          </div>
        </div>
      </div>
    );
  }
  return null;
};

const Reports: React.FC<ReportsProps> = ({ subcontractors, transactions }) => {
  const [range, setRange] = useState<Range>('all');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiInsight, setAiInsight] = useState<string | null>(null);

  const filteredData = useMemo(() => {
    const now = new Date();
    const rangeLimit = range === '30d' ? 30 : range === '90d' ? 90 : Infinity;

    const allPayments = subcontractors.flatMap(s => 
      (s.progressPayments || []).map(p => ({
        ...p,
        subName: s.name,
        dateObj: new Date(p.date)
      }))
    ).filter(p => {
      if (range === 'all') return true;
      const diffDays = (now.getTime() - p.dateObj.getTime()) / (1000 * 3600 * 24);
      return diffDays <= rangeLimit;
    });

    return allPayments.sort((a, b) => a.dateObj.getTime() - b.dateObj.getTime());
  }, [subcontractors, range]);

  const stats = useMemo(() => {
    const totalPaid = filteredData.reduce((sum, p) => sum + p.summary.currentTotal, 0);
    const totalRetention = filteredData.reduce((sum, p) => sum + p.summary.retentionAmount, 0);
    const paymentCount = filteredData.length;
    return { totalPaid, totalRetention, paymentCount };
  }, [filteredData]);

  const trendData = useMemo(() => {
    const groups: Record<string, { total: number; details: {name: string, amount: number}[] }> = {};
    filteredData.forEach(p => {
      const month = p.dateObj.toLocaleDateString('tr-TR', { month: 'short', year: '2-digit' });
      if (!groups[month]) {
        groups[month] = { total: 0, details: [] };
      }
      groups[month].total += p.summary.currentTotal;

      const existing = groups[month].details.find(d => d.name === p.subName);
      if (existing) {
        existing.amount += p.summary.currentTotal;
      } else {
        groups[month].details.push({ name: p.subName, amount: p.summary.currentTotal });
      }
    });
    return Object.entries(groups).map(([name, data]) => ({ 
      name, 
      total: data.total, 
      details: data.details.sort((a,b) => b.amount - a.amount) 
    }));
  }, [filteredData]);

  const subProgressData = useMemo(() => {
    return subcontractors
      .filter(s => (s.totalContractValue || 0) > 0)
      .map(s => {
        const paid = (s.progressPayments || []).reduce((sum, p) => sum + p.summary.currentTotal, 0);
        const percent = Math.round((paid / (s.totalContractValue || 1)) * 100) || 0;
        return {
          name: s.name.length > 8 ? s.name.substring(0, 8) + '...' : s.name,
          fullName: s.name,
          percent: percent,
          paidAmount: paid,
          totalValue: s.totalContractValue || 0
        };
      })
      .sort((a, b) => b.percent - a.percent);
  }, [subcontractors]);

  const financialTrendData = useMemo(() => {
    const now = new Date();
    const rangeLimit = range === '30d' ? 30 : range === '90d' ? 90 : Infinity;

    const filteredTransactions = transactions.filter(t => {
      if (range === 'all') return true;
      const date = new Date(t.date);
      const diffDays = (now.getTime() - date.getTime()) / (1000 * 3600 * 24);
      return diffDays <= rangeLimit;
    });

    const groups: Record<string, { income: number; expense: number }> = {};

    filteredTransactions.forEach(t => {
      const month = new Date(t.date).toLocaleDateString('tr-TR', { month: 'short', year: '2-digit' });
      if (!groups[month]) groups[month] = { income: 0, expense: 0 };
      if (t.type === 'income') groups[month].income += t.amount;
      else groups[month].expense += t.amount;
    });

    return Object.entries(groups).map(([name, data]) => ({
      name,
      Gelir: data.income,
      Gider: data.expense
    }));
  }, [transactions, range]);

  const handleProjectAnalysis = async () => {
    setIsAnalyzing(true);
    const result = await analyzeProjectHealth(subcontractors);
    setAiInsight(result);
    setIsAnalyzing(false);
  };

  return (
