interface DashboardProps {
  subcontractors: Subcontractor[];
  projects: Project[];
  contracts: Contract[];
  transactions: Transaction[];
}

const Dashboard: React.FC<DashboardProps> = ({ subcontractors, projects, contracts, transactions }) => {
  const totalIncome = transactions.filter(t => t.type === 'income').reduce((sum, t) => sum + t.amount, 0);

  const subCosts = contracts.reduce((sum, c) => {
    const lastPayment = c.progressPayments[c.progressPayments.length - 1];
    return sum + (lastPayment?.summary.cumulativeTotal || 0);
  }, 0);

  const miscExpenses = transactions.filter(t => t.type === 'expense').reduce((sum, t) => sum + t.amount, 0);
  const totalCost = subCosts + miscExpenses;
  const balance = totalIncome - totalCost;

  const chartData = projects.map(p => {
    const projIncome = transactions.filter(t => t.projectId === p.id && t.type === 'income').reduce((sum, t) => sum + t.amount, 0);
    const projContracts = contracts.filter(c => c.projectId === p.id);
    const projSubCosts = projContracts.reduce((sum, c) => {
      const last = c.progressPayments[c.progressPayments.length-1];
      return sum + (last?.summary.cumulativeTotal || 0);
    }, 0);
    const projMiscCosts = transactions.filter(t => t.projectId === p.id && t.type === 'expense').reduce((sum, t) => sum + t.amount, 0);

    return {
      name: p.name.length > 8 ? p.name.substring(0, 8) + '...' : p.name,
      Gelir: projIncome,
      Maliyet: projSubCosts + projMiscCosts,
    };
  });

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-700">
      <div className="flex items-center gap-3 px-2">
        <div className="bg-orange-600 p-2 rounded-xl text-white shadow-lg shadow-orange-200">
          <HardHat className="w-5 h-5" />
        </div>
        <h1 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Finansal Durum</h1>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-100 relative overflow-hidden group">
          <Activity className="absolute -right-2 -bottom-2 w-12 h-12 text-slate-50 group-hover:scale-110 transition-transform" />
          <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest mb-1">Toplam Tahsilat</p>
          <p className="text-2xl font-black text-slate-800">{totalIncome.toLocaleString('tr-TR')} TL</p>
        </div>
        <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-100 relative overflow-hidden group">
          <Wallet className="absolute -right-2 -bottom-2 w-12 h-12 text-slate-50 group-hover:scale-110 transition-transform" />
          <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest mb-1">Toplam Maliyet</p>
          <p className="text-2xl font-black text-rose-600">{totalCost.toLocaleString('tr-TR')} TL</p>
        </div>

        <div className={`p-6 rounded-[2.5rem] shadow-xl flex flex-col col-span-2 text-white relative overflow-hidden transition-colors ${balance >= 0 ? 'bg-slate-900' : 'bg-rose-900'}`}>
          <div className="absolute top-0 right-0 p-8 opacity-10"><TrendingUp className="w-24 h-24" /></div>
          <div className="relative z-10 space-y-2">
            <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Kasa Net Bakiyesi (Kar/Zarar)</p>
            <div className="flex items-end gap-2">
              <p className="text-4xl font-black text-white">{balance.toLocaleString('tr-TR')}</p>
              <p className="text-lg font-bold text-slate-500 mb-1">TL</p>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100">
        <div className="flex items-center justify-between mb-6">
          <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Nakıt Akış Analizi</h3>
          <DollarSign className="w-4 h-4 text-slate-200" />
