};

const CustomProgressTooltip = ({ active, payload }: any) => {
  if (active && payload && payload.length) {
    const data = payload[0].payload;
    return (
      <div className="bg-white/95 backdrop-blur-md p-4 border border-slate-100 shadow-2xl rounded-2xl animate-in zoom-in-95 duration-200">
        <p className="text-sm font-bold text-slate-800 mb-1">{data.fullName}</p>
        <div className="space-y-2 mt-2">
          <div className="flex justify-between items-center gap-6">
            <span className="text-[10px] font-bold text-slate-400 uppercase">Tamamlanma</span>
            <span className="text-xs font-bold text-orange-600">%{data.percent}</span>
          </div>
        </div>
      </div>
    );
  }
  return null;
};

const Reports: React.FC<ReportsProps> = ({ subcontractors, transactions }) => {
  const [range, setRange] = useState<Range>('all');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiInsight, setAiInsight] = useState<string | null>(null);

  const filteredData = useMemo(() => {
    const now = new Date();
    const rangeLimit = range === '30d' ? 30 : range === '90d' ? 90 : Infinity;

    const allPayments = subcontractors.flatMap(s => 
      (s.progressPayments || []).map(p => ({
        ...p,
        subName: s.name,
        dateObj: new Date(p.date)
      }))
    ).filter(p => {
      if (range === 'all') return true;
      const diffDays = (now.getTime() - p.dateObj.getTime()) / (1000 * 3600 * 24);
      return diffDays <= rangeLimit;
    });

    return allPayments.sort((a, b) => a.dateObj.getTime() - b.dateObj.getTime());
  }, [subcontractors, range]);

  const stats = useMemo(() => {
    const totalPaid = filteredData.reduce((sum, p) => sum + p.summary.currentTotal, 0);
    const totalRetention = filteredData.reduce((sum, p) => sum + p.summary.retentionAmount, 0);
    const paymentCount = filteredData.length;
    return { totalPaid, totalRetention, paymentCount };
  }, [filteredData]);

  const trendData = useMemo(() => {
    const groups: Record<string, { total: number; details: {name: string, amount: number}[] }> = {};
    filteredData.forEach(p => {
      const month = p.dateObj.toLocaleDateString('tr-TR', { month: 'short', year: '2-digit' });
      if (!groups[month]) {
        groups[month] = { total: 0, details: [] };
      }
      groups[month].total += p.summary.currentTotal;

      const existing = groups[month].details.find(d => d.name === p.subName);
      if (existing) {
        existing.amount += p.summary.currentTotal;
      } else {
        groups[month].details.push({ name: p.subName, amount: p.summary.currentTotal });
      }
    });
    return Object.entries(groups).map(([name, data]) => ({ 
      name, 
      total: data.total, 
      details: data.details.sort((a,b) => b.amount - a.amount) 
    }));
  }, [filteredData]);

  const subProgressData = useMemo(() => {
    return subcontractors
      .filter(s => (s.totalContractValue || 0) > 0)
      .map(s => {
        const paid = (s.progressPayments || []).reduce((sum, p) => sum + p.summary.currentTotal, 0);
        const percent = Math.round((paid / (s.totalContractValue || 1)) * 100) || 0;
        return {
          name: s.name.length > 8 ? s.name.substring(0, 8) + '...' : s.name,
          fullName: s.name,
          percent: percent,
          paidAmount: paid,
          totalValue: s.totalContractValue || 0
        };
      })
      .sort((a, b) => b.percent - a.percent);
  }, [subcontractors]);

  const financialTrendData = useMemo(() => {
    const now = new Date();
    const rangeLimit = range === '30d' ? 30 : range === '90d' ? 90 : Infinity;

    const filteredTransactions = transactions.filter(t => {
      if (range === 'all') return true;
      const date = new Date(t.date);
      const diffDays = (now.getTime() - date.getTime()) / (1000 * 3600 * 24);
      return diffDays <= rangeLimit;
    });

    const groups: Record<string, { income: number; expense: number }> = {};

    filteredTransactions.forEach(t => {
      const month = new Date(t.date).toLocaleDateString('tr-TR', { month: 'short', year: '2-digit' });
      if (!groups[month]) groups[month] = { income: 0, expense: 0 };
      if (t.type === 'income') groups[month].income += t.amount;
      else groups[month].expense += t.amount;
    });

    return Object.entries(groups).map(([name, data]) => ({
      name,
      Gelir: data.income,
      Gider: data.expense
    }));
  }, [transactions, range]);

  const handleProjectAnalysis = async () => {
    setIsAnalyzing(true);
    const result = await analyzeProjectHealth(subcontractors);
    setAiInsight(result);
    setIsAnalyzing(false);
  };

  return (
    <div className="space-y-6 pb-24 animate-in fade-in duration-500">
      <div className="flex justify-between items-center px-1">
        <div>
          <h1 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Rapor Analiz</h1>
          <p className="text-[10px] text-orange-600 font-bold uppercase tracking-widest mt-1">İlerleme ve Mali Göstergeler</p>
        </div>
        <div className="flex bg-white border border-slate-200 p-1 rounded-2xl shadow-sm">
          {(['30d', '90d', 'all'] as Range[]).map((r) => (
            <button
              key={r}
              onClick={() => setRange(r)}
              className={`px-3 py-1.5 text-[9px] font-black rounded-xl transition-all ${range === r ? 'bg-orange-600 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}
            >
              {r === '30d' ? '30 GÜN' : r === '90d' ? '90 GÜN' : 'TÜMÜ'}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Dönemlik Hakediş</p>
          <p className="text-xl font-black text-orange-600">{stats.totalPaid.toLocaleString('tr-TR')} TL</p>
          <div className="flex items-center gap-1 mt-1 text-[9px] text-emerald-500 font-bold uppercase">
            <CheckCircle2 className="w-3 h-3" /> {stats.paymentCount} Kayıt
          </div>
        </div>
        <div className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Dönemlik Teminat</p>
          <p className="text-xl font-black text-slate-800">{stats.totalRetention.toLocaleString('tr-TR')} TL</p>
          <p className="text-[9px] text-orange-400 mt-1 font-medium uppercase tracking-tighter italic">Emanet Hesap</p>
        </div>
      </div>

      {/* AI Project Insight */}
      <div className="bg-gradient-to-br from-orange-600 to-orange-900 p-6 rounded-[2.5rem] shadow-xl text-white relative overflow-hidden group">
        <div className="absolute top-0 right-0 p-8 opacity-10 rotate-12 group-hover:rotate-45 transition-transform duration-700">
           <Sparkles className="w-24 h-24" />
        </div>
        <div className="relative z-10 space-y-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Sparkles className="w-5 h-5 text-orange-200" />
              <h3 className="text-xs font-black uppercase tracking-widest">Yapay Zeka Proje Analizi</h3>
            </div>
            <button 
              onClick={handleProjectAnalysis}
              disabled={isAnalyzing}
              className="bg-white/10 hover:bg-white/20 disabled:opacity-50 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest backdrop-blur-md border border-white/10 transition-all"
            >
              {isAnalyzing ? 'Analiz Ediliyor...' : 'Yeniden Analiz Et'}
            </button>
          </div>

          {aiInsight ? (
            <div className="text-sm leading-relaxed text-orange-50/90 whitespace-pre-wrap animate-in fade-in duration-500">
              {aiInsight}
            </div>
          ) : (
            <div className="text-sm text-orange-200/60 italic">
              Proje mali sağlığı ve risk analizi için butona tıklayın.
            </div>
          )}
        </div>
      </div>

      <div className="space-y-4">
        <div className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Kasa Nakıt Akışı</h3>
            <Wallet className="w-4 h-4 text-slate-200" />
          </div>
          <div className="h-64 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={financialTrendData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" fontSize={10} axisLine={false} tickLine={false} />
                <YAxis fontSize={10} axisLine={false} tickLine={false} tickFormatter={(value) => `${value/1000}k`} />
                <Tooltip cursor={{fill: '#f8fafc'}} />
                <Legend iconType="circle" wrapperStyle={{fontSize: '10px', fontWeight: 'bold', textTransform: 'uppercase', paddingTop: '10px'}} />
                <Bar dataKey="Gelir" fill="#ea580c" radius={[4, 4, 0, 0]} />
                <Bar dataKey="Gider" fill="#0f172a" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Hakediş Ödeme Trendi</h3>
            <BarChart3 className="w-4 h-4 text-slate-200" />
          </div>
          <div className="h-64 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendData}>
                <defs>
                  <linearGradient id="colorTotal" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#ea580c" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#ea580c" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" fontSize={10} axisLine={false} tickLine={false} />
                <YAxis fontSize={10} axisLine={false} tickLine={false} tickFormatter={(value) => `${value/1000}k`} />
                <Tooltip content={<CustomTrendTooltip />} />
                <Area type="monotone" dataKey="total" stroke="#ea580c" fillOpacity={1} fill="url(#colorTotal)" strokeWidth={3} />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Reports;

import React, { useState, useEffect } from 'react';
