const STORAGE_KEY = 'ahmetoglu_santiye_data_v1';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<'dashboard' | 'subcontractors' | 'all-payments' | 'reports' | 'detail' | 'payment-form' | 'add-sub' | 'projects' | 'add-project' | 'contracts' | 'add-contract' | 'transactions' | 'add-transaction'>('dashboard');

  const [projects, setProjects] = useState<Project[]>([]);
  const [subcontractors, setSubcontractors] = useState<Subcontractor[]>([]);
  const [contracts, setContracts] = useState<Contract[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  const [selectedContractId, setSelectedContractId] = useState<string | null>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const data = JSON.parse(saved);
      setProjects(data.projects || []);
      setSubcontractors(data.subcontractors || []);
      setContracts(data.contracts || []);
      setTransactions(data.transactions || []);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ projects, subcontractors, contracts, transactions }));
  }, [projects, subcontractors, contracts, transactions]);

  const handleAddProject = (p: Project) => {
    setProjects([...projects, p]);
    setActiveView('projects');
  };

  const handleAddSubcontractor = (s: Subcontractor) => {
    setSubcontractors([...subcontractors, s]);
    setActiveView('subcontractors');
  };

  const handleAddContract = (c: Contract) => {
    setContracts([...contracts, c]);
    setActiveView('contracts');
  };

  const handleAddTransaction = (t: Transaction) => {
    setTransactions([...transactions, t]);
    setActiveView('transactions');
  };

  const handleUpdateContract = (updated: Contract) => {
    setContracts(prev => prev.map(c => c.id === updated.id ? updated : c));
  };

  const handleAddPayment = (payment: ProgressPayment) => {
    setContracts(prev => prev.map(c => {
      if (c.id === payment.contractId) {
        return {
          ...c,
          progressPayments: [...c.progressPayments, payment]
        };
      }
      return c;
    }));
    setActiveView('detail');
  };

  const selectedContract = contracts.find(c => c.id === selectedContractId);

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return <Dashboard subcontractors={subcontractors} projects={projects} contracts={contracts} transactions={transactions} />;
      case 'projects':
        return <ProjectList projects={projects} onAdd={() => setActiveView('add-project')} onSelect={() => {}} />;
      case 'add-project':
        return <ProjectForm onCancel={() => setActiveView('projects')} onSave={handleAddProject} />;
      case 'transactions':
        return <TransactionList transactions={transactions} projects={projects} onAdd={() => setActiveView('add-transaction')} />;
      case 'add-transaction':
        return <TransactionForm projects={projects} onCancel={() => setActiveView('transactions')} onSave={handleAddTransaction} />;
      case 'all-payments':
        return (
          <AllPaymentsList 
            contracts={contracts} 
            subcontractors={subcontractors} 
            onSelectContract={(id) => {
              setSelectedContractId(id);
              setActiveView('detail');
            }} 
          />
        );
      case 'contracts':
        return (
          <div className="space-y-6 pb-24">
            <div className="flex justify-between items-center px-1">
              <h1 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Sözleşmeler</h1>
              <button 
                onClick={() => setActiveView('add-contract')}
                className="bg-orange-600 text-white p-3 rounded-2xl shadow-lg shadow-orange-200 active:scale-95 transition-all flex items-center gap-2"
              >
                <FileEdit className="w-5 h-5" />
                <span className="text-[10px] font-black uppercase tracking-widest">Sözleşme Ekle</span>
              </button>
            </div>
            <div className="space-y-4">
              {contracts.length === 0 ? (
                <div className="text-center py-20 bg-white rounded-[2.5rem] border border-dashed border-slate-200">
                  <FileEdit className="w-12 h-12 text-slate-200 mx-auto mb-3" />
                  <p className="text-slate-400 text-sm font-medium">Henüz bir sözleşme tanımlanmamış.</p>
                </div>
              ) : (
                contracts.map(c => {
                  const project = projects.find(p => p.id === c.projectId);
                  const sub = subcontractors.find(s => s.id === c.subcontractorId);
                  return (
                    <button 
                      key={c.id} 
                      onClick={() => { setSelectedContractId(c.id); setActiveView('detail'); }}
                      className="w-full text-left bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm hover:border-orange-100 transition-all flex flex-col gap-3 group"
                    >
                      <div className="flex justify-between items-start">
                        <div>
                          <h3 className="font-black text-slate-800 text-sm uppercase group-hover:text-orange-600 transition-colors">{c.title}</h3>
                          <p className="text-[10px] font-bold text-slate-400 mt-0.5">{project?.name} / {sub?.name}</p>
                        </div>
                        <span className="bg-slate-50 text-slate-600 text-[10px] font-black px-3 py-1 rounded-full uppercase">
                          {c.totalValue.toLocaleString('tr-TR')} TL
                        </span>
                      </div>
                      <div className="w-full bg-slate-100 h-1.5 rounded-full overflow-hidden">
                        <div 
                          className="bg-orange-600 h-full rounded-full transition-all duration-1000" 
                          style={{ width: `${Math.min(100, (c.progressPayments[c.progressPayments.length-1]?.summary.cumulativeTotal || 0) / c.totalValue * 100)}%` }}
                        />
                      </div>
                    </button>
                  );
                })
              )}
            </div>
          </div>
        );
      case 'add-contract':
        return <ContractForm projects={projects} subcontractors={subcontractors} onCancel={() => setActiveView('contracts')} onSave={handleAddContract} />;
      case 'subcontractors':
        return <SubcontractorList subcontractors={subcontractors} onSelect={() => {}} onAdd={() => setActiveView('add-sub')} />;
      case 'add-sub':
        return (
          <div className="space-y-6 pb-24">
            <h2 className="text-xl font-bold">Taşeron Ekle</h2>
            <div className="bg-white p-6 rounded-3xl border shadow-sm space-y-4">
               <input 
                type="text" 
                placeholder="İsim" 
                className="w-full p-4 bg-slate-50 border rounded-2xl" 
                onBlur={(e) => {
                  if (e.target.value) handleAddSubcontractor({ id: Math.random().toString(36).substr(2, 9), name: e.target.value, trade: 'Genel' });
                }}
               />
               <button onClick={() => setActiveView('subcontractors')} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-bold">Geri Dön</button>
            </div>
          </div>
        );
      case 'detail':
        return selectedContract ? (
          <SubcontractorDetail 
            subcontractor={{ ...subcontractors.find(s => s.id === selectedContract.subcontractorId)!, contractDate: selectedContract.contractDate, totalContractValue: selectedContract.totalValue, workItems: selectedContract.workItems, progressPayments: selectedContract.progressPayments, contractDocuments: selectedContract.documents }}
            onBack={() => setActiveView('contracts')} 
            onNewPayment={() => setActiveView('payment-form')}
            onUpdate={(updatedSub) => {
               handleUpdateContract({
                 ...selectedContract,
                 workItems: updatedSub.workItems,
                 progressPayments: updatedSub.progressPayments,
                 documents: updatedSub.contractDocuments || []
               });
            }}
          />
        ) : null;
      case 'payment-form':
        return selectedContract ? (
          <ProgressPaymentForm 
            subcontractor={{ ...subcontractors.find(s => s.id === selectedContract.subcontractorId)!, contractDate: selectedContract.contractDate, totalContractValue: selectedContract.totalValue, workItems: selectedContract.workItems, progressPayments: selectedContract.progressPayments, contractDocuments: selectedContract.documents }} 
            onCancel={() => setActiveView('detail')} 
            onSave={(p) => handleAddPayment({ ...p, contractId: selectedContract.id })}
          />
        ) : null;
      case 'reports':
        return <Reports subcontractors={subcontractors} transactions={transactions} contracts={contracts} projects={projects} />;
      default:
        return <Dashboard subcontractors={subcontractors} projects={projects} contracts={contracts} transactions={transactions} />;
    }
  };

  const NavItem = ({ view, icon: Icon, label, activeViews = [] }: { view: any, icon: any, label: string, activeViews?: string[] }) => {
    const isActive = activeView === view || activeViews.includes(activeView);
    return (
      <button 
        onClick={() => setActiveView(view)}
        className={`flex flex-col items-center justify-center gap-1.5 transition-all duration-300 relative px-1 py-2 rounded-2xl flex-1 ${
          isActive 
            ? 'text-orange-600' 
            : 'text-slate-400 hover:text-slate-600'
        }`}
      >
        <div className={`p-2 rounded-xl transition-all duration-300 ${isActive ? 'bg-orange-50 shadow-inner' : 'bg-transparent'}`}>
          <Icon className={`w-5 h-5 transition-transform duration-300 ${isActive ? 'scale-110 stroke-[2.5px]' : 'stroke-2'}`} />
        </div>
        <span className={`text-[9px] uppercase tracking-widest leading-none font-black transition-all ${isActive ? 'opacity-100 translate-y-0' : 'opacity-80'}`}>
          {label}
        </span>
        {isActive && (
          <span className="absolute -bottom-0.5 w-4 h-1 bg-orange-600 rounded-full animate-in fade-in zoom-in duration-300" />
        )}
      </button>
    );
  };

  return (
    <div className="max-w-md mx-auto min-h-screen relative bg-slate-50 flex flex-col selection:bg-orange-100">
      <main className="flex-1 p-5 overflow-y-auto no-scrollbar">
        {/* Top Header Logo Area */}
        {activeView === 'dashboard' && (
          <div className="flex items-center justify-between mb-6 px-1">
             <div className="flex items-center gap-2">
                <div className="bg-orange-600 p-2 rounded-xl shadow-lg shadow-orange-200">
                   <HardHat className="w-6 h-6 text-white" />
                </div>
                <div>
                  <h2 className="text-sm font-black text-slate-900 leading-none uppercase tracking-tight">Ahmetoğlu</h2>
                  <p className="text-[10px] font-bold text-orange-600 uppercase tracking-widest">Şantiye Pro</p>
                </div>
             </div>
             <div className="w-8 h-8 rounded-full bg-slate-200 border-2 border-white shadow-sm flex items-center justify-center">
                <span className="text-[10px] font-black text-slate-500">AS</span>
             </div>
          </div>
        )}

        {renderView()}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/80 backdrop-blur-2xl border-t border-slate-100 px-2 py-2 flex justify-between items-center z-50 shadow-[0_-15px_40px_-10px_rgba(0,0,0,0.08)]">
        <NavItem view="dashboard" icon={LayoutGrid} label="Panel" />
        <NavItem view="projects" icon={Building2} label="Proje" activeViews={['add-project']} />
        <NavItem view="contracts" icon={FileEdit} label="Sözleşme" activeViews={['add-contract', 'detail', 'payment-form']} />
        <NavItem view="transactions" icon={Wallet} label="Kasa" activeViews={['add-transaction']} />
        <NavItem view="all-payments" icon={History} label="Geçmiş" />
        <NavItem view="reports" icon={PieChart} label="Analiz" />
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Legend, Cell 
} from 'recharts';
import { Subcontractor, Transaction, Contract, Project } from '../types';
import { 
  Calendar, 
  TrendingUp, 
  PieChart as PieChartIcon, 
  Sparkles, 
  CheckCircle2, 
  BarChart3, 
  Wallet, 
  Table as TableIcon,
  ArrowUpDown,
  ChevronUp,
  ChevronDown
} from 'lucide-react';
import { analyzeProjectHealth } from '../services/geminiService';

interface ReportsProps {
  subcontractors: Subcontractor[];
  transactions: Transaction[];
  contracts: Contract[];
  projects: Project[];
}

type Range = '30d' | '90d' | 'all';
type SortKey = 'projectName' | 'subName' | 'title' | 'totalValue' | 'paidAmount';
type SortOrder = 'asc' | 'desc';

const CustomTrendTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    const data = payload[0].payload;
    return (
      <div className="bg-white/95 backdrop-blur-md p-4 border border-slate-100 shadow-2xl rounded-2xl animate-in zoom-in-95 duration-200">
        <p className="text-xs font-bold text-slate-400 uppercase mb-2 tracking-wider">{label}</p>
        <p className="text-lg font-black text-orange-600 mb-2">
          {payload[0].value.toLocaleString('tr-TR')} TL
        </p>
        <div className="space-y-1 border-t border-slate-50 pt-2">
          <p className="text-[10px] font-bold text-slate-500 mb-1">DÖNEM ÖDEMELERİ:</p>
          {data.details.map((d: any, i: number) => (
            <div key={i} className="flex justify-between gap-4 text-[10px]">
              <span className="text-slate-600 font-medium">{d.name}</span>
              <span className="text-slate-900 font-bold">{d.amount.toLocaleString('tr-TR')} TL</span>
            </div>
          ))}
        </div>
      </div>
    );
  }
  return null;
};

const CustomProgressTooltip = ({ active, payload }: any) => {
  if (active && payload && payload.length) {
    const data = payload[0].payload;
    return (
      <div className="bg-white/95 backdrop-blur-md p-4 border border-slate-100 shadow-2xl rounded-2xl animate-in zoom-in-95 duration-200">
        <p className="text-sm font-bold text-slate-800 mb-1">{data.fullName}</p>
        <div className="space-y-2 mt-2">
          <div className="flex justify-between items-center gap-6">
            <span className="text-[10px] font-bold text-slate-400 uppercase">Tamamlanma</span>
            <span className="text-xs font-bold text-orange-600">%{data.percent}</span>
          </div>
        </div>
      </div>
    );
  }
  return null;
};

const Reports: React.FC<ReportsProps> = ({ subcontractors, transactions, contracts, projects }) => {
  const [range, setRange] = useState<Range>('all');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [sortKey, setSortKey] = useState<SortKey>('totalValue');
  const [sortOrder, setSortOrder] = useState<SortOrder>('desc');

  const filteredData = useMemo(() => {
    const now = new Date();
    const rangeLimit = range === '30d' ? 30 : range === '90d' ? 90 : Infinity;

    const allPayments = subcontractors.flatMap(s => 
      (s.progressPayments || []).map(p => ({
        ...p,
        subName: s.name,
        dateObj: new Date(p.date)
      }))
    ).filter(p => {
      if (range === 'all') return true;
      const diffDays = (now.getTime() - p.dateObj.getTime()) / (1000 * 3600 * 24);
      return diffDays <= rangeLimit;
    });

    return allPayments.sort((a, b) => a.dateObj.getTime() - b.dateObj.getTime());
  }, [subcontractors, range]);

  const stats = useMemo(() => {
    const totalPaid = filteredData.reduce((sum, p) => sum + p.summary.currentTotal, 0);
    const totalRetention = filteredData.reduce((sum, p) => sum + p.summary.retentionAmount, 0);
    const paymentCount = filteredData.length;
    return { totalPaid, totalRetention, paymentCount };
  }, [filteredData]);

  const trendData = useMemo(() => {
    const groups: Record<string, { total: number; details: {name: string, amount: number}[] }> = {};
    filteredData.forEach(p => {
      const month = p.dateObj.toLocaleDateString('tr-TR', { month: 'short', year: '2-digit' });
      if (!groups[month]) {
        groups[month] = { total: 0, details: [] };
      }
      groups[month].total += p.summary.currentTotal;

      const existing = groups[month].details.find(d => d.name === p.subName);
      if (existing) {
        existing.amount += p.summary.currentTotal;
      } else {
        groups[month].details.push({ name: p.subName, amount: p.summary.currentTotal });
      }
    });
    return Object.entries(groups).map(([name, data]) => ({ 
      name, 
      total: data.total, 
      details: data.details.sort((a,b) => b.amount - a.amount) 
    }));
  }, [filteredData]);

  const subProgressData = useMemo(() => {
    return subcontractors
      .filter(s => (s.totalContractValue || 0) > 0)
      .map(s => {
        const paid = (s.progressPayments || []).reduce((sum, p) => sum + p.summary.currentTotal, 0);
        const percent = Math.round((paid / (s.totalContractValue || 1)) * 100) || 0;
        return {
          name: s.name.length > 8 ? s.name.substring(0, 8) + '...' : s.name,
          fullName: s.name,
          percent: percent,
          paidAmount: paid,
          totalValue: s.totalContractValue || 0
        };
      })
      .sort((a, b) => b.percent - a.percent);
  }, [subcontractors]);

  const financialTrendData = useMemo(() => {
    const now = new Date();
    const rangeLimit = range === '30d' ? 30 : range === '90d' ? 90 : Infinity;

    const filteredTransactions = transactions.filter(t => {
      if (range === 'all') return true;
      const date = new Date(t.date);
      const diffDays = (now.getTime() - date.getTime()) / (1000 * 3600 * 24);
      return diffDays <= rangeLimit;
    });

    const groups: Record<string, { income: number; expense: number }> = {};

    filteredTransactions.forEach(t => {
      const month = new Date(t.date).toLocaleDateString('tr-TR', { month: 'short', year: '2-digit' });
      if (!groups[month]) groups[month] = { income: 0, expense: 0 };
      if (t.type === 'income') groups[month].income += t.amount;
      else groups[month].expense += t.amount;
    });

    return Object.entries(groups).map(([name, data]) => ({
      name,
      Gelir: data.income,
      Gider: data.expense
    }));
  }, [transactions, range]);

  const consolidatedContracts = useMemo(() => {
    const data = contracts.map(c => {
      const project = projects.find(p => p.id === c.projectId);
      const sub = subcontractors.find(s => s.id === c.subcontractorId);
      const paidAmount = c.progressPayments[c.progressPayments.length - 1]?.summary.cumulativeTotal || 0;

      return {
        id: c.id,
        projectName: project?.name || 'Bilinmeyen Proje',
        subName: sub?.name || 'Bilinmeyen Taşeron',
        title: c.title,
        totalValue: c.totalValue,
        paidAmount: paidAmount,
        progress: c.totalValue > 0 ? (paidAmount / c.totalValue) * 100 : 0
      };
    });

    return data.sort((a, b) => {
      const aVal = a[sortKey];
      const bVal = b[sortKey];

      if (typeof aVal === 'string' && typeof bVal === 'string') {
        return sortOrder === 'asc' 
          ? aVal.localeCompare(bVal) 
          : bVal.localeCompare(aVal);
      }

      return sortOrder === 'asc' 
        ? (aVal as number) - (bVal as number) 
        : (bVal as number) - (aVal as number);
    });
  }, [contracts, projects, subcontractors, sortKey, sortOrder]);

  const handleProjectAnalysis = async () => {
    setIsAnalyzing(true);
    const result = await analyzeProjectHealth(subcontractors);
    setAiInsight(result);
    setIsAnalyzing(false);
  };

  const handleSort = (key: SortKey) => {
    if (sortKey === key) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortKey(key);
      setSortOrder('desc');
    }
  };

  const SortIndicator = ({ k }: { k: SortKey }) => {
    if (sortKey !== k) return <ArrowUpDown className="w-3 h-3 text-slate-300" />;
    return sortOrder === 'asc' ? <ChevronUp className="w-3 h-3 text-orange-600" /> : <ChevronDown className="w-3 h-3 text-orange-600" />;
  };

  return (
    <div className="space-y-6 pb-24 animate-in fade-in duration-500">
      <div className="flex justify-between items-center px-1">
        <div>
          <h1 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Rapor Analiz</h1>
          <p className="text-[10px] text-orange-600 font-bold uppercase tracking-widest mt-1">İlerleme ve Mali Göstergeler</p>
        </div>
        <div className="flex bg-white border border-slate-200 p-1 rounded-2xl shadow-sm">
          {(['30d', '90d', 'all'] as Range[]).map((r) => (
            <button
              key={r}
              onClick={() => setRange(r)}
              className={`px-3 py-1.5 text-[9px] font-black rounded-xl transition-all ${range === r ? 'bg-orange-600 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}
            >
              {r === '30d' ? '30 GÜN' : r === '90d' ? '90 GÜN' : 'TÜMÜ'}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Dönemlik Hakediş</p>
          <p className="text-xl font-black text-orange-600">{stats.totalPaid.toLocaleString('tr-TR')} TL</p>
          <div className="flex items-center gap-1 mt-1 text-[9px] text-emerald-500 font-bold uppercase">
            <CheckCircle2 className="w-3 h-3" /> {stats.paymentCount} Kayıt
          </div>
        </div>
        <div className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Dönemlik Teminat</p>
          <p className="text-xl font-black text-slate-800">{stats.totalRetention.toLocaleString('tr-TR')} TL</p>
          <p className="text-[9px] text-orange-400 mt-1 font-medium uppercase tracking-tighter italic">Emanet Hesap</p>
        </div>
      </div>

      {/* AI Project Insight */}
      <div className="bg-gradient-to-br from-orange-600 to-orange-900 p-6 rounded-[2.5rem] shadow-xl text-white relative overflow-hidden group">
        <div className="absolute top-0 right-0 p-8 opacity-10 rotate-12 group-hover:rotate-45 transition-transform duration-700">
           <Sparkles className="w-24 h-24" />
        </div>
        <div className="relative z-10 space-y-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Sparkles className="w-5 h-5 text-orange-200" />
              <h3 className="text-xs font-black uppercase tracking-widest">Yapay Zeka Proje Analizi</h3>
            </div>
            <button 
              onClick={handleProjectAnalysis}
              disabled={isAnalyzing}
              className="bg-white/10 hover:bg-white/20 disabled:opacity-50 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest backdrop-blur-md border border-white/10 transition-all"
            >
              {isAnalyzing ? 'Analiz Ediliyor...' : 'Yeniden Analiz Et'}
            </button>
          </div>

          {aiInsight ? (
            <div className="text-sm leading-relaxed text-orange-50/90 whitespace-pre-wrap animate-in fade-in duration-500">
              {aiInsight}
            </div>
          ) : (
            <div className="text-sm text-orange-200/60 italic">
              Proje mali sağlığı ve risk analizi için butona tıklayın.
            </div>
          )}
        </div>
      </div>

      <div className="space-y-4">
        {/* Consolidated Contract Table */}
        <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden animate-in fade-in duration-500">
          <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
              <TableIcon className="w-4 h-4" /> Sözleşme İcmali
            </h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse min-w-[700px]">
              <thead>
                <tr className="bg-slate-50/50">
                  <th onClick={() => handleSort('projectName')} className="p-4 cursor-pointer hover:bg-slate-100 transition-colors">
                    <div className="flex items-center gap-2 text-[10px] font-black text-slate-500 uppercase">
                      Proje <SortIndicator k="projectName" />
                    </div>
                  </th>
                  <th onClick={() => handleSort('subName')} className="p-4 cursor-pointer hover:bg-slate-100 transition-colors">
                    <div className="flex items-center gap-2 text-[10px] font-black text-slate-500 uppercase">
                      Taşeron <SortIndicator k="subName" />
                    </div>
                  </th>
                  <th onClick={() => handleSort('title')} className="p-4 cursor-pointer hover:bg-slate-100 transition-colors">
                    <div className="flex items-center gap-2 text-[10px] font-black text-slate-500 uppercase">
                      Sözleşme <SortIndicator k="title" />
                    </div>
                  </th>
                  <th onClick={() => handleSort('totalValue')} className="p-4 text-right cursor-pointer hover:bg-slate-100 transition-colors">
                    <div className="flex items-center justify-end gap-2 text-[10px] font-black text-slate-500 uppercase">
                      Bedel <SortIndicator k="totalValue" />
                    </div>
                  </th>
