import React, { useState, useMemo } from 'react';
import { Subcontractor, ProgressPayment, UnitType } from '../types';
import { ArrowLeft, Save, AlertCircle, Calculator, Percent, Gavel, ShieldCheck, ChevronDown, ChevronUp, Info } from 'lucide-react';

interface ProgressPaymentFormProps {
  subcontractor: Subcontractor;
  onCancel: () => void;
  onSave: (payment: ProgressPayment) => void;
}

const ProgressPaymentForm: React.FC<ProgressPaymentFormProps> = ({ subcontractor, onCancel, onSave }) => {
  const [quantities, setQuantities] = useState<Record<string, number>>(
    (subcontractor.workItems || []).reduce((acc, item) => ({ ...acc, [item.id]: 0 }), {})
  );

  const [vatRate, setVatRate] = useState(20);
  const [retentionRate, setRetentionRate] = useState(5); // Teminat kesintisi %5
  const [showBreakdown, setShowBreakdown] = useState(false);
  const STAMP_DUTY_RATE = 0.00948; // Binde 9.48

  const itemProgress = useMemo(() => {
    return (subcontractor.workItems || []).map(item => {
      const prevTotal = (subcontractor.progressPayments || []).reduce((sum, p) => {
        const pItem = p.items.find(i => i.workItemId === item.id);
        return sum + (pItem?.thisPeriodQuantity || 0);
      }, 0);

      const thisPeriod = quantities[item.id] || 0;
      const cumulative = prevTotal + thisPeriod;
      const amount = thisPeriod * item.unitPrice;
      const isExceeding = cumulative > item.contractQuantity;

      return {
        ...item,
        prevTotal,
        thisPeriod,
        cumulative,
        amount,
        isExceeding
      };
    });
  }, [subcontractor, quantities]);

  const summary = useMemo(() => {
    const currentTotal = itemProgress.reduce((sum, i) => sum + i.amount, 0);
    const lastPayment = subcontractor.progressPayments?.[subcontractor.progressPayments.length - 1];
    const previousTotal = lastPayment?.summary.cumulativeTotal || 0;
    const cumulativeTotal = previousTotal + currentTotal;

    const retentionAmount = (currentTotal * retentionRate) / 100;
    const stampDutyAmount = currentTotal * STAMP_DUTY_RATE;
    const vatAmount = (currentTotal * vatRate) / 100;
    const netPayable = currentTotal - retentionAmount - stampDutyAmount + vatAmount;

    return {
      previousTotal,
      currentTotal,
      cumulativeTotal,
      retentionAmount,
      stampDutyAmount,
      vatAmount,
      netPayable
    };
  }, [itemProgress, retentionRate, vatRate, subcontractor.progressPayments]);

  const handleSave = () => {
    const newPayment: ProgressPayment = {
      id: Math.random().toString(36).substr(2, 9),
      number: (subcontractor.progressPayments?.length || 0) + 1,
      date: new Date().toISOString(),
      contractId: '', 
      items: itemProgress.map(i => ({
        workItemId: i.id,
        thisPeriodQuantity: i.thisPeriod,
        cumulativeQuantity: i.cumulative
      })),
      summary: {
        previousTotal: summary.previousTotal,
        currentTotal: summary.currentTotal,
        cumulativeTotal: summary.cumulativeTotal,
        retentionAmount: summary.retentionAmount,
        stampDutyAmount: summary.stampDutyAmount,
        vatAmount: summary.vatAmount,
        netPayable: summary.netPayable
      }
    };
    onSave(newPayment);
  };

  return (
    <div className="space-y-6 pb-24 animate-in slide-in-from-bottom duration-500 max-w-2xl mx-auto px-4">
      <div className="flex items-center justify-between sticky top-0 bg-slate-50/80 backdrop-blur-md z-20 py-4 -mx-4 px-4">
        <div className="flex items-center gap-3">
          <button onClick={onCancel} className="p-2 bg-white rounded-xl shadow-sm border border-slate-200">
            <ArrowLeft className="w-5 h-5 text-slate-600" />
          </button>
          <div>
            <h2 className="text-xl font-bold text-slate-800">Hakediş Raporu No: {(subcontractor.progressPayments?.length || 0) + 1}</h2>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{subcontractor.name}</p>
          </div>
        </div>
        <button 
          onClick={handleSave}
          className="bg-orange-600 text-white px-5 py-2.5 rounded-xl flex items-center gap-2 font-bold shadow-lg shadow-orange-200 active:scale-95 transition-all"
        >
          <Save className="w-4 h-4" /> Onayla
        </button>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-3">
          <div className="p-2 bg-orange-50 rounded-lg"><Percent className="w-4 h-4 text-orange-600" /></div>
          <div className="flex-1">
            <p className="text-[9px] text-slate-400 font-bold uppercase">KDV Oranı</p>
            <select value={vatRate} onChange={(e) => setVatRate(Number(e.target.value))} className="w-full text-xs font-black text-slate-700 bg-transparent focus:outline-none appearance-none cursor-pointer">
              <option value={0}>%0</option>
              <option value={10}>%10</option>
              <option value={20}>%20</option>
            </select>
          </div>
        </div>
        <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-3">
          <div className="p-2 bg-slate-50 rounded-lg"><ShieldCheck className="w-4 h-4 text-slate-600" /></div>
          <div className="flex-1">
            <p className="text-[9px] text-slate-400 font-bold uppercase">Teminat Kesintisi</p>
            <select value={retentionRate} onChange={(e) => setRetentionRate(Number(e.target.value))} className="w-full text-xs font-black text-slate-700 bg-transparent focus:outline-none appearance-none cursor-pointer">
              <option value={0}>%0</option>
              <option value={3}>%3</option>
              <option value={5}>%5</option>
            </select>
          </div>
        </div>
      </div>

      <div className="space-y-4">
        {itemProgress.map(item => (
          <div key={item.id} className={`bg-white rounded-3xl border transition-all ${item.isExceeding ? 'border-red-200 bg-red-50/30' : 'border-slate-100 shadow-sm'}`}>
            <div className="p-5 space-y-4">
              <div className="flex justify-between items-start">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-[9px] font-black bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded uppercase tracking-tighter">Poz: {item.pozNo || 'Özel'}</span>
                    <h4 className="text-sm font-bold text-slate-800">{item.description}</h4>
                  </div>
                  <p className="text-[10px] text-slate-400 font-medium">Birim Fiyat: {item.unitPrice.toLocaleString('tr-TR')} TL / {item.unit}</p>
                </div>
              </div>

              <div className="grid grid-cols-3 gap-3">
                <div className="space-y-1">
                  <label className="text-[9px] font-bold text-slate-400 uppercase ml-1">Önceki Toplam</label>
                  <div className="bg-slate-50 p-2 rounded-xl text-xs font-bold text-slate-600 text-center">{item.prevTotal}</div>
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-bold text-slate-400 uppercase ml-1">Bu Dönem</label>
                  <input 
                    type="number" 
                    value={item.thisPeriod || ''} 
                    onChange={(e) => setQuantities({ ...quantities, [item.id]: parseFloat(e.target.value) || 0 })}
                    className="w-full bg-orange-50/50 border border-orange-100 rounded-xl p-2 text-xs font-black text-orange-700 text-center focus:ring-2 focus:ring-orange-500 outline-none"
                    placeholder="0"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-bold text-slate-400 uppercase ml-1">Kümülatif</label>
                  <div className="bg-slate-50 p-2 rounded-xl text-xs font-black text-slate-800 text-center">{item.cumulative}</div>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Financial Summary Card */}
      <div className="bg-slate-900 text-white rounded-[2.5rem] p-8 space-y-6 shadow-2xl relative overflow-hidden animate-in fade-in slide-in-from-bottom duration-700">
        <div className="flex justify-between items-center text-xs text-slate-400 font-bold uppercase tracking-widest border-b border-slate-800 pb-4">
          <div className="flex items-center gap-2">
            <Gavel className="w-4 h-4 text-orange-500" />
            <span>Hakediş İcmal Özeti</span>
          </div>
          <button 
            onClick={() => setShowBreakdown(!showBreakdown)}
            className="flex items-center gap-1.5 bg-slate-800 hover:bg-slate-700 px-3 py-1.5 rounded-xl transition-colors text-[10px]"
          >
            {showBreakdown ? 'Hesaplamayı Gizle' : 'Hesaplama Detayı'}
            {showBreakdown ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
          </button>
        </div>

        <div className="space-y-4">
          <div className="flex justify-between text-sm items-center">
            <span className="text-slate-400 font-medium">Brüt İmalat Tutarı (A)</span>
            <span className="font-bold text-lg">{summary.currentTotal.toLocaleString('tr-TR')} TL</span>
          </div>

          {/* Expandable Breakdown Section */}
          {showBreakdown && (
            <div className="space-y-3 pt-4 border-t border-slate-800/50 bg-slate-800/30 p-4 rounded-2xl animate-in slide-in-from-top duration-300">
              <div className="flex justify-between text-[11px] items-start">
                <div className="space-y-0.5">
                  <span className="text-slate-400 block font-bold uppercase tracking-tighter">Teminat Kesintisi</span>
                  <span className="text-[9px] text-slate-500 italic block">Brüt Tutar x %{retentionRate}</span>
                </div>
                <span className="font-bold text-orange-400">-{summary.retentionAmount.toLocaleString('tr-TR', { minimumFractionDigits: 2 })} TL</span>
              </div>

              <div className="flex justify-between text-[11px] items-start">
                <div className="space-y-0.5">
                  <span className="text-slate-400 block font-bold uppercase tracking-tighter">Damga Vergisi</span>
                  <span className="text-[9px] text-slate-500 italic block">Brüt Tutar x 0.00948</span>
                </div>
                <span className="font-bold text-red-400">-{summary.stampDutyAmount.toLocaleString('tr-TR', { minimumFractionDigits: 2 })} TL</span>
              </div>

              <div className="flex justify-between text-[11px] items-start">
                <div className="space-y-0.5">
                  <span className="text-slate-400 block font-bold uppercase tracking-tighter">KDV İlavesi</span>
                  <span className="text-[9px] text-slate-500 italic block">Brüt Tutar x %{vatRate}</span>
                </div>
                <span className="font-bold text-blue-400">+{summary.vatAmount.toLocaleString('tr-TR', { minimumFractionDigits: 2 })} TL</span>
              </div>

              <div className="pt-2 flex items-center gap-2 border-t border-slate-700/50 mt-2">
                <Info className="w-3 h-3 text-slate-500" />
                <p className="text-[9px] text-slate-500 font-medium">Hesaplamalar yuvarlama farkı içerebilir.</p>
              </div>
            </div>
          )}

          {/* Regular Summary Items (Always visible if not expanded, or as totals) */}
          {!showBreakdown && (
            <div className="space-y-2 text-[11px]">
              <div className="flex justify-between">
                <span className="text-slate-500">Toplam Kesintiler</span>
                <span className="text-red-400 font-bold">
                  -{(summary.retentionAmount + summary.stampDutyAmount).toLocaleString('tr-TR', { minimumFractionDigits: 2 })} TL
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-500">KDV Tutarı</span>
                <span className="text-blue-400 font-bold">
                  +{summary.vatAmount.toLocaleString('tr-TR', { minimumFractionDigits: 2 })} TL
                </span>
              </div>
            </div>
          )}

          <div className="pt-6 mt-4 border-t border-slate-800">
            <div className="flex items-center justify-between mb-1">
              <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.3em]">Net Ödenecek Tutar</p>
              <span className="bg-orange-600/20 text-orange-500 text-[8px] px-2 py-0.5 rounded-full font-black uppercase tracking-widest">Tahakkuk</span>
            </div>
            <div className="flex items-baseline gap-2">
              <p className="text-4xl font-black text-white">{summary.netPayable.toLocaleString('tr-TR', { maximumFractionDigits: 0 })}</p>
              <p className="text-lg font-bold text-slate-500">TL</p>
            </div>
            <p className="text-[10px] text-slate-500 mt-2 italic font-medium">
              * Bu tutar stopaj ve diğer varsa cezai kesintiler hariç tahmini net ödemedir.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

