                className="bg-blue-600 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 shadow-lg shadow-blue-200 active:scale-95 transition-all"
              >
                <Plus className="w-3 h-3" /> Yeni Ekle
              </button>
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileUpload} 
                className="hidden" 
                accept="image/*"
              />
            </div>

            {(!subcontractor.contractDocuments || subcontractor.contractDocuments.length === 0) ? (
              <div 
                onClick={() => fileInputRef.current?.click()}
                className="bg-white border-2 border-dashed border-slate-200 p-12 rounded-[2.5rem] flex flex-col items-center text-center gap-4 hover:border-blue-400 hover:bg-blue-50/10 transition-all cursor-pointer group shadow-sm"
              >
                <div className="p-5 bg-slate-50 rounded-[2rem] text-slate-400 group-hover:bg-blue-50 group-hover:text-blue-600 transition-all group-hover:rotate-12">
                  <FileUp className="w-10 h-10" />
                </div>
                <div>
                  <p className="text-sm font-bold text-slate-800">Henüz Belge Yok</p>
                  <p className="text-[10px] text-slate-400 mt-1 max-w-[200px]">
                    Sözleşme veya tutanak görsellerini buraya yükleyerek dijital arşiv oluşturun.
                  </p>
                </div>
              </div>
            ) : (
              <div className="grid grid-cols-2 gap-4">
                {subcontractor.contractDocuments.map((doc) => (
                  <div 
                    key={doc.id} 
                    className="bg-white p-2 rounded-[2rem] border border-slate-100 shadow-sm group relative animate-in zoom-in-95 duration-200"
                  >
                    <div className="aspect-square rounded-2xl overflow-hidden bg-slate-50 relative">
                      <img 
                        src={doc.url} 
                        alt={doc.name} 
                        className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"
                      />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center backdrop-blur-[2px] gap-3">
                        <button 
                          onClick={() => setPreviewDoc(doc)}
                          className="p-2 bg-white text-slate-800 rounded-full hover:bg-blue-50 transition-colors shadow-lg"
                        >
                          <ZoomIn className="w-5 h-5" />
                        </button>
                        <button 
                          onClick={() => handleRemoveDoc(doc.id)}
                          className="p-2 bg-white text-red-600 rounded-full hover:bg-red-50 transition-colors shadow-lg"
                        >
                          <Trash2 className="w-5 h-5" />
                        </button>
                      </div>
                    </div>
                    <div className="p-2 pt-3">
                      <p className="text-[10px] font-bold text-slate-700 truncate">{doc.name}</p>
                      <p className="text-[8px] text-slate-400 mt-0.5">{new Date(doc.uploadDate).toLocaleDateString('tr-TR')}</p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default SubcontractorDetail;

import React, { useState, useEffect, useRef } from 'react';
import { Subcontractor, ProgressPayment, Project, Contract, Transaction } from './types';
import Dashboard from './components/Dashboard';
import SubcontractorList from './components/SubcontractorList';
import SubcontractorDetail from './components/SubcontractorDetail';
import ProgressPaymentForm from './components/ProgressPaymentForm';
import Reports from './components/Reports';
import AllPaymentsList from './components/AllPaymentsList';
import ProjectList from './components/ProjectList';
import ProjectForm from './components/ProjectForm';
import ContractForm from './components/ContractForm';
import TransactionList from './components/TransactionList';
import TransactionForm from './components/TransactionForm';
import { 
  LayoutGrid, 
  Building2, 
  FileEdit, 
  Wallet, 
  History, 
  PieChart,
  HardHat,
  CloudCheck,
  RefreshCw,
  Database
} from 'lucide-react';

const STORAGE_KEY = 'ahmetoglu_santiye_data_v1';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<'dashboard' | 'subcontractors' | 'all-payments' | 'reports' | 'detail' | 'payment-form' | 'add-sub' | 'projects' | 'add-project' | 'contracts' | 'add-contract' | 'transactions' | 'add-transaction'>('dashboard');

  const [projects, setProjects] = useState<Project[]>([]);
  const [subcontractors, setSubcontractors] = useState<Subcontractor[]>([]);
  const [contracts, setContracts] = useState<Contract[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  const [selectedContractId, setSelectedContractId] = useState<string | null>(null);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const isInitialMount = useRef(true);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const data = JSON.parse(saved);
      setProjects(data.projects || []);
      setSubcontractors(data.subcontractors || []);
      setContracts(data.contracts || []);
      setTransactions(data.transactions || []);
    }
  }, []);

  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false;
      return;
    }

    setSaveStatus('saving');
    const timer = setTimeout(() => {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ projects, subcontractors, contracts, transactions }));
      setSaveStatus('saved');

      const resetTimer = setTimeout(() => setSaveStatus('idle'), 2000);
      return () => clearTimeout(resetTimer);
    }, 500);

    return () => clearTimeout(timer);
  }, [projects, subcontractors, contracts, transactions]);

  const handleAddProject = (p: Project) => {
    setProjects([...projects, p]);
    setActiveView('projects');
  };

  const handleAddSubcontractor = (s: Subcontractor) => {
    setSubcontractors([...subcontractors, s]);
    setActiveView('subcontractors');
  };

  const handleAddContract = (c: Contract) => {
    setContracts([...contracts, c]);
    setActiveView('contracts');
  };

  const handleAddTransaction = (t: Transaction) => {
    setTransactions([...transactions, t]);
    setActiveView('transactions');
  };

  const handleUpdateContract = (updated: Contract) => {
    setContracts(prev => prev.map(c => c.id === updated.id ? updated : c));
  };

  const handleAddPayment = (payment: ProgressPayment) => {
    setContracts(prev => prev.map(c => {
      if (c.id === payment.contractId) {
        return {
          ...c,
          progressPayments: [...c.progressPayments, payment]
        };
      }
      return c;
    }));
    setActiveView('detail');
  };

  const handleApprovePayment = (contractId: string, paymentId: string) => {
    setContracts(prev => prev.map(c => {
      if (c.id === contractId) {
        return {
          ...c,
          progressPayments: c.progressPayments.map(p => 
            p.id === paymentId ? { ...p, status: 'Approved' } : p
          )
        };
      }
      return c;
    }));
  };

  const selectedContract = contracts.find(c => c.id === selectedContractId);

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return <Dashboard subcontractors={subcontractors} projects={projects} contracts={contracts} transactions={transactions} />;
      case 'projects':
        return <ProjectList projects={projects} onAdd={() => setActiveView('add-project')} onSelect={() => {}} />;
      case 'add-project':
        return <ProjectForm onCancel={() => setActiveView('projects')} onSave={handleAddProject} />;
      case 'transactions':
        return <TransactionList transactions={transactions} projects={projects} onAdd={() => setActiveView('add-transaction')} />;
      case 'add-transaction':
        return <TransactionForm projects={projects} onCancel={() => setActiveView('transactions')} onSave={handleAddTransaction} />;
      case 'all-payments':
        return (
          <AllPaymentsList 
            contracts={contracts} 
            subcontractors={subcontractors} 
            onSelectContract={(id) => {
              setSelectedContractId(id);
              setActiveView('detail');
            }} 
          />
        );
      case 'contracts':
        return (
          <div className="space-y-6 pb-24">
            <div className="flex justify-between items-center px-1">
              <h1 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Sözleşmeler</h1>
              <button 
                onClick={() => setActiveView('add-contract')}
                className="bg-orange-600 text-white p-3 rounded-2xl shadow-lg shadow-orange-200 active:scale-95 transition-all flex items-center gap-2"
              >
                <FileEdit className="w-5 h-5" />
                <span className="text-[10px] font-black uppercase tracking-widest">Sözleşme Ekle</span>
              </button>
            </div>
            <div className="space-y-4">
              {contracts.length === 0 ? (
                <div className="text-center py-20 bg-white rounded-[2.5rem] border border-dashed border-slate-200">
                  <FileEdit className="w-12 h-12 text-slate-200 mx-auto mb-3" />
                  <p className="text-slate-400 text-sm font-medium">Henüz bir sözleşme tanımlanmamış.</p>
                </div>
              ) : (
                contracts.map(c => {
                  const project = projects.find(p => p.id === c.projectId);
                  const sub = subcontractors.find(s => s.id === c.subcontractorId);
                  const lastApproved = [...c.progressPayments].reverse().find(p => p.status === 'Approved');

                  return (
                    <button 
                      key={c.id} 
                      onClick={() => { setSelectedContractId(c.id); setActiveView('detail'); }}
                      className="w-full text-left bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm hover:border-orange-100 transition-all flex flex-col gap-3 group"
                    >
                      <div className="flex justify-between items-start">
                        <div>
                          <h3 className="font-black text-slate-800 text-sm uppercase group-hover:text-orange-600 transition-colors">{c.title}</h3>
                          <p className="text-[10px] font-bold text-slate-400 mt-0.5">{project?.name} / {sub?.name}</p>
                        </div>
                        <span className="bg-slate-50 text-slate-600 text-[10px] font-black px-3 py-1 rounded-full uppercase">
                          {c.totalValue.toLocaleString('tr-TR')} TL
                        </span>
                      </div>
                      <div className="w-full bg-slate-100 h-1.5 rounded-full overflow-hidden">
                        <div 
                          className="bg-orange-600 h-full rounded-full transition-all duration-1000" 
                          style={{ width: `${Math.min(100, (lastApproved?.summary.cumulativeTotal || 0) / c.totalValue * 100)}%` }}
                        />
                      </div>
                    </button>
                  );
                })
              )}
            </div>
          </div>
        );
      case 'add-contract':
        return <ContractForm projects={projects} subcontractors={subcontractors} onCancel={() => setActiveView('contracts')} onSave={handleAddContract} />;
      case 'subcontractors':
        return <SubcontractorList subcontractors={subcontractors} onSelect={() => {}} onAdd={() => setActiveView('add-sub')} />;
      case 'add-sub':
        return (
          <div className="space-y-6 pb-24">
            <h2 className="text-xl font-bold">Taşeron Ekle</h2>
            <div className="bg-white p-6 rounded-3xl border shadow-sm space-y-4">
               <input 
                type="text" 
                placeholder="İsim" 
                className="w-full p-4 bg-slate-50 border rounded-2xl" 
                onBlur={(e) => {
                  if (e.target.value) handleAddSubcontractor({ id: Math.random().toString(36).substr(2, 9), name: e.target.value, trade: 'Genel' });
                }}
               />
               <button onClick={() => setActiveView('subcontractors')} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-bold">Geri Dön</button>
            </div>
          </div>
        );
      case 'detail':
        return selectedContract ? (
          <SubcontractorDetail 
            subcontractor={{ ...subcontractors.find(s => s.id === selectedContract.subcontractorId)!, contractDate: selectedContract.contractDate, totalContractValue: selectedContract.totalValue, workItems: selectedContract.workItems, progressPayments: selectedContract.progressPayments, contractDocuments: selectedContract.documents }}
            onBack={() => setActiveView('contracts')} 
            onNewPayment={() => setActiveView('payment-form')}
            onApprovePayment={(pid) => handleApprovePayment(selectedContract.id, pid)}
            onUpdate={(updatedSub) => {
               handleUpdateContract({
                 ...selectedContract,
                 workItems: updatedSub.workItems,
                 progressPayments: updatedSub.progressPayments,
                 documents: updatedSub.contractDocuments || []
               });
            }}
          />
        ) : null;
      case 'payment-form':
        return selectedContract ? (
          <ProgressPaymentForm 
            subcontractor={{ ...subcontractors.find(s => s.id === selectedContract.subcontractorId)!, contractDate: selectedContract.contractDate, totalContractValue: selectedContract.totalValue, workItems: selectedContract.workItems, progressPayments: selectedContract.progressPayments, contractDocuments: selectedContract.documents }} 
            onCancel={() => setActiveView('detail')} 
            onSave={(p) => handleAddPayment({ ...p, contractId: selectedContract.id })}
          />
        ) : null;
      case 'reports':
        return (
          <Reports 
            subcontractors={subcontractors} 
            transactions={transactions} 
            contracts={contracts} 
            projects={projects} 
            onNewPayment={(contractId) => {
              setSelectedContractId(contractId);
              setActiveView('payment-form');
            }}
          />
        );
      default:
        return <Dashboard subcontractors={subcontractors} projects={projects} contracts={contracts} transactions={transactions} />;
    }
  };

  const NavItem = ({ view, icon: Icon, label, activeViews = [] }: { view: any, icon: any, label: string, activeViews?: string[] }) => {
    const isActive = activeView === view || activeViews.includes(activeView);
    return (
      <button 
        onClick={() => setActiveView(view)}
        className={`flex flex-col items-center justify-center gap-1.5 transition-all duration-300 relative px-1 py-2 rounded-2xl flex-1 ${
          isActive 
            ? 'text-orange-600' 
            : 'text-slate-400 hover:text-slate-600'
        }`}
      >
        <div className={`p-2 rounded-xl transition-all duration-300 ${isActive ? 'bg-orange-50 shadow-inner' : 'bg-transparent'}`}>
          <Icon className={`w-5 h-5 transition-transform duration-300 ${isActive ? 'scale-110 stroke-[2.5px]' : 'stroke-2'}`} />
        </div>
        <span className={`text-[9px] uppercase tracking-widest leading-none font-black transition-all ${isActive ? 'opacity-100 translate-y-0' : 'opacity-80'}`}>
          {label}
        </span>
        {isActive && (
          <span className="absolute -bottom-0.5 w-4 h-1 bg-orange-600 rounded-full animate-in fade-in zoom-in duration-300" />
        )}
      </button>
    );
  };

  return (
    <div className="max-w-md mx-auto min-h-screen relative bg-slate-50 flex flex-col selection:bg-orange-100">
      <main className="flex-1 p-5 overflow-y-auto no-scrollbar">
        {/* Top Header Logo Area & Save Status */}
        <div className="flex items-center justify-between mb-6 px-1">
           <div className="flex items-center gap-2">
              <div className="bg-orange-600 p-2 rounded-xl shadow-lg shadow-orange-200">
                 <HardHat className="w-6 h-6 text-white" />
              </div>
              <div>
                <h2 className="text-sm font-black text-slate-900 leading-none uppercase tracking-tight">Ahmetoğlu</h2>
                <div className="flex items-center gap-1.5 mt-0.5">
                  <p className="text-[10px] font-bold text-orange-600 uppercase tracking-widest">Şantiye Pro</p>
                  {saveStatus !== 'idle' && (
                    <div className="flex items-center gap-1 animate-in fade-in slide-in-from-left duration-300">
                      <span className="w-1 h-1 bg-slate-300 rounded-full" />
                      <div className="flex items-center gap-1 text-[8px] font-black uppercase tracking-tighter text-slate-400">
                        {saveStatus === 'saving' ? (
                          <>
                            <RefreshCw className="w-2 h-2 animate-spin" /> Yedekleniyor
                          </>
                        ) : (
                          <>
                            <CloudCheck className="w-2.5 h-2.5 text-emerald-500" /> Kaydedildi
                          </>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              </div>
           </div>
           <div className="w-8 h-8 rounded-full bg-white border border-slate-100 shadow-sm flex items-center justify-center group relative cursor-help">
              <Database className="w-4 h-4 text-slate-400 group-hover:text-orange-500 transition-colors" />
              <div className="absolute top-full right-0 mt-2 w-48 bg-slate-900 text-white text-[9px] p-3 rounded-2xl opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all z-[60] shadow-2xl leading-relaxed">
                <p className="font-black mb-1 uppercase text-orange-500 tracking-widest">Veri Güvenliği</p>
                Tüm verileriniz uçtan uca şifreli olarak sadece bu cihazda (localStorage) saklanır. İnternet olmasa bile çalışmaya devam edebilirsiniz.
              </div>
           </div>
        </div>

        {renderView()}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/80 backdrop-blur-2xl border-t border-slate-100 px-2 py-2 flex justify-between items-center z-50 shadow-[0_-15px_40px_-10px_rgba(0,0,0,0.08)]">
        <NavItem view="dashboard" icon={LayoutGrid} label="Panel" />
        <NavItem view="projects" icon={Building2} label="Proje" activeViews={['add-project']} />
        <NavItem view="contracts" icon={FileEdit} label="Sözleşme" activeViews={['add-contract', 'detail', 'payment-form']} />
        <NavItem view="transactions" icon={Wallet} label="Kasa" activeViews={['add-transaction']} />
        <NavItem view="all-payments" icon={History} label="Geçmiş" />
        <NavItem view="reports" icon={PieChart} label="Analiz" />
      </nav>
    </div>
  );
};

export default App;

import React from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer 
} from 'recharts';
import { Subcontractor, Project, Contract, Transaction } from '../types';
import { TrendingUp, Activity, Wallet, Landmark, DollarSign, HardHat, ShieldCheck, Database, Zap } from 'lucide-react';

interface DashboardProps {
  subcontractors: Subcontractor[];
  projects: Project[];
  contracts: Contract[];
  transactions: Transaction[];
}

const Dashboard: React.FC<DashboardProps> = ({ subcontractors, projects, contracts, transactions }) => {
  const totalIncome = transactions.filter(t => t.type === 'income').reduce((sum, t) => sum + t.amount, 0);

  const subCosts = contracts.reduce((sum, c) => {
    const approvedPayments = c.progressPayments.filter(p => p.status === 'Approved');
    const lastPayment = approvedPayments[approvedPayments.length - 1];
    return sum + (lastPayment?.summary.cumulativeTotal || 0);
  }, 0);

  const miscExpenses = transactions.filter(t => t.type === 'expense').reduce((sum, t) => sum + t.amount, 0);
  const totalCost = subCosts + miscExpenses;
  const balance = totalIncome - totalCost;

  const chartData = projects.map(p => {
    const projIncome = transactions.filter(t => t.projectId === p.id && t.type === 'income').reduce((sum, t) => sum + t.amount, 0);
    const projContracts = contracts.filter(c => c.projectId === p.id);
    const projSubCosts = projContracts.reduce((sum, c) => {
      const approved = c.progressPayments.filter(pay => pay.status === 'Approved');
      const last = approved[approved.length-1];
      return sum + (last?.summary.cumulativeTotal || 0);
    }, 0);
    const projMiscCosts = transactions.filter(t => t.projectId === p.id && t.type === 'expense').reduce((sum, t) => sum + t.amount, 0);

    return {
      name: p.name.length > 8 ? p.name.substring(0, 8) + '...' : p.name,
      Gelir: projIncome,
      Maliyet: projSubCosts + projMiscCosts,
    };
  });

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-700">
      <div className="flex items-center gap-3 px-2">
        <div className="bg-orange-600 p-2 rounded-xl text-white shadow-lg shadow-orange-200">
          <HardHat className="w-5 h-5" />
        </div>
        <h1 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Finansal Durum</h1>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-100 relative overflow-hidden group">
          <Activity className="absolute -right-2 -bottom-2 w-12 h-12 text-slate-50 group-hover:scale-110 transition-transform" />
          <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest mb-1">Onaylı Tahsilat</p>
          <p className="text-2xl font-black text-slate-800">{totalIncome.toLocaleString('tr-TR')} TL</p>
        </div>
        <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-100 relative overflow-hidden group">
          <Wallet className="absolute -right-2 -bottom-2 w-12 h-12 text-slate-50 group-hover:scale-110 transition-transform" />
          <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest mb-1">Onaylı Maliyet</p>
          <p className="text-2xl font-black text-rose-600">{totalCost.toLocaleString('tr-TR')} TL</p>
        </div>

        <div className={`p-6 rounded-[2.5rem] shadow-xl flex flex-col col-span-2 text-white relative overflow-hidden transition-colors ${balance >= 0 ? 'bg-slate-900' : 'bg-rose-900'}`}>
          <div className="absolute top-0 right-0 p-8 opacity-10"><TrendingUp className="w-24 h-24" /></div>
          <div className="relative z-10 space-y-2">
            <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Kasa Net Bakiyesi (Kar/Zarar)</p>
            <div className="flex items-end gap-2">
              <p className="text-4xl font-black text-white">{balance.toLocaleString('tr-TR')}</p>
              <p className="text-lg font-bold text-slate-500 mb-1">TL</p>
            </div>
          </div>
        </div>
      </div>

      {/* Persistence Quality of Life Card */}
      <div className="bg-blue-600 rounded-[2.5rem] p-6 text-white relative overflow-hidden shadow-xl shadow-blue-100 group border-t-4 border-blue-400">
        <div className="absolute top-0 right-0 p-6 opacity-10 group-hover:scale-110 transition-transform">
          <Database className="w-32 h-32" />
        </div>
        <div className="relative z-10 flex items-start gap-4">
          <div className="p-3 bg-white/10 rounded-2xl backdrop-blur-md">
            <Zap className="w-6 h-6 text-blue-200" />
          </div>
          <div>
            <h3 className="text-sm font-black uppercase tracking-tight mb-1 flex items-center gap-2">
              Otomatik Yedekleme Aktif <ShieldCheck className="w-4 h-4" />
            </h3>
            <p className="text-[10px] text-blue-100 leading-relaxed font-medium">
              Uygulamada yaptığınız her değişiklik anlık olarak cihazınıza kaydedilir. Verileriniz buluta gönderilmez, gizliliğiniz %100 korunur.
            </p>
            <div className="mt-4 flex items-center gap-2">
              <span className="w-2 h-2 bg-emerald-400 rounded-full animate-pulse" />
              <span className="text-[9px] font-black uppercase tracking-widest text-blue-200">Yerel Veritabanı Optimize Edildi</span>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100">
        <div className="flex items-center justify-between mb-6">
          <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Nakıt Akış Analizi (Onaylı)</h3>
          <DollarSign className="w-4 h-4 text-slate-200" />
        </div>
        <div className="h-64 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" fontSize={10} axisLine={false} tickLine={false} />
              <Tooltip cursor={{fill: '#f8fafc'}} />
              <Bar dataKey="Gelir" fill="#ea580c" radius={[6, 6, 0, 0]} />
              <Bar dataKey="Maliyet" fill="#0f172a" radius={[6, 6, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Legend, Cell 
} from 'recharts';
import { Subcontractor, Transaction, Contract, Project } from '../types';
import { 
  Calendar, 
  TrendingUp, 
  PieChart as PieChartIcon, 
  Sparkles, 
  CheckCircle2, 
  BarChart3, 
  Wallet, 
  Table as TableIcon,
  ArrowUpDown,
  ChevronUp,
  ChevronDown,
  PlusCircle,
  Download,
  FileSpreadsheet
} from 'lucide-react';
import { analyzeProjectHealth } from '../services/geminiService';

interface ReportsProps {
  subcontractors: Subcontractor[];
  transactions: Transaction[];
  contracts: Contract[];
  projects: Project[];
  onNewPayment: (contractId: string) => void;
}

type Range = '30d' | '90d' | 'all';
type SortKey = 'projectName' | 'subName' | 'title' | 'totalValue' | 'paidAmount';
type SortOrder = 'asc' | 'desc';

const Reports: React.FC<ReportsProps> = ({ subcontractors, transactions, contracts, projects, onNewPayment }) => {
  const [range, setRange] = useState<Range>('all');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [sortKey, setSortKey] = useState<SortKey>('totalValue');
  const [sortOrder, setSortOrder] = useState<SortOrder>('desc');

  const filteredData = useMemo(() => {
    const now = new Date();
    const rangeLimit = range === '30d' ? 30 : range === '90d' ? 90 : Infinity;

    const allPayments = subcontractors.flatMap(s => 
      (s.progressPayments || [])
        .filter(p => p.status === 'Approved')
        .map(p => ({
          ...p,
          subName: s.name,
          dateObj: new Date(p.date)
        }))
    ).filter(p => {
      if (range === 'all') return true;
      const diffDays = (now.getTime() - p.dateObj.getTime()) / (1000 * 3600 * 24);
      return diffDays <= rangeLimit;
    });

    return allPayments.sort((a, b) => a.dateObj.getTime() - b.dateObj.getTime());
  }, [subcontractors, range]);

  const stats = useMemo(() => {
    const totalPaid = filteredData.reduce((sum, p) => sum + p.summary.currentTotal, 0);
    const totalRetention = filteredData.reduce((sum, p) => sum + p.summary.retentionAmount, 0);
    const paymentCount = filteredData.length;
    return { totalPaid, totalRetention, paymentCount };
  }, [filteredData]);

  const financialTrendData = useMemo(() => {
    const now = new Date();
    const rangeLimit = range === '30d' ? 30 : range === '90d' ? 90 : Infinity;

    const filteredTransactions = transactions.filter(t => {
      if (range === 'all') return true;
      const date = new Date(t.date);
      const diffDays = (now.getTime() - date.getTime()) / (1000 * 3600 * 24);
      return diffDays <= rangeLimit;
    });

    const groups: Record<string, { income: number; expense: number }> = {};

    filteredTransactions.forEach(t => {
      const month = new Date(t.date).toLocaleDateString('tr-TR', { month: 'short', year: '2-digit' });
      if (!groups[month]) groups[month] = { income: 0, expense: 0 };
      if (t.type === 'income') groups[month].income += t.amount;
      else groups[month].expense += t.amount;
    });

    return Object.entries(groups).map(([name, data]) => ({
      name,
      Gelir: data.income,
      Gider: data.expense
    }));
  }, [transactions, range]);

  const consolidatedContracts = useMemo(() => {
    const data = contracts.map(c => {
      const project = projects.find(p => p.id === c.projectId);
      const sub = subcontractors.find(s => s.id === c.subcontractorId);
      const approved = c.progressPayments.filter(p => p.status === 'Approved');
      const paidAmount = approved[approved.length - 1]?.summary.cumulativeTotal || 0;

      return {
        id: c.id,
        projectName: project?.name || 'Bilinmeyen Proje',
        subName: sub?.name || 'Bilinmeyen Taşeron',
        title: c.title,
        totalValue: c.totalValue,
        paidAmount: paidAmount,
        progress: c.totalValue > 0 ? (paidAmount / c.totalValue) * 100 : 0
      };
    });

    return data.sort((a, b) => {
      const aVal = a[sortKey];
      const bVal = b[sortKey];

      if (typeof aVal === 'string' && typeof bVal === 'string') {
        return sortOrder === 'asc' 
          ? aVal.localeCompare(bVal) 
          : bVal.localeCompare(aVal);
      }

      return sortOrder === 'asc' 
        ? (aVal as number) - (bVal as number) 
        : (bVal as number) - (aVal as number);
    });
  }, [contracts, projects, subcontractors, sortKey, sortOrder]);

  const handleExportToCSV = () => {
    const headers = ["Proje", "Taşeron", "Sözleşme", "Sözleşme Bedeli", "Onaylı Hakediş", "İlerleme (%)"];
    const rows = consolidatedContracts.map(c => [
      c.projectName,
      c.subName,
      c.title,
      c.totalValue.toString(),
      c.paidAmount.toString(),
      c.progress.toFixed(2)
    ]);

    const csvContent = [headers, ...rows].map(e => e.join(";")).join("\n");
    const blob = new Blob(["\ufeff" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    const url = URL.createObjectURL(blob);
    link.setAttribute("href", url);
    link.setAttribute("download", `Sozlesme_Icmali_${new Date().toLocaleDateString('tr-TR')}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleProjectAnalysis = async () => {
    setIsAnalyzing(true);
    const result = await analyzeProjectHealth(subcontractors);
    setAiInsight(result);
    setIsAnalyzing(false);
  };

  const handleSort = (key: SortKey) => {
    if (sortKey === key) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortKey(key);
      setSortOrder('desc');
    }
  };

  const SortIndicator = ({ k }: { k: SortKey }) => {
    if (sortKey !== k) return <ArrowUpDown className="w-3 h-3 text-slate-300" />;
    return sortOrder === 'asc' ? <ChevronUp className="w-3 h-3 text-orange-600" /> : <ChevronDown className="w-3 h-3 text-orange-600" />;
  };

  return (
    <div className="space-y-6 pb-24 animate-in fade-in duration-500">
      <div className="flex justify-between items-center px-1">
        <div>
          <h1 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Rapor Analiz</h1>
          <p className="text-[10px] text-orange-600 font-bold uppercase tracking-widest mt-1">Onaylı İlerleme ve Mali Göstergeler</p>
        </div>
        <div className="flex bg-white border border-slate-200 p-1 rounded-2xl shadow-sm no-print">
          {(['30d', '90d', 'all'] as Range[]).map((r) => (
            <button
              key={r}
              onClick={() => setRange(r)}
              className={`px-3 py-1.5 text-[9px] font-black rounded-xl transition-all ${range === r ? 'bg-orange-600 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}
            >
              {r === '30d' ? '30 GÜN' : r === '90d' ? '90 GÜN' : 'TÜMÜ'}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Onaylı Hakediş</p>
          <p className="text-xl font-black text-orange-600">{stats.totalPaid.toLocaleString('tr-TR')} TL</p>
          <div className="flex items-center gap-1 mt-1 text-[9px] text-emerald-500 font-bold uppercase">
            <CheckCircle2 className="w-3 h-3" /> {stats.paymentCount} Onaylı
          </div>
        </div>
        <div className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Emanet Teminat</p>
          <p className="text-xl font-black text-slate-800">{stats.totalRetention.toLocaleString('tr-TR')} TL</p>
          <p className="text-[9px] text-orange-400 mt-1 font-medium uppercase tracking-tighter italic">Onaylılardan Kesilen</p>
        </div>
      </div>

      <div className="bg-gradient-to-br from-orange-600 to-orange-900 p-6 rounded-[2.5rem] shadow-xl text-white relative overflow-hidden group no-print">
        <div className="absolute top-0 right-0 p-8 opacity-10 rotate-12 group-hover:rotate-45 transition-transform duration-700">
           <Sparkles className="w-24 h-24" />
        </div>
        <div className="relative z-10 space-y-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Sparkles className="w-5 h-5 text-orange-200" />
              <h3 className="text-xs font-black uppercase tracking-widest">Yapay Zeka Analizi</h3>
            </div>
            <button 
              onClick={handleProjectAnalysis}
              disabled={isAnalyzing}
              className="bg-white/10 hover:bg-white/20 disabled:opacity-50 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest backdrop-blur-md border border-white/10 transition-all"
            >
              {isAnalyzing ? 'Analiz Ediliyor...' : 'Analiz Et'}
            </button>
          </div>

          {aiInsight ? (
            <div className="text-sm leading-relaxed text-orange-50/90 whitespace-pre-wrap animate-in fade-in duration-500">
              {aiInsight}
            </div>
          ) : (
            <div className="text-sm text-orange-200/60 italic">
              Onaylı veriler üzerinden mali risk analizi için butona tıklayın.
            </div>
          )}
        </div>
      </div>

      <div className="space-y-4">
        <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden animate-in fade-in duration-500">
          <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
              <TableIcon className="w-4 h-4" /> Onaylı Sözleşme İcmali
            </h3>
            <button 
              onClick={handleExportToCSV}
              className="flex items-center gap-2 bg-emerald-50 text-emerald-600 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-600 hover:text-white transition-all shadow-sm active:scale-95 no-print"
            >
              <FileSpreadsheet className="w-3.5 h-3.5" /> Excel'e Aktar
            </button>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse min-w-[800px]">
              <thead>
                <tr className="bg-slate-50/50">
                  <th onClick={() => handleSort('projectName')} className="p-4 cursor-pointer hover:bg-slate-100 transition-colors">
                    <div className="flex items-center gap-2 text-[10px] font-black text-slate-500 uppercase">
                      Proje <SortIndicator k="projectName" />
                    </div>
                  </th>
                  <th onClick={() => handleSort('subName')} className="p-4 cursor-pointer hover:bg-slate-100 transition-colors">
                    <div className="flex items-center gap-2 text-[10px] font-black text-slate-500 uppercase">
                      Taşeron <SortIndicator k="subName" />
                    </div>
                  </th>
                  <th onClick={() => handleSort('title')} className="p-4 cursor-pointer hover:bg-slate-100 transition-colors">
                    <div className="flex items-center gap-2 text-[10px] font-black text-slate-500 uppercase">
                      Sözleşme <SortIndicator k="title" />
                    </div>
                  </th>
                  <th onClick={() => handleSort('totalValue')} className="p-4 text-right cursor-pointer hover:bg-slate-100 transition-colors">
                    <div className="flex items-center justify-end gap-2 text-[10px] font-black text-slate-500 uppercase">
                      Bedel <SortIndicator k="totalValue" />
                    </div>
                  </th>
                  <th onClick={() => handleSort('paidAmount')} className="p-4 text-right cursor-pointer hover:bg-slate-100 transition-colors">
                    <div className="flex items-center justify-end gap-2 text-[10px] font-black text-slate-500 uppercase">
                      Onaylı <SortIndicator k="paidAmount" />
                    </div>
                  </th>
                  <th className="p-4 text-center text-[10px] font-black text-slate-500 uppercase no-print">
                    İşlem
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {consolidatedContracts.map((c, idx) => (
                  <tr key={c.id} className={`${idx % 2 === 0 ? 'bg-white' : 'bg-slate-50/20'} hover:bg-orange-50/30 transition-colors`}>
                    <td className="p-4 text-[11px] font-bold text-slate-600">{c.projectName}</td>
                    <td className="p-4 text-[11px] font-black text-slate-800">{c.subName}</td>
                    <td className="p-4 text-[10px] font-medium text-slate-500 uppercase tracking-tight">{c.title}</td>
                    <td className="p-4 text-right text-[11px] font-mono font-bold text-slate-700">{c.totalValue.toLocaleString('tr-TR')} TL</td>
                    <td className="p-4 text-right text-[11px] font-mono font-black text-orange-600">
                      <div className="flex flex-col items-end gap-1">
                        <span>{c.paidAmount.toLocaleString('tr-TR')} TL</span>
                        <div className="w-16 bg-slate-100 h-1 rounded-full overflow-hidden">
                          <div className="bg-orange-600 h-full" style={{ width: `${Math.min(100, c.progress)}%` }} />
                        </div>
                      </div>
                    </td>
                    <td className="p-4 text-center no-print">
                      <button 
                        onClick={() => onNewPayment(c.id)}
                        className="bg-orange-600 text-white p-2 rounded-xl shadow-md shadow-orange-100 hover:bg-orange-700 active:scale-90 transition-all group"
                        title="Yeni Hakediş Hazırla"
                      >
                        <PlusCircle className="w-5 h-5 group-hover:rotate-90 transition-transform" />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <div className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Onaylı Nakıt Akışı</h3>
            <Wallet className="w-4 h-4 text-slate-200" />
          </div>
          <div className="h-64 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={financialTrendData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" fontSize={10} axisLine={false} tickLine={false} />
                <YAxis fontSize={10} axisLine={false} tickLine={false} tickFormatter={(value) => `${value/1000}k`} />
                <Tooltip cursor={{fill: '#f8fafc'}} />
                <Legend iconType="circle" wrapperStyle={{fontSize: '10px', fontWeight: 'bold', textTransform: 'uppercase', paddingTop: '10px'}} />
                <Bar dataKey="Gelir" fill="#ea580c" radius={[4, 4, 0, 0]} />
                <Bar dataKey="Gider" fill="#0f172a" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Reports;

import React, { useState, useRef } from 'react';
import { Subcontractor, ProgressPayment, ContractDocument, WorkItem } from '../types';
import { ArrowLeft, Plus, Sparkles, FileText, Info, TrendingUp, Calendar, Edit2, Check, X, FileUp, Eye, Trash2, Image as ImageIcon, ZoomIn, ListFilter, Calculator, AlertCircle, CheckCircle2, Clock, Landmark, ShieldCheck, Gavel, Download, FileSpreadsheet, Printer } from 'lucide-react';
import { analyzeProgress } from '../services/geminiService';

interface SubcontractorDetailProps {
  subcontractor: Subcontractor;
  onBack: () => void;
  onNewPayment: () => void;
  onApprovePayment: (id: string) => void;
  onUpdate: (updatedSub: Subcontractor) => void;
}

const SubcontractorDetail: React.FC<SubcontractorDetailProps> = ({ subcontractor, onBack, onNewPayment, onApprovePayment, onUpdate }) => {
  const [activeTab, setActiveTab] = useState<'items' | 'payments' | 'docs'>('items');
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isEditingDate, setIsEditingDate] = useState(false);
  const [tempDate, setTempDate] = useState(subcontractor.contractDate ? subcontractor.contractDate.split('T')[0] : '');
  const [previewDoc, setPreviewDoc] = useState<ContractDocument | null>(null);
  const [approvingPayment, setApprovingPayment] = useState<ProgressPayment | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    const report = await analyzeProgress(subcontractor);
    setAiReport(report || "Analiz yapılamadı.");
    setIsAnalyzing(false);
  };

  const handleExportPayments = () => {
    if (!subcontractor.progressPayments || subcontractor.progressPayments.length === 0) return;

    const headers = ["No", "Tarih", "Durum", "Onceki Toplam", "Bu Donem", "Kumulatif Toplam", "Kesintiler", "Net Odenecek"];
    const rows = subcontractor.progressPayments.map(p => [
      p.number,
      new Date(p.date).toLocaleDateString('tr-TR'),
      p.status === 'Approved' ? 'Onayli' : 'Beklemede',
      p.summary.previousTotal.toString(),
      p.summary.currentTotal.toString(),
      p.summary.cumulativeTotal.toString(),
      (p.summary.retentionAmount + p.summary.stampDutyAmount).toString(),
      p.summary.netPayable.toString()
    ]);

    const csvContent = [headers, ...rows].map(e => e.join(";")).join("\n");
    const blob = new Blob(["\ufeff" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    const url = URL.createObjectURL(blob);
    link.setAttribute("href", url);
    link.setAttribute("download", `${subcontractor.name}_Hakedis_Icmali.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleSaveDate = () => {
    onUpdate({
      ...subcontractor,
      contractDate: new Date(tempDate).toISOString()
    });
    setIsEditingDate(false);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const newDoc: ContractDocument = {
          id: Math.random().toString(36).substr(2, 9),
          url: reader.result as string,
          name: file.name,
          uploadDate: new Date().toISOString()
        };
        onUpdate({
          ...subcontractor,
          contractDocuments: [...(subcontractor.contractDocuments || []), newDoc]
        });
      };
      reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleRemoveDoc = (docId: string) => {
    if (confirm("Bu belgeyi silmek istediğinize emin misiniz?")) {
      onUpdate({
        ...subcontractor,
        contractDocuments: (subcontractor.contractDocuments || []).filter(d => d.id !== docId)
      });
    }
  };

  const lastApprovedPayment = [...(subcontractor.progressPayments || [])].reverse().find(p => p.status === 'Approved');
  const totalPaid = lastApprovedPayment?.summary.cumulativeTotal || 0;
  const progressPercent = subcontractor.totalContractValue > 0 ? (totalPaid / subcontractor.totalContractValue) * 100 : 0;

  return (
    <div className="space-y-6 pb-24 animate-in fade-in duration-500 max-w-4xl mx-auto relative">
      {/* Approval Confirmation Modal */}
      {approvingPayment && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-in fade-in duration-300 no-print">
          <div className="bg-white w-full max-w-sm rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-orange-600 p-6 text-white">
              <div className="flex items-center gap-3 mb-2">
                <ShieldCheck className="w-6 h-6" />
                <h3 className="text-lg font-black uppercase tracking-tight">Hakediş Onayı</h3>
              </div>
              <p className="text-orange-100 text-[10px] font-bold uppercase tracking-widest">Aşağıdaki icmali kontrol edip onaylayınız</p>
            </div>
            <div className="p-6 space-y-4">
              <div className="space-y-3">
                <div className="flex justify-between items-center text-xs">
                  <span className="text-slate-400 font-bold uppercase">Hakediş No</span>
                  <span className="text-slate-900 font-black">#{approvingPayment.number}</span>
                </div>
                <div className="flex justify-between items-center text-xs">
                  <span className="text-slate-400 font-bold uppercase">Dönem İmalat</span>
                  <span className="text-slate-900 font-black">{approvingPayment.summary.currentTotal.toLocaleString('tr-TR')} TL</span>
                </div>
                <div className="flex justify-between items-center text-xs text-rose-500">
                  <span className="font-bold uppercase">Toplam Kesinti</span>
                  <span className="font-black">-{ (approvingPayment.summary.retentionAmount + approvingPayment.summary.stampDutyAmount).toLocaleString('tr-TR') } TL</span>
                </div>
                <div className="pt-3 border-t border-slate-100 flex justify-between items-end">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Ödenecek Net</span>
                  <span className="text-xl font-black text-orange-600">{approvingPayment.summary.netPayable.toLocaleString('tr-TR')} TL</span>
                </div>
              </div>
              <div className="flex flex-col gap-2 pt-4">
                <button 
                  onClick={() => {
                    onApprovePayment(approvingPayment.id);
                    setApprovingPayment(null);
                  }}
                  className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg shadow-slate-200 active:scale-95 transition-all"
                >
                  Onayla ve Maliyete İşle
                </button>
                <button 
                  onClick={() => setApprovingPayment(null)}
                  className="w-full bg-slate-50 text-slate-400 py-3 rounded-2xl font-bold text-xs uppercase tracking-widest hover:bg-slate-100 transition-all"
                >
                  Vazgeç
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Fullscreen Image Preview Modal */}
      {previewDoc && (
        <div className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-black/95 animate-in fade-in duration-300 p-4 no-print">
          <button 
            onClick={() => setPreviewDoc(null)}
            className="absolute top-6 right-6 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white transition-colors"
          >
            <X className="w-6 h-6" />
          </button>
          <div className="w-full max-w-4xl h-[80vh] flex items-center justify-center">
            <img 
              src={previewDoc.url} 
              alt={previewDoc.name} 
              className="max-w-full max-h-full object-contain rounded-lg shadow-2xl"
            />
          </div>
          <div className="mt-6 text-center">
            <p className="text-white font-bold text-lg">{previewDoc.name}</p>
            <p className="text-white/50 text-xs mt-1">Yükleme: {new Date(previewDoc.uploadDate).toLocaleDateString('tr-TR')}</p>
          </div>
        </div>
      )}

      {/* Top Bar */}
      <div className="flex items-center gap-3">
        <button onClick={onBack} className="p-2 bg-white rounded-xl shadow-sm border border-slate-100 hover:bg-slate-50 transition-colors no-print">
          <ArrowLeft className="w-5 h-5 text-slate-600" />
        </button>
        <div className="flex-1">
          <h2 className="text-xl font-bold text-slate-800">{subcontractor.name}</h2>
          <div className="flex items-center flex-wrap gap-2 mt-1">
            <span className="text-[10px] bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full font-bold uppercase tracking-wider">{subcontractor.trade}</span>
            <div className="flex items-center gap-1.5">
              {isEditingDate ? (
                <div className="flex items-center gap-1 bg-white border border-slate-200 rounded-lg p-1 animate-in zoom-in-95 duration-200 no-print">
                  <input 
                    type="date" 
                    value={tempDate}
