import React, { useState, useEffect, useRef } from 'react';
import { Subcontractor, ProgressPayment, Project, Contract, Transaction } from './types';
import Dashboard from './components/Dashboard';
import SubcontractorList from './components/SubcontractorList';
import SubcontractorDetail from './components/SubcontractorDetail';
import ProgressPaymentForm from './components/ProgressPaymentForm';
import Reports from './components/Reports';
import AllPaymentsList from './components/AllPaymentsList';
import ProjectList from './components/ProjectList';
import ProjectForm from './components/ProjectForm';
import ContractForm from './components/ContractForm';
import TransactionList from './components/TransactionList';
import TransactionForm from './components/TransactionForm';
import ContractSummaryList from './components/ContractSummaryList';
import { 
  LayoutGrid, 
  Building2, 
  FileEdit, 
  Wallet, 
  History, 
  PieChart,
  HardHat,
  CloudCheck,
  RefreshCw,
  Database,
  ScrollText
} from 'lucide-react';

const STORAGE_KEY = 'ahmetoglu_santiye_data_v1';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<'dashboard' | 'subcontractors' | 'all-payments' | 'reports' | 'detail' | 'payment-form' | 'add-sub' | 'projects' | 'add-project' | 'contracts' | 'add-contract' | 'transactions' | 'add-transaction' | 'contract-summary'>('dashboard');

  const [projects, setProjects] = useState<Project[]>([]);
  const [subcontractors, setSubcontractors] = useState<Subcontractor[]>([]);
  const [contracts, setContracts] = useState<Contract[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  const [selectedContractId, setSelectedContractId] = useState<string | null>(null);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const isInitialMount = useRef(true);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const data = JSON.parse(saved);
      setProjects(data.projects || []);
      setSubcontractors(data.subcontractors || []);
      setContracts(data.contracts || []);
      setTransactions(data.transactions || []);
    }
  }, []);

  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false;
      return;
    }

    setSaveStatus('saving');
    const timer = setTimeout(() => {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ projects, subcontractors, contracts, transactions }));
      setSaveStatus('saved');

      const resetTimer = setTimeout(() => setSaveStatus('idle'), 2000);
      return () => clearTimeout(resetTimer);
    }, 500);

    return () => clearTimeout(timer);
  }, [projects, subcontractors, contracts, transactions]);

  const handleAddProject = (p: Project) => {
    setProjects([...projects, p]);
    setActiveView('projects');
  };

  const handleAddSubcontractor = (s: Subcontractor) => {
    setSubcontractors([...subcontractors, s]);
    setActiveView('subcontractors');
  };

  const handleAddContract = (c: Contract) => {
    setContracts([...contracts, c]);
    setActiveView('contracts');
  };

  const handleAddTransaction = (t: Transaction) => {
    setTransactions([...transactions, t]);
    setActiveView('transactions');
  };

  const handleUpdateContract = (updated: Contract) => {
    setContracts(prev => prev.map(c => c.id === updated.id ? updated : c));
  };

  const handleAddPayment = (payment: ProgressPayment) => {
    setContracts(prev => prev.map(c => {
      if (c.id === payment.contractId) {
        return {
          ...c,
          progressPayments: [...c.progressPayments, payment]
        };
      }
      return c;
    }));
    setActiveView('detail');
  };

  const handleApprovePayment = (contractId: string, paymentId: string) => {
    setContracts(prev => prev.map(c => {
      if (c.id === contractId) {
        return {
          ...c,
          progressPayments: c.progressPayments.map(p => 
            p.id === paymentId ? { ...p, status: 'Approved' } : p
          )
        };
      }
      return c;
    }));
  };

  const selectedContract = contracts.find(c => c.id === selectedContractId);

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return <Dashboard subcontractors={subcontractors} projects={projects} contracts={contracts} transactions={transactions} />;
      case 'projects':
        return <ProjectList projects={projects} onAdd={() => setActiveView('add-project')} onSelect={() => {}} />;
      case 'add-project':
        return <ProjectForm onCancel={() => setActiveView('projects')} onSave={handleAddProject} />;
      case 'transactions':
        return <TransactionList transactions={transactions} projects={projects} onAdd={() => setActiveView('add-transaction')} />;
      case 'add-transaction':
        return <TransactionForm projects={projects} onCancel={() => setActiveView('transactions')} onSave={handleAddTransaction} />;
      case 'all-payments':
        return (
          <AllPaymentsList 
            contracts={contracts} 
            subcontractors={subcontractors} 
            onSelectContract={(id) => {
              setSelectedContractId(id);
              setActiveView('detail');
            }} 
          />
        );
      case 'contract-summary':
        return (
          <ContractSummaryList 
            contracts={contracts} 
            projects={projects} 
            subcontractors={subcontractors} 
            onSelectContract={(id) => {
              setSelectedContractId(id);
              setActiveView('detail');
            }} 
          />
        );
      case 'contracts':
        return (
          <div className="space-y-6 pb-24">
            <div className="flex justify-between items-center px-1">
              <h1 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Sözleşmeler</h1>
              <button 
                onClick={() => setActiveView('add-contract')}
                className="bg-orange-600 text-white p-3 rounded-2xl shadow-lg shadow-orange-200 active:scale-95 transition-all flex items-center gap-2"
              >
                <FileEdit className="w-5 h-5" />
                <span className="text-[10px] font-black uppercase tracking-widest">Sözleşme Ekle</span>
              </button>
            </div>
            <div className="space-y-4">
              {contracts.length === 0 ? (
                <div className="text-center py-20 bg-white rounded-[2.5rem] border border-dashed border-slate-200">
                  <FileEdit className="w-12 h-12 text-slate-200 mx-auto mb-3" />
                  <p className="text-slate-400 text-sm font-medium">Henüz bir sözleşme tanımlanmamış.</p>
                </div>
              ) : (
                contracts.map(c => {
                  const project = projects.find(p => p.id === c.projectId);
                  const sub = subcontractors.find(s => s.id === c.subcontractorId);
                  const lastApproved = [...c.progressPayments].reverse().find(p => p.status === 'Approved');

                  return (
                    <button 
                      key={c.id} 
                      onClick={() => { setSelectedContractId(c.id); setActiveView('detail'); }}
                      className="w-full text-left bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm hover:border-orange-100 transition-all flex flex-col gap-3 group"
                    >
                      <div className="flex justify-between items-start">
                        <div>
                          <h3 className="font-black text-slate-800 text-sm uppercase group-hover:text-orange-600 transition-colors">{c.title}</h3>
                          <p className="text-[10px] font-bold text-slate-400 mt-0.5">{project?.name} / {sub?.name}</p>
                        </div>
                        <span className="bg-slate-50 text-slate-600 text-[10px] font-black px-3 py-1 rounded-full uppercase">
                          {c.totalValue.toLocaleString('tr-TR')} TL
                        </span>
                      </div>
                      <div className="w-full bg-slate-100 h-1.5 rounded-full overflow-hidden">
                        <div 
                          className="bg-orange-600 h-full rounded-full transition-all duration-1000" 
                          style={{ width: `${Math.min(100, (lastApproved?.summary.cumulativeTotal || 0) / c.totalValue * 100)}%` }}
                        />
                      </div>
                    </button>
                  );
                })
              )}
            </div>
          </div>
        );
      case 'add-contract':
        return <ContractForm projects={projects} subcontractors={subcontractors} onCancel={() => setActiveView('contracts')} onSave={handleAddContract} />;
      case 'subcontractors':
        return <SubcontractorList subcontractors={subcontractors} onSelect={() => {}} onAdd={() => setActiveView('add-sub')} />;
      case 'add-sub':
        return (
          <div className="space-y-6 pb-24">
            <h2 className="text-xl font-bold">Taşeron Ekle</h2>
            <div className="bg-white p-6 rounded-3xl border shadow-sm space-y-4">
               <input 
                type="text" 
                placeholder="İsim" 
                className="w-full p-4 bg-slate-50 border rounded-2xl" 
                onBlur={(e) => {
                  if (e.target.value) handleAddSubcontractor({ id: Math.random().toString(36).substr(2, 9), name: e.target.value, trade: 'Genel' });
                }}
               />
               <button onClick={() => setActiveView('subcontractors')} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-bold">Geri Dön</button>
            </div>
          </div>
        );
      case 'detail':
        return selectedContract ? (
          <SubcontractorDetail 
            subcontractor={{ ...subcontractors.find(s => s.id === selectedContract.subcontractorId)!, contractDate: selectedContract.contractDate, totalContractValue: selectedContract.totalValue, workItems: selectedContract.workItems, progressPayments: selectedContract.progressPayments, contractDocuments: selectedContract.documents }}
            onBack={() => setActiveView('contract-summary')} 
            onNewPayment={() => setActiveView('payment-form')}
            onApprovePayment={(pid) => handleApprovePayment(selectedContract.id, pid)}
            onUpdate={(updatedSub) => {
               handleUpdateContract({
                 ...selectedContract,
                 workItems: updatedSub.workItems,
                 progressPayments: updatedSub.progressPayments,
                 documents: updatedSub.contractDocuments || []
               });
            }}
          />
        ) : null;
      case 'payment-form':
        return selectedContract ? (
          <ProgressPaymentForm 
            subcontractor={{ ...subcontractors.find(s => s.id === selectedContract.subcontractorId)!, contractDate: selectedContract.contractDate, totalContractValue: selectedContract.totalValue, workItems: selectedContract.workItems, progressPayments: selectedContract.progressPayments, contractDocuments: selectedContract.documents }} 
            onCancel={() => setActiveView('detail')} 
            onSave={(p) => handleAddPayment({ ...p, contractId: selectedContract.id })}
          />
        ) : null;
      case 'reports':
        return (
          <Reports 
            subcontractors={subcontractors} 
            transactions={transactions} 
            contracts={contracts} 
            projects={projects} 
            onNewPayment={(contractId) => {
              setSelectedContractId(contractId);
              setActiveView('payment-form');
            }}
          />
        );
      default:
        return <Dashboard subcontractors={subcontractors} projects={projects} contracts={contracts} transactions={transactions} />;
    }
  };

  const NavItem = ({ view, icon: Icon, label, activeViews = [] }: { view: any, icon: any, label: string, activeViews?: string[] }) => {
    const isActive = activeView === view || activeViews.includes(activeView);
    return (
      <button 
        onClick={() => setActiveView(view)}
        className={`flex flex-col items-center justify-center gap-1.5 transition-all duration-300 relative px-1 py-2 rounded-2xl flex-1 ${
          isActive 
            ? 'text-orange-600' 
            : 'text-slate-400 hover:text-slate-600'
        }`}
      >
        <div className={`p-2 rounded-xl transition-all duration-300 ${isActive ? 'bg-orange-50 shadow-inner' : 'bg-transparent'}`}>
          <Icon className={`w-5 h-5 transition-transform duration-300 ${isActive ? 'scale-110 stroke-[2.5px]' : 'stroke-2'}`} />
        </div>
        <span className={`text-[9px] uppercase tracking-widest leading-none font-black transition-all ${isActive ? 'opacity-100 translate-y-0' : 'opacity-80'}`}>
          {label}
        </span>
        {isActive && (
          <span className="absolute -bottom-0.5 w-4 h-1 bg-orange-600 rounded-full animate-in fade-in zoom-in duration-300" />
        )}
      </button>
    );
  };

  return (
    <div className="max-w-md mx-auto min-h-screen relative bg-slate-50 flex flex-col selection:bg-orange-100">
      <main className="flex-1 p-5 overflow-y-auto no-scrollbar">
        {/* Top Header Logo Area & Save Status */}
        <div className="flex items-center justify-between mb-6 px-1">
           <div className="flex items-center gap-2">
              <div className="bg-orange-600 p-2 rounded-xl shadow-lg shadow-orange-200">
                 <HardHat className="w-6 h-6 text-white" />
              </div>
              <div>
                <h2 className="text-sm font-black text-slate-900 leading-none uppercase tracking-tight">Ahmetoğlu</h2>
                <div className="flex items-center gap-1.5 mt-0.5">
                  <p className="text-[10px] font-bold text-orange-600 uppercase tracking-widest">Şantiye Pro</p>
                  {saveStatus !== 'idle' && (
                    <div className="flex items-center gap-1 animate-in fade-in slide-in-from-left duration-300">
                      <span className="w-1 h-1 bg-slate-300 rounded-full" />
                      <div className="flex items-center gap-1 text-[8px] font-black uppercase tracking-tighter text-slate-400">
                        {saveStatus === 'saving' ? (
                          <>
                            <RefreshCw className="w-2 h-2 animate-spin" /> Yedekleniyor
                          </>
                        ) : (
                          <>
                            <CloudCheck className="w-2.5 h-2.5 text-emerald-500" /> Kaydedildi
                          </>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              </div>
           </div>
           <div className="w-8 h-8 rounded-full bg-white border border-slate-100 shadow-sm flex items-center justify-center group relative cursor-help">
              <Database className="w-4 h-4 text-slate-400 group-hover:text-orange-500 transition-colors" />
              <div className="absolute top-full right-0 mt-2 w-48 bg-slate-900 text-white text-[9px] p-3 rounded-2xl opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all z-[60] shadow-2xl leading-relaxed">
                <p className="font-black mb-1 uppercase text-orange-500 tracking-widest">Veri Güvenliği</p>
                Tüm verileriniz uçtan uca şifreli olarak sadece bu cihazda (localStorage) saklanır. İnternet olmasa bile çalışmaya devam edebilirsiniz.
              </div>
           </div>
        </div>

        {renderView()}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/80 backdrop-blur-2xl border-t border-slate-100 px-2 py-1.5 flex justify-between items-center z-50 shadow-[0_-15px_40px_-10px_rgba(0,0,0,0.08)]">
        <NavItem view="dashboard" icon={LayoutGrid} label="Panel" />
        <NavItem view="projects" icon={Building2} label="Proje" activeViews={['add-project']} />
        <NavItem view="contract-summary" icon={ScrollText} label="İcmal" activeViews={['detail', 'payment-form']} />
        <NavItem view="contracts" icon={FileEdit} label="Sözleşme" activeViews={['add-contract']} />
        <NavItem view="transactions" icon={Wallet} label="Kasa" activeViews={['add-transaction']} />
        <NavItem view="reports" icon={PieChart} label="Analiz" />
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  User, 
  Settings as SettingsIcon, 
  Database, 
  Download, 
  Upload, 
  Trash2, 
  ShieldAlert, 
  Bell, 
  Info,
  Building2,
  Briefcase,
  CheckCircle2,
  RefreshCw
} from 'lucide-react';

interface SettingsProps {
  onResetData: () => void;
  onImportData: (data: any) => void;
  allData: any;
}

const Settings: React.FC<SettingsProps> = ({ onResetData, onImportData, allData }) => {
  const [userName, setUserName] = useState(localStorage.getItem('user_name') || '');
  const [companyName, setCompanyName] = useState(localStorage.getItem('company_name') || '');
  const [role, setRole] = useState(localStorage.getItem('user_role') || 'Proje Müdürü');
  const [isSaved, setIsSaved] = useState(false);
  const [showResetConfirm, setShowResetConfirm] = useState(false);

  const handleSaveProfile = () => {
    localStorage.setItem('user_name', userName);
    localStorage.setItem('company_name', companyName);
    localStorage.setItem('user_role', role);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const handleExportData = () => {
    const dataStr = JSON.stringify(allData, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Santiye_Pro_Yedek_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
  };

  const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (confirm('Mevcut verileriniz silinecek ve yedek yüklenecek. Onaylıyor musunuz?')) {
          onImportData(json);
          alert('Veriler başarıyla yüklendi!');
        }
      } catch (err) {
        alert('Geçersiz yedek dosyası.');
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="space-y-6 pb-24 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="px-1">
        <h1 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Kullanıcı & Ayarlar</h1>
        <p className="text-[10px] text-orange-600 font-bold uppercase tracking-widest mt-1">Sistem ve Profil Tercihleri</p>
      </div>

      {/* Profile Section */}
      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
        <div className="p-6 bg-slate-50/50 border-b border-slate-100 flex items-center gap-3">
          <div className="p-2 bg-slate-900 rounded-xl text-white">
            <User className="w-5 h-5" />
          </div>
          <h3 className="text-xs font-black text-slate-800 uppercase tracking-widest">Kullanıcı Profili</h3>
        </div>
        <div className="p-6 space-y-4">
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Ad Soyad</label>
            <div className="relative">
              <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 w-4 h-4" />
              <input 
                type="text" 
                value={userName}
                onChange={(e) => setUserName(e.target.value)}
                placeholder="Örn: Ahmet Yılmaz"
                className="w-full pl-11 pr-4 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold focus:ring-2 focus:ring-orange-500 outline-none transition-all"
              />
            </div>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Şirket / Firma Adı</label>
            <div className="relative">
              <Building2 className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 w-4 h-4" />
              <input 
                type="text" 
                value={companyName}
                onChange={(e) => setCompanyName(e.target.value)}
                placeholder="Örn: Ahmetoğlu İnşaat A.Ş."
                className="w-full pl-11 pr-4 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold focus:ring-2 focus:ring-orange-500 outline-none transition-all"
              />
            </div>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Görev / Unvan</label>
            <div className="relative">
              <Briefcase className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 w-4 h-4" />
              <select 
                value={role}
                onChange={(e) => setRole(e.target.value)}
                className="w-full pl-11 pr-4 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold focus:ring-2 focus:ring-orange-500 outline-none transition-all appearance-none"
              >
                <option value="Proje Müdürü">Proje Müdürü</option>
                <option value="Şantiye Şefi">Şantiye Şefi</option>
                <option value="Hakediş Mühendisi">Hakediş Mühendisi</option>
                <option value="Firma Sahibi">Firma Sahibi</option>
              </select>
            </div>
          </div>
          <button 
            onClick={handleSaveProfile}
            className={`w-full py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-2 ${isSaved ? 'bg-emerald-500 text-white' : 'bg-orange-600 text-white shadow-lg shadow-orange-200 active:scale-95'}`}
          >
            {isSaved ? <><CheckCircle2 className="w-4 h-4" /> Güncellendi</> : 'Değişiklikleri Kaydet'}
          </button>
        </div>
      </div>

      {/* Data Operations */}
      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
        <div className="p-6 bg-slate-50/50 border-b border-slate-100 flex items-center gap-3">
          <div className="p-2 bg-slate-900 rounded-xl text-white">
            <Database className="w-5 h-5" />
          </div>
          <h3 className="text-xs font-black text-slate-800 uppercase tracking-widest">Veri Yönetimi</h3>
        </div>
        <div className="p-6 space-y-3">
          <button 
            onClick={handleExportData}
            className="w-full p-4 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded-2xl flex items-center justify-between group transition-all"
          >
            <div className="flex items-center gap-3">
              <div className="p-2 bg-white rounded-lg shadow-sm group-hover:bg-blue-50 transition-colors">
                <Download className="w-4 h-4 text-blue-600" />
              </div>
              <div className="text-left">
                <p className="text-xs font-black text-slate-800 uppercase">Tüm Verileri Yedekle</p>
                <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter">JSON Formatında İndir</p>
              </div>
            </div>
            <RefreshCw className="w-4 h-4 text-slate-200 group-hover:rotate-180 transition-transform duration-500" />
          </button>

          <label className="w-full p-4 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded-2xl flex items-center justify-between group transition-all cursor-pointer">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-white rounded-lg shadow-sm group-hover:bg-emerald-50 transition-colors">
                <Upload className="w-4 h-4 text-emerald-600" />
              </div>
              <div className="text-left">
                <p className="text-xs font-black text-slate-800 uppercase">Yedek Dosyası Yükle</p>
                <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter">Cihazdan JSON Dosyası Seç</p>
              </div>
            </div>
            <input type="file" className="hidden" accept=".json" onChange={handleImportFile} />
          </label>

          <div className="pt-4 mt-2 border-t border-slate-50">
            {showResetConfirm ? (
              <div className="bg-rose-50 p-4 rounded-2xl border border-rose-100 animate-in zoom-in-95 duration-200">
                <div className="flex items-start gap-3 mb-4">
                  <ShieldAlert className="w-5 h-5 text-rose-600 shrink-0" />
                  <p className="text-[11px] font-bold text-rose-700 leading-relaxed uppercase">
                    Tüm projeleriniz, taşeronlarınız ve hakedişleriniz kalıcı olarak silinecektir. Bu işlem geri alınamaz!
                  </p>
                </div>
                <div className="flex gap-2">
                  <button 
                    onClick={() => { onResetData(); setShowResetConfirm(false); }}
                    className="flex-1 bg-rose-600 text-white py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-rose-200"
                  >
                    Evet, Her Şeyi Sil
                  </button>
                  <button 
                    onClick={() => setShowResetConfirm(false)}
                    className="flex-1 bg-white text-slate-600 py-2.5 rounded-xl text-[10px] font-black uppercase border border-slate-200"
                  >
                    Vazgeç
                  </button>
                </div>
              </div>
            ) : (
              <button 
                onClick={() => setShowResetConfirm(true)}
                className="w-full p-4 text-rose-600 bg-rose-50/50 hover:bg-rose-50 rounded-2xl flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-[0.2em] transition-all"
              >
                <Trash2 className="w-4 h-4" /> Fabrika Ayarlarına Dön
              </button>
            )}
          </div>
        </div>
      </div>

      {/* App Info */}
      <div className="bg-slate-900 rounded-[2.5rem] p-8 text-white relative overflow-hidden">
        <div className="absolute top-0 right-0 p-8 opacity-10">
