import React, { useState, useEffect, useRef } from 'react';
import { Subcontractor, ProgressPayment, Project, Contract, Transaction } from './types';
import Dashboard from './components/Dashboard';
import SubcontractorList from './components/SubcontractorList';
import SubcontractorDetail from './components/SubcontractorDetail';
import ProgressPaymentForm from './components/ProgressPaymentForm';
import Reports from './components/Reports';
import AllPaymentsList from './components/AllPaymentsList';
import ProjectList from './components/ProjectList';
import ProjectForm from './components/ProjectForm';
import ContractForm from './components/ContractForm';
import TransactionList from './components/TransactionList';
import TransactionForm from './components/TransactionForm';
import ContractSummaryList from './components/ContractSummaryList';
import Settings from './components/Settings';
import { 
  LayoutGrid, 
  Building2, 
  FileEdit, 
  Wallet, 
  History, 
  PieChart,
  HardHat,
  CloudCheck,
  RefreshCw,
  Database,
  ScrollText,
  Settings as SettingsIcon
} from 'lucide-react';

const STORAGE_KEY = 'ahmetoglu_santiye_data_v1';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<'dashboard' | 'subcontractors' | 'all-payments' | 'reports' | 'detail' | 'payment-form' | 'add-sub' | 'projects' | 'add-project' | 'contracts' | 'add-contract' | 'transactions' | 'add-transaction' | 'contract-summary' | 'settings'>('dashboard');

  const [projects, setProjects] = useState<Project[]>([]);
  const [subcontractors, setSubcontractors] = useState<Subcontractor[]>([]);
  const [contracts, setContracts] = useState<Contract[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  const [selectedContractId, setSelectedContractId] = useState<string | null>(null);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const isInitialMount = useRef(true);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const data = JSON.parse(saved);
      setProjects(data.projects || []);
      setSubcontractors(data.subcontractors || []);
      setContracts(data.contracts || []);
      setTransactions(data.transactions || []);
    }
  }, []);

  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false;
      return;
    }

    setSaveStatus('saving');
    const timer = setTimeout(() => {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ projects, subcontractors, contracts, transactions }));
      setSaveStatus('saved');

      const resetTimer = setTimeout(() => setSaveStatus('idle'), 2000);
      return () => clearTimeout(resetTimer);
    }, 500);

    return () => clearTimeout(timer);
  }, [projects, subcontractors, contracts, transactions]);

  const handleResetData = () => {
    setProjects([]);
    setSubcontractors([]);
    setContracts([]);
    setTransactions([]);
    localStorage.removeItem(STORAGE_KEY);
    setActiveView('dashboard');
  };

  const handleImportData = (data: any) => {
    if (data.projects) setProjects(data.projects);
    if (data.subcontractors) setSubcontractors(data.subcontractors);
    if (data.contracts) setContracts(data.contracts);
    if (data.transactions) setTransactions(data.transactions);
    setActiveView('dashboard');
  };

  const handleAddProject = (p: Project) => {
    setProjects([...projects, p]);
    setActiveView('projects');
  };

  const handleAddSubcontractor = (s: Subcontractor) => {
    setSubcontractors([...subcontractors, s]);
    setActiveView('subcontractors');
  };

  const handleAddContract = (c: Contract) => {
    setContracts([...contracts, c]);
    setActiveView('contracts');
  };

  const handleAddTransaction = (t: Transaction) => {
    setTransactions([...transactions, t]);
    setActiveView('transactions');
  };

  const handleUpdateContract = (updated: Contract) => {
    setContracts(prev => prev.map(c => c.id === updated.id ? updated : c));
  };

  const handleAddPayment = (payment: ProgressPayment) => {
    setContracts(prev => prev.map(c => {
      if (c.id === payment.contractId) {
        return {
          ...c,
          progressPayments: [...c.progressPayments, payment]
        };
      }
      return c;
    }));
    setActiveView('detail');
  };

  const handleApprovePayment = (contractId: string, paymentId: string) => {
    setContracts(prev => prev.map(c => {
      if (c.id === contractId) {
        return {
          ...c,
          progressPayments: c.progressPayments.map(p => 
            p.id === paymentId ? { ...p, status: 'Approved' } : p
          )
        };
      }
      return c;
    }));
  };

  const selectedContract = contracts.find(c => c.id === selectedContractId);

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return <Dashboard subcontractors={subcontractors} projects={projects} contracts={contracts} transactions={transactions} />;
      case 'projects':
        return <ProjectList projects={projects} onAdd={() => setActiveView('add-project')} onSelect={() => {}} />;
      case 'add-project':
        return <ProjectForm onCancel={() => setActiveView('projects')} onSave={handleAddProject} />;
      case 'transactions':
        return <TransactionList transactions={transactions} projects={projects} onAdd={() => setActiveView('add-transaction')} />;
      case 'add-transaction':
        return <TransactionForm projects={projects} onCancel={() => setActiveView('transactions')} onSave={handleAddTransaction} />;
      case 'all-payments':
        return (
          <AllPaymentsList 
            contracts={contracts} 
            subcontractors={subcontractors} 
            onSelectContract={(id) => {
              setSelectedContractId(id);
              setActiveView('detail');
            }} 
          />
        );
      case 'contract-summary':
        return (
          <ContractSummaryList 
            contracts={contracts} 
            projects={projects} 
            subcontractors={subcontractors} 
            onSelectContract={(id) => {
              setSelectedContractId(id);
              setActiveView('detail');
            }} 
          />
        );
      case 'contracts':
        return (
          <div className="space-y-6 pb-24">
            <div className="flex justify-between items-center px-1">
              <h1 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Sözleşmeler</h1>
              <button 
                onClick={() => setActiveView('add-contract')}
                className="bg-orange-600 text-white p-3 rounded-2xl shadow-lg shadow-orange-200 active:scale-95 transition-all flex items-center gap-2"
              >
                <FileEdit className="w-5 h-5" />
                <span className="text-[10px] font-black uppercase tracking-widest">Sözleşme Ekle</span>
              </button>
            </div>
            <div className="space-y-4">
              {contracts.length === 0 ? (
                <div className="text-center py-20 bg-white rounded-[2.5rem] border border-dashed border-slate-200">
                  <FileEdit className="w-12 h-12 text-slate-200 mx-auto mb-3" />
                  <p className="text-slate-400 text-sm font-medium">Henüz bir sözleşme tanımlanmamış.</p>
                </div>
              ) : (
                contracts.map(c => {
                  const project = projects.find(p => p.id === c.projectId);
                  const sub = subcontractors.find(s => s.id === c.subcontractorId);
                  const lastApproved = [...c.progressPayments].reverse().find(p => p.status === 'Approved');

                  return (
                    <button 
                      key={c.id} 
                      onClick={() => { setSelectedContractId(c.id); setActiveView('detail'); }}
                      className="w-full text-left bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm hover:border-orange-100 transition-all flex flex-col gap-3 group"
                    >
                      <div className="flex justify-between items-start">
                        <div>
                          <h3 className="font-black text-slate-800 text-sm uppercase group-hover:text-orange-600 transition-colors">{c.title}</h3>
                          <p className="text-[10px] font-bold text-slate-400 mt-0.5">{project?.name} / {sub?.name}</p>
                        </div>
                        <span className="bg-slate-50 text-slate-600 text-[10px] font-black px-3 py-1 rounded-full uppercase">
                          {c.totalValue.toLocaleString('tr-TR')} TL
                        </span>
                      </div>
                      <div className="w-full bg-slate-100 h-1.5 rounded-full overflow-hidden">
                        <div 
                          className="bg-orange-600 h-full rounded-full transition-all duration-1000" 
                          style={{ width: `${Math.min(100, (lastApproved?.summary.cumulativeTotal || 0) / c.totalValue * 100)}%` }}
                        />
                      </div>
                    </button>
                  );
                })
              )}
            </div>
          </div>
        );
      case 'add-contract':
        return <ContractForm projects={projects} subcontractors={subcontractors} onCancel={() => setActiveView('contracts')} onSave={handleAddContract} />;
      case 'subcontractors':
        return <SubcontractorList subcontractors={subcontractors} onSelect={() => {}} onAdd={() => setActiveView('add-sub')} />;
      case 'add-sub':
        return (
          <div className="space-y-6 pb-24">
            <h2 className="text-xl font-bold">Taşeron Ekle</h2>
            <div className="bg-white p-6 rounded-3xl border shadow-sm space-y-4">
               <input 
                type="text" 
                placeholder="İsim" 
                className="w-full p-4 bg-slate-50 border rounded-2xl" 
                onBlur={(e) => {
                  if (e.target.value) handleAddSubcontractor({ id: Math.random().toString(36).substr(2, 9), name: e.target.value, trade: 'Genel' });
                }}
               />
               <button onClick={() => setActiveView('subcontractors')} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-bold">Geri Dön</button>
            </div>
          </div>
        );
      case 'detail':
        return selectedContract ? (
          <SubcontractorDetail 
            subcontractor={{ ...subcontractors.find(s => s.id === selectedContract.subcontractorId)!, contractDate: selectedContract.contractDate, totalContractValue: selectedContract.totalValue, workItems: selectedContract.workItems, progressPayments: selectedContract.progressPayments, contractDocuments: selectedContract.documents }}
            onBack={() => setActiveView('contract-summary')} 
            onNewPayment={() => setActiveView('payment-form')}
            onApprovePayment={(pid) => handleApprovePayment(selectedContract.id, pid)}
            onUpdate={(updatedSub) => {
               handleUpdateContract({
                 ...selectedContract,
                 workItems: updatedSub.workItems,
                 progressPayments: updatedSub.progressPayments,
                 documents: updatedSub.contractDocuments || []
               });
            }}
          />
        ) : null;
      case 'payment-form':
        return selectedContract ? (
          <ProgressPaymentForm 
            subcontractor={{ ...subcontractors.find(s => s.id === selectedContract.subcontractorId)!, contractDate: selectedContract.contractDate, totalContractValue: selectedContract.totalValue, workItems: selectedContract.workItems, progressPayments: selectedContract.progressPayments, contractDocuments: selectedContract.documents }} 
            onCancel={() => setActiveView('detail')} 
            onSave={(p) => handleAddPayment({ ...p, contractId: selectedContract.id })}
          />
        ) : null;
      case 'reports':
        return (
          <Reports 
            subcontractors={subcontractors} 
            transactions={transactions} 
            contracts={contracts} 
            projects={projects} 
            onNewPayment={(contractId) => {
              setSelectedContractId(contractId);
              setActiveView('payment-form');
            }}
          />
        );
      case 'settings':
        return (
          <Settings 
            onResetData={handleResetData}
            onImportData={handleImportData}
            allData={{ projects, subcontractors, contracts, transactions }}
          />
        );
      default:
        return <Dashboard subcontractors={subcontractors} projects={projects} contracts={contracts} transactions={transactions} />;
    }
  };

  const NavItem = ({ view, icon: Icon, label, activeViews = [] }: { view: any, icon: any, label: string, activeViews?: string[] }) => {
    const isActive = activeView === view || activeViews.includes(activeView);
    return (
      <button 
        onClick={() => setActiveView(view)}
        className={`flex flex-col items-center justify-center gap-1.5 transition-all duration-300 relative px-1 py-2 rounded-2xl flex-1 ${
          isActive 
            ? 'text-orange-600' 
            : 'text-slate-400 hover:text-slate-600'
        }`}
      >
        <div className={`p-2 rounded-xl transition-all duration-300 ${isActive ? 'bg-orange-50 shadow-inner' : 'bg-transparent'}`}>
          <Icon className={`w-5 h-5 transition-transform duration-300 ${isActive ? 'scale-110 stroke-[2.5px]' : 'stroke-2'}`} />
        </div>
        <span className={`text-[9px] uppercase tracking-widest leading-none font-black transition-all ${isActive ? 'opacity-100 translate-y-0' : 'opacity-80'}`}>
          {label}
        </span>
        {isActive && (
          <span className="absolute -bottom-0.5 w-4 h-1 bg-orange-600 rounded-full animate-in fade-in zoom-in duration-300" />
        )}
      </button>
    );
  };

  return (
    <div className="max-w-md mx-auto min-h-screen relative bg-slate-50 flex flex-col selection:bg-orange-100">
      <main className="flex-1 p-5 overflow-y-auto no-scrollbar">
        {/* Top Header Logo Area & Save Status */}
        <div className="flex items-center justify-between mb-6 px-1">
           <div className="flex items-center gap-2">
              <div className="bg-orange-600 p-2 rounded-xl shadow-lg shadow-orange-200">
                 <HardHat className="w-6 h-6 text-white" />
              </div>
              <div>
                <h2 className="text-sm font-black text-slate-900 leading-none uppercase tracking-tight">Ahmetoğlu</h2>
                <div className="flex items-center gap-1.5 mt-0.5">
                  <p className="text-[10px] font-bold text-orange-600 uppercase tracking-widest">Şantiye Pro</p>
                  {saveStatus !== 'idle' && (
                    <div className="flex items-center gap-1 animate-in fade-in slide-in-from-left duration-300">
                      <span className="w-1 h-1 bg-slate-300 rounded-full" />
                      <div className="flex items-center gap-1 text-[8px] font-black uppercase tracking-tighter text-slate-400">
                        {saveStatus === 'saving' ? (
                          <>
                            <RefreshCw className="w-2 h-2 animate-spin" /> Yedekleniyor
                          </>
                        ) : (
                          <>
                            <CloudCheck className="w-2.5 h-2.5 text-emerald-500" /> Kaydedildi
                          </>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              </div>
           </div>
           <div className="w-8 h-8 rounded-full bg-white border border-slate-100 shadow-sm flex items-center justify-center group relative cursor-help">
              <Database className="w-4 h-4 text-slate-400 group-hover:text-orange-500 transition-colors" />
              <div className="absolute top-full right-0 mt-2 w-48 bg-slate-900 text-white text-[9px] p-3 rounded-2xl opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all z-[60] shadow-2xl leading-relaxed">
                <p className="font-black mb-1 uppercase text-orange-500 tracking-widest">Veri Güvenliği</p>
                Tüm verileriniz uçtan uca şifreli olarak sadece bu cihazda (localStorage) saklanır. İnternet olmasa bile çalışmaya devam edebilirsiniz.
              </div>
           </div>
        </div>

        {renderView()}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/80 backdrop-blur-2xl border-t border-slate-100 px-2 py-1.5 flex justify-between items-center z-50 shadow-[0_-15px_40px_-10px_rgba(0,0,0,0.08)]">
        <NavItem view="dashboard" icon={LayoutGrid} label="Panel" />
        <NavItem view="contract-summary" icon={ScrollText} label="İcmal" activeViews={['detail', 'payment-form']} />
        <NavItem view="transactions" icon={Wallet} label="Kasa" activeViews={['add-transaction']} />
        <NavItem view="reports" icon={PieChart} label="Analiz" />
        <NavItem view="settings" icon={SettingsIcon} label="Ayarlar" />
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Subcontractor, ProgressPayment, Project, Contract, Transaction } from './types';
import Dashboard from './components/Dashboard';
import SubcontractorList from './components/SubcontractorList';
import SubcontractorDetail from './components/SubcontractorDetail';
import ProgressPaymentForm from './components/ProgressPaymentForm';
import Reports from './components/Reports';
import AllPaymentsList from './components/AllPaymentsList';
import ProjectList from './components/ProjectList';
import ProjectForm from './components/ProjectForm';
import ContractForm from './components/ContractForm';
import TransactionList from './components/TransactionList';
import TransactionForm from './components/TransactionForm';
import ContractSummaryList from './components/ContractSummaryList';
import Settings from './components/Settings';
import { 
  LayoutGrid, 
  Building2, 
  FileEdit, 
  Wallet, 
  PieChart,
  HardHat,
  CloudCheck,
  RefreshCw,
  Database,
  ScrollText,
  Settings as SettingsIcon,
  Menu,
  X
} from 'lucide-react';

const STORAGE_KEY = 'ahmetoglu_santiye_data_v1';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<'dashboard' | 'subcontractors' | 'all-payments' | 'reports' | 'detail' | 'payment-form' | 'add-sub' | 'projects' | 'add-project' | 'contracts' | 'add-contract' | 'transactions' | 'add-transaction' | 'contract-summary' | 'settings'>('dashboard');

  const [projects, setProjects] = useState<Project[]>([]);
  const [subcontractors, setSubcontractors] = useState<Subcontractor[]>([]);
  const [contracts, setContracts] = useState<Contract[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  const [selectedContractId, setSelectedContractId] = useState<string | null>(null);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const isInitialMount = useRef(true);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const data = JSON.parse(saved);
      setProjects(data.projects || []);
      setSubcontractors(data.subcontractors || []);
      setContracts(data.contracts || []);
      setTransactions(data.transactions || []);
    }
  }, []);

  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false;
      return;
    }
    setSaveStatus('saving');
    const timer = setTimeout(() => {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ projects, subcontractors, contracts, transactions }));
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 500);
    return () => clearTimeout(timer);
  }, [projects, subcontractors, contracts, transactions]);

  const handleResetData = () => {
    if(confirm('Tüm veriler kalıcı olarak silinecek. Emin misiniz?')) {
      setProjects([]); setSubcontractors([]); setContracts([]); setTransactions([]);
      localStorage.removeItem(STORAGE_KEY);
      setActiveView('dashboard');
    }
  };

  const handleImportData = (data: any) => {
    if (data.projects) setProjects(data.projects);
    if (data.subcontractors) setSubcontractors(data.subcontractors);
    if (data.contracts) setContracts(data.contracts);
    if (data.transactions) setTransactions(data.transactions);
    setActiveView('dashboard');
  };

  const handleUpdateContract = (updated: Contract) => {
    setContracts(prev => prev.map(c => c.id === updated.id ? updated : c));
  };

  const handleApprovePayment = (contractId: string, paymentId: string) => {
    setContracts(prev => prev.map(c => {
      if (c.id === contractId) {
        return {
          ...c,
          progressPayments: c.progressPayments.map(p => 
            p.id === paymentId ? { ...p, status: 'Approved' } : p
          )
        };
      }
      return c;
    }));
  };

  const selectedContract = contracts.find(c => c.id === selectedContractId);

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <Dashboard subcontractors={subcontractors} projects={projects} contracts={contracts} transactions={transactions} />;
      case 'projects': return <ProjectList projects={projects} onAdd={() => setActiveView('add-project')} onSelect={() => {}} />;
      case 'add-project': return <ProjectForm onCancel={() => setActiveView('projects')} onSave={(p) => { setProjects([...projects, p]); setActiveView('projects'); }} />;
      case 'transactions': return <TransactionList transactions={transactions} projects={projects} onAdd={() => setActiveView('add-transaction')} />;
      case 'add-transaction': return <TransactionForm projects={projects} onCancel={() => setActiveView('transactions')} onSave={(t) => { setTransactions([...transactions, t]); setActiveView('transactions'); }} />;
      case 'contract-summary': return <ContractSummaryList contracts={contracts} projects={projects} subcontractors={subcontractors} onSelectContract={(id) => { setSelectedContractId(id); setActiveView('detail'); }} />;
      case 'contracts': return (
        <div className="space-y-6 pb-24 max-w-5xl mx-auto">
          <div className="flex justify-between items-center px-1">
            <h1 className="text-2xl md:text-3xl font-black text-slate-800 uppercase tracking-tight">Sözleşmeler</h1>
            <button onClick={() => setActiveView('add-contract')} className="bg-orange-600 text-white p-3 md:px-6 rounded-2xl shadow-lg active:scale-95 transition-all flex items-center gap-2">
              <FileEdit className="w-5 h-5" />
              <span className="hidden md:inline text-xs font-black uppercase tracking-widest">Yeni Sözleşme</span>
            </button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {contracts.map(c => {
              const project = projects.find(p => p.id === c.projectId);
              const sub = subcontractors.find(s => s.id === c.subcontractorId);
              const lastApproved = [...c.progressPayments].reverse().find(p => p.status === 'Approved');
              return (
                <button key={c.id} onClick={() => { setSelectedContractId(c.id); setActiveView('detail'); }} className="text-left bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm hover:border-orange-500 hover:shadow-xl transition-all flex flex-col gap-4">
                  <div className="flex justify-between items-start">
                    <div>
                      <h3 className="font-black text-slate-800 text-sm uppercase">{c.title}</h3>
                      <p className="text-[10px] font-bold text-slate-400 mt-0.5">{project?.name} / {sub?.name}</p>
                    </div>
                  </div>
                  <div className="mt-auto">
                    <div className="flex justify-between text-[10px] font-bold mb-1 uppercase tracking-wider">
                      <span className="text-slate-400">İlerleme</span>
                      <span className="text-orange-600">%{Math.min(100, (lastApproved?.summary.cumulativeTotal || 0) / c.totalValue * 100).toFixed(0)}</span>
                    </div>
                    <div className="w-full bg-slate-100 h-2 rounded-full overflow-hidden">
                      <div className="bg-orange-600 h-full transition-all duration-1000" style={{ width: `${Math.min(100, (lastApproved?.summary.cumulativeTotal || 0) / c.totalValue * 100)}%` }} />
                    </div>
                  </div>
                </button>
              );
            })}
          </div>
        </div>
      );
      case 'add-contract': return <ContractForm projects={projects} subcontractors={subcontractors} onCancel={() => setActiveView('contracts')} onSave={(c) => { setContracts([...contracts, c]); setActiveView('contracts'); }} />;
      case 'detail': return selectedContract ? <SubcontractorDetail subcontractor={{ ...subcontractors.find(s => s.id === selectedContract.subcontractorId)!, contractDate: selectedContract.contractDate, totalContractValue: selectedContract.totalValue, workItems: selectedContract.workItems, progressPayments: selectedContract.progressPayments, contractDocuments: selectedContract.documents }} onBack={() => setActiveView('contract-summary')} onNewPayment={() => setActiveView('payment-form')} onApprovePayment={(pid) => handleApprovePayment(selectedContract.id, pid)} onUpdate={(updatedSub) => { handleUpdateContract({ ...selectedContract, workItems: updatedSub.workItems, progressPayments: updatedSub.progressPayments, documents: updatedSub.contractDocuments || [] }); }} /> : null;
      case 'payment-form': return selectedContract ? <ProgressPaymentForm subcontractor={{ ...subcontractors.find(s => s.id === selectedContract.subcontractorId)!, contractDate: selectedContract.contractDate, totalContractValue: selectedContract.totalValue, workItems: selectedContract.workItems, progressPayments: selectedContract.progressPayments, contractDocuments: selectedContract.documents }} onCancel={() => setActiveView('detail')} onSave={(p) => { setContracts(prev => prev.map(c => c.id === selectedContract.id ? { ...c, progressPayments: [...c.progressPayments, p] } : c)); setActiveView('detail'); }} /> : null;
      case 'reports': return <Reports subcontractors={subcontractors} transactions={transactions} contracts={contracts} projects={projects} onNewPayment={(id) => { setSelectedContractId(id); setActiveView('payment-form'); }} />;
      case 'settings': return <Settings onResetData={handleResetData} onImportData={handleImportData} allData={{ projects, subcontractors, contracts, transactions }} />;
      default: return <Dashboard subcontractors={subcontractors} projects={projects} contracts={contracts} transactions={transactions} />;
    }
  };

  const menuItems = [
    { id: 'dashboard', icon: LayoutGrid, label: 'Panel' },
    { id: 'projects', icon: Building2, label: 'Projeler' },
    { id: 'contract-summary', icon: ScrollText, label: 'İcmal' },
    { id: 'contracts', icon: FileEdit, label: 'Sözleşme' },
    { id: 'transactions', icon: Wallet, label: 'Kasa' },
    { id: 'reports', icon: PieChart, label: 'Analiz' },
    { id: 'settings', icon: SettingsIcon, label: 'Ayarlar' },
  ];

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row font-inter overflow-x-hidden">
      {/* Sidebar for Desktop */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-slate-900 text-white transform transition-transform duration-300 ease-in-out md:relative md:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 flex flex-col h-full">
          <div className="flex items-center gap-3 mb-10">
            <div className="bg-orange-600 p-2 rounded-xl shadow-lg shadow-orange-900/50">
              <HardHat className="w-6 h-6 text-white" />
            </div>
            <div>
              <h2 className="text-sm font-black uppercase tracking-tight leading-none">Ahmetoğlu</h2>
              <p className="text-[10px] font-bold text-orange-500 uppercase tracking-widest mt-1">Şantiye Pro</p>
            </div>
          </div>
          <nav className="flex-1 space-y-2">
            {menuItems.map((item) => (
              <button
                key={item.id}
                onClick={() => { setActiveView(item.id as any); setIsSidebarOpen(false); }}
                className={`w-full flex items-center gap-3 px-4 py-3.5 rounded-2xl transition-all group ${activeView === item.id ? 'bg-orange-600 text-white shadow-lg shadow-orange-900/20' : 'text-slate-400 hover:bg-white/5 hover:text-white'}`}
              >
                <item.icon className={`w-5 h-5 ${activeView === item.id ? 'scale-110' : 'group-hover:scale-110 transition-transform'}`} />
                <span className="text-xs font-black uppercase tracking-widest">{item.label}</span>
              </button>
            ))}
          </nav>
          <div className="mt-auto pt-6 border-t border-white/5 text-[10px] text-slate-500 font-bold uppercase tracking-widest text-center">
            v1.5.0 WEB EDITION
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-h-screen">
        <header className="md:hidden bg-white border-b border-slate-100 px-5 py-4 flex justify-between items-center sticky top-0 z-40">
          <div className="flex items-center gap-2">
            <HardHat className="w-5 h-5 text-orange-600" />
            <span className="font-black text-xs uppercase tracking-tight">Ahmetoğlu Şantiye</span>
          </div>
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 bg-slate-50 rounded-xl">
            {isSidebarOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
          </button>
        </header>

        {/* Top Desktop Header with Save Status */}
        <div className="hidden md:flex bg-white/60 backdrop-blur-md px-10 py-6 items-center justify-between border-b border-slate-100 sticky top-0 z-30">
          <div className="flex items-center gap-6">
            <h2 className="text-sm font-black text-slate-400 uppercase tracking-[0.3em]">Merkezi Yönetim Sistemi</h2>
            {saveStatus !== 'idle' && (
              <div className="flex items-center gap-2 px-4 py-2 bg-white rounded-full border border-slate-100 shadow-sm animate-in fade-in slide-in-from-top-2">
                <div className={`w-2 h-2 rounded-full ${saveStatus === 'saving' ? 'bg-blue-500 animate-pulse' : 'bg-emerald-500'}`} />
                <span className="text-[10px] font-black uppercase text-slate-500">
                  {saveStatus === 'saving' ? 'Senkronize Ediliyor' : 'Bulut Yedekleme Tamam'}
                </span>
              </div>
            )}
          </div>
          <div className="flex items-center gap-4">
            <div className="text-right">
              <p className="text-[10px] font-black text-slate-900 uppercase">{localStorage.getItem('user_name') || 'Yönetici'}</p>
              <p className="text-[8px] font-bold text-slate-400 uppercase">{localStorage.getItem('user_role') || 'Sistem Admin'}</p>
            </div>
            <div className="w-10 h-10 rounded-2xl bg-slate-900 flex items-center justify-center text-white font-black text-xs">
              {(localStorage.getItem('user_name') || 'Y').charAt(0)}
            </div>
          </div>
        </div>

        <main className="flex-1 p-5 md:p-10 overflow-y-auto w-full max-w-7xl mx-auto">
          {renderView()}
        </main>

        {/* Mobile Bottom Nav */}
        <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-white/80 backdrop-blur-2xl border-t border-slate-100 px-2 py-2 flex justify-between items-center z-40 shadow-[0_-10px_30px_rgba(0,0,0,0.05)]">
          {menuItems.slice(0, 5).map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveView(item.id as any)}
              className={`flex flex-col items-center justify-center flex-1 py-1 gap-1 transition-all ${activeView === item.id ? 'text-orange-600' : 'text-slate-400'}`}
            >
              <item.icon className={`w-5 h-5 ${activeView === item.id ? 'scale-110' : ''}`} />
              <span className="text-[8px] font-black uppercase tracking-widest">{item.label}</span>
            </button>
          ))}
        </nav>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Subcontractor, ProgressPayment, Contract } from '../types';
import { Search, FileText, Calendar, ArrowRight, Wallet, UserCircle, Download, FileSpreadsheet } from 'lucide-react';

interface AllPaymentsListProps {
  contracts: Contract[];
  subcontractors: Subcontractor[];
  onSelectContract: (id: string) => void;
}

const AllPaymentsList: React.FC<AllPaymentsListProps> = ({ contracts, subcontractors, onSelectContract }) => {
  const [searchTerm, setSearchTerm] = useState('');

  const allPayments = useMemo(() => {
    return contracts.flatMap(contract => {
      const sub = subcontractors.find(s => s.id === contract.subcontractorId);
      return contract.progressPayments.map(p => ({
        ...p,
        subName: sub?.name || 'Bilinmeyen Taşeron',
        subTrade: sub?.trade || 'Genel',
        contractTitle: contract.title,
        contractId: contract.id
      }));
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [contracts, subcontractors]);

  const filteredPayments = allPayments.filter(p => 
    p.subName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.contractTitle.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.number.toString().includes(searchTerm) ||
    new Date(p.date).toLocaleDateString('tr-TR').includes(searchTerm)
  );

  const handleExportAllToCSV = () => {
    if (allPayments.length === 0) return;

    // CSV Headers
    const headers = ["Tarih", "Taseron", "Sozlesme", "Hakedis No", "Durum", "Net Odenecek (TL)"];

    // Data Rows
    const rows = allPayments.map(p => [
      new Date(p.date).toLocaleDateString('tr-TR').replace(/\//g, '.'), // Standardize date format
      `"${p.subName.replace(/"/g, '""')}"`, // Escape quotes for CSV
      `"${p.contractTitle.replace(/"/g, '""')}"`,
      p.number,
      p.status === 'Approved' ? 'Onayli' : 'Beklemede',
      p.summary.netPayable.toFixed(2).replace('.', ',') // Locale-friendly decimal
    ]);

    // Construct CSV Content
    const csvContent = [headers, ...rows].map(e => e.join(";")).join("\n");

    // Add BOM for Excel UTF-8 support
    const blob = new Blob(["\ufeff" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);

    const link = document.createElement("a");
    const safeDate = new Date().toISOString().split('T')[0];
    link.setAttribute("href", url);
    link.setAttribute("download", `Tum_Hakedis_Icmali_${safeDate}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6 pb-24 animate-in fade-in duration-500">
      <div className="flex justify-between items-center px-1">
        <div>
          <h1 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Hakediş Kayıtları</h1>
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Şantiye Genel Ödeme Listesi</p>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={handleExportAllToCSV}
            className="bg-emerald-50 text-emerald-600 p-2.5 rounded-2xl shadow-sm border border-emerald-100 hover:bg-emerald-100 active:scale-90 transition-all no-print flex items-center gap-2 group"
            title="Tüm Listeyi Excel Olarak İndir"
          >
            <FileSpreadsheet className="w-5 h-5" />
            <span className="hidden md:inline text-[9px] font-black uppercase">Dışa Aktar</span>
          </button>
          <div className="bg-blue-600 text-white text-[10px] font-black px-4 py-2 rounded-2xl shadow-lg shadow-blue-200 uppercase tracking-widest flex items-center">
            {allPayments.length} Kayıt
          </div>
        </div>
      </div>

      <div className="relative no-print">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
        <input 
          type="text" 
          placeholder="Taşeron, hakediş no veya tarih..." 
          className="w-full pl-12 pr-4 py-4 bg-white border border-slate-200 rounded-[2rem] focus:outline-none focus:ring-2 focus:ring-blue-500 shadow-sm transition-all text-sm font-medium"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {filteredPayments.length === 0 ? (
        <div className="text-center py-20 bg-white rounded-[2.5rem] border border-dashed border-slate-200">
          <div className="bg-slate-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-4">
            <FileText className="text-slate-300 w-10 h-10" />
          </div>
          <p className="text-slate-400 text-sm font-bold uppercase tracking-widest">Kayıt Bulunamadı</p>
        </div>
      ) : (
        <div className="space-y-4">
          {filteredPayments.map((p) => (
            <button
              key={p.id}
              onClick={() => onSelectContract(p.contractId)}
