             />
             <button onClick={() => setActiveView('subcontractors')} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-bold">Geri Dön</button>
          </div>
        </div>
      );
      case 'detail': return selectedContract ? <SubcontractorDetail subcontractor={{ ...subcontractors.find(s => s.id === selectedContract.subcontractorId)!, contractDate: selectedContract.contractDate, totalContractValue: selectedContract.totalValue, workItems: selectedContract.workItems, progressPayments: selectedContract.progressPayments, contractDocuments: selectedContract.documents }} onBack={() => setActiveView('contract-summary')} onNewPayment={() => setActiveView('payment-form')} onApprovePayment={(pid) => handleApprovePayment(selectedContract.id, pid)} onUpdate={(updatedSub) => { handleUpdateContract({ ...selectedContract, workItems: updatedSub.workItems, progressPayments: updatedSub.progressPayments, documents: updatedSub.contractDocuments || [] }); }} /> : null;
      case 'payment-form': return selectedContract ? <ProgressPaymentForm subcontractor={{ ...subcontractors.find(s => s.id === selectedContract.subcontractorId)!, contractDate: selectedContract.contractDate, totalContractValue: selectedContract.totalValue, workItems: selectedContract.workItems, progressPayments: selectedContract.progressPayments, contractDocuments: selectedContract.documents }} onCancel={() => setActiveView('detail')} onSave={(p) => { setContracts(prev => prev.map(c => c.id === selectedContract.id ? { ...c, progressPayments: [...c.progressPayments, p] } : c)); setActiveView('detail'); }} /> : null;
